window.BANK['a7']['a7-1-1'] = [
  {"q":"كلمة <b>رجلٌ</b> اسم:","o":["مذكر حقيقي","مذكر مجازي","مؤنث حقيقي","مؤنث مجازي"],"a":0,"why":"رجل إنسان ذكر، ونقول: هذا رجل، فهو مذكر حقيقي، لأن المذكر الحقيقي هو ما دلّ على ذكر من الإنسان أو الحيوان.","ow":["","المجازي يدل على غير الإنسان والحيوان، ورجل إنسان.","رجل ذكر وليس أنثى، فلا يكون مؤنثًا.","رجل ليس مؤنثًا ولا مجازيًا لأنه إنسان ذكر."]},
  {"q":"كلمة <b>ظلٌّ</b> اسم:","o":["مذكر حقيقي","مؤنث حقيقي","مذكر مجازي","مؤنث مجازي"],"a":2,"why":"الظل ليس إنسانًا ولا حيوانًا، ونقول هذا ظل، فهو مذكر مجازي. والحقيقي يدل على ذكر من إنسان أو حيوان.","ow":["المذكر الحقيقي إنسان أو حيوان ذكر، والظل ليس كذلك.","المؤنث الحقيقي أنثى من الإنسان أو الحيوان، والظل ليس كذلك.","","الظل مذكر وليس مؤنثًا، فنقول هذا ظل."]},
  {"q":"كلمة <b>ناقةٌ</b> اسم:","o":["مذكر حقيقي","مؤنث حقيقي","مؤنث مجازي","مذكر مجازي"],"a":1,"why":"الناقة أنثى من الحيوان، فهي مؤنث حقيقي لأن المؤنث الحقيقي يدل على أنثى من الإنسان أو الحيوان، وفيها تاء مربوطة.","ow":["الناقة أنثى وليست ذكرًا، فلا تكون مذكرًا حقيقيًا.","","المؤنث المجازي يدل على غير الحي، والناقة حيوان حي.","الناقة مؤنث وليست مذكرًا، وهي حيوان حقيقي."]},
  {"q":"كلمة <b>شمسٌ</b> اسم:","o":["مؤنث حقيقي","مذكر حقيقي","مؤنث مجازي","مذكر مجازي"],"a":2,"why":"الشمس ليست إنسانًا ولا حيوانًا، ونقول هذه شمس، فهي مؤنث مجازي. وهي مؤنث معنوي لأنه لا علامة تأنيث فيها.","ow":["المؤنث الحقيقي أنثى من الإنسان أو الحيوان، والشمس ليست كذلك.","المذكر الحقيقي ذكر من إنسان أو حيوان، والشمس ليست كذلك.","","الشمس مؤنثة وليست مذكرة."]},
  {"q":"كلمة <b>خيرٌ</b> اسم:","o":["مذكر مجازي","مذكر حقيقي","مؤنث مجازي","مؤنث حقيقي"],"a":0,"why":"الخير ليس إنسانًا ولا حيوانًا، فهو مذكر مجازي، ونقول: هذا خير. وكذلك الأجر والماء والظل.","ow":["","المذكر الحقيقي يدل على ذكر حي، والخير ليس حيًّا.","المؤنث المجازي هو المؤنث غير الحي مثل شمس ودار.","المؤنث الحقيقي هو أنثى حية، والخير ليس كذلك."]},
  {"q":"المذكر المجازي هو ما دلّ على مذكر من:","o":["الإنسان فقط","الحيوان فقط","الإنسان والحيوان","غير الإنسان والحيوان"],"a":3,"why":"المذكر المجازي يدل على مذكر ليس إنسانًا ولا حيوانًا، مثل: ماء وظل وخير. ولهذا نقول مجازي لأنه ليس ذكرًا حقيقيًا.","ow":["الإنسان وحده ليس تعريف المجازي، فالمجازي غير حي.","الحيوان وحده ليس تعريف المجازي، فالمجازي غير حي.","الإنسان والحيوان معًا يدلان على المذكر الحقيقي.",""]},
  {"q":"من علامات التأنيث:","o":["التاء المربوطة","واو الجماعة","ألف الاثنين","ياء النسبة"],"a":0,"why":"من علامات التأنيث التاء المربوطة مثل فاطمة، والألف المقصورة مثل سلوى، والألف الممدودة مثل هيفاء.","ow":["","واو الجماعة تدل على الجمع وليست علامة تأنيث.","ألف الاثنين تدل على المثنى وليست علامة تأنيث.","ياء النسبة تدل على النسبة وليست علامة تأنيث."]},
  {"q":"علامة التأنيث في كلمة <b>هيفاء</b>:","o":["التاء المربوطة","الألف المقصورة","الألف الممدودة","لا علامة"],"a":2,"why":"هيفاء تنتهي بألف بعدها همزة، وهي الألف الممدودة، وهي إحدى علامات التأنيث الثلاث في آخر الاسم.","ow":["التاء المربوطة تكون مثل فاطمة، وهيفاء لا تنتهي بها.","الألف المقصورة تكون بلا همزة مثل سلمى.","","في هيفاء علامة تأنيث ظاهرة هي الألف الممدودة."]},
  {"q":"علامة التأنيث في كلمة <b>سلمى</b>:","o":["الألف المقصورة","الألف الممدودة","التاء المربوطة","لا علامة"],"a":0,"why":"سلمى تنتهي بألف مقصورة، أي ألف في آخر الكلمة بلا همزة بعدها، وهي إحدى علامات التأنيث.","ow":["","الألف الممدودة يكون بعدها همزة مثل هيفاء.","التاء المربوطة تكون مثل فاطمة، وسلمى لا تنتهي بها.","في سلمى علامة تأنيث ظاهرة هي الألف المقصورة."]},
  {"q":"علامة التأنيث في كلمة <b>فاطمة</b>:","o":["الألف المقصورة","التاء المربوطة","الألف الممدودة","لا علامة"],"a":1,"why":"فاطمة تنتهي بتاء مربوطة، وهي إحدى علامات التأنيث الثلاث، فتجعل الاسم مؤنثًا لفظيًا لأن العلامة ظاهرة فيه.","ow":["الألف المقصورة تكون مثل سلمى، وفاطمة لا تنتهي بها.","","الألف الممدودة تكون مثل هيفاء، وفاطمة لا تنتهي بها.","في فاطمة علامة تأنيث ظاهرة هي التاء المربوطة."]},
  {"q":"المؤنث اللفظي هو الاسم الذي:","o":["ينتهي بعلامة تأنيث","يخلو من علامة التأنيث","يدل على مذكر فقط","يدل على حرف"],"a":0,"why":"المؤنث اللفظي هو الاسم الذي ينتهي بعلامة تأنيث ظاهرة، مثل: فاطمة بتاء مربوطة وسلمى وهيفاء.","ow":["","الاسم الذي يخلو من علامة التأنيث هو المؤنث المعنوي.","اللفظي لا يدل على المذكر فقط، بل ينتهي بعلامة تأنيث.","اللفظي ليس حرفًا، بل اسم فيه علامة تأنيث."]},
  {"q":"المؤنث المعنوي هو الاسم المؤنث الذي:","o":["ينتهي بتاء مربوطة","ينتهي بألف ممدودة","يخلو من علامة التأنيث","ينتهي بألف مقصورة"],"a":2,"why":"المؤنث المعنوي هو الاسم المؤنث الذي لا توجد في آخره علامة تأنيث ظاهرة، مثل: هند وزينب وشمس.","ow":["الذي ينتهي بتاء مربوطة هو المؤنث اللفظي.","الذي ينتهي بألف ممدودة هو المؤنث اللفظي.","","الذي ينتهي بألف مقصورة هو المؤنث اللفظي."]},
  {"q":"اسم <b>هند</b> مؤنث:","o":["مجازي لفظي","حقيقي لفظي","مجازي معنوي","حقيقي معنوي"],"a":3,"why":"هند إنسان أنثى، فهي مؤنث حقيقي، وليس في آخرها علامة تأنيث، فهي معنوي. فنقول: مؤنث حقيقي معنوي.","ow":["مجازي لفظي غير صحيح، فهند إنسان وليست علامة تأنيث ظاهرة فيها.","مجازي معنوي غير صحيح، فهند إنسان حي.","حقيقي لفظي غير صحيح، لأن هند ليس في آخرها علامة تأنيث ظاهرة.",""]},
  {"q":"اسم <b>طلحة</b> مذكر حقيقي وتلحقه تاء التأنيث، ويسمى:","o":["مؤنثًا لفظيًا","مؤنثًا معنويًا","مذكرًا مجازيًا","جمعًا"],"a":0,"why":"طلحة مذكر حقيقي لأنه اسم رجل، لكنه ينتهي بتاء التأنيث، فنسميه مؤنثًا لفظيًا لوجود علامة التأنيث فيه.","ow":["","المؤنث المعنوي هو الذي لا علامة تأنيث فيه، وطلحة فيه تاء مربوطة.","طلحة اسم إنسان فلا يكون مذكرًا مجازيًا.","طلحة ليست جمعًا، بل اسم مفرد."]},
  {"q":"كلمة <b>مدينةٌ</b> اسم مؤنث:","o":["حقيقي لفظي","حقيقي معنوي","مجازي معنوي","مجازي لفظي"],"a":3,"why":"مدينة ليست إنسانًا ولا حيوانًا فهي مجازي، وفيها تاء مربوطة وهي علامة ظاهرة فهي لفظي. فنقول: مؤنث مجازي لفظي.","ow":["الحقيقي يدل على إنسان أو حيوان، والمدينة ليست كذلك.","مجازي معنوي يخلو من علامة التأنيث، والمدينة فيها تاء مربوطة.","المؤنث الحقيقي لا يصح هنا لأن المدينة ليست إنسانًا ولا حيوانًا.",""]},
  {"q":"العبارة: المذكر الحقيقي ما دلّ على ذكر من إنسان أو حيوان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمذكر الحقيقي ما دلّ على ذكر من الإنسان أو الحيوان، مثل: رجل وأب وأسد وجمل.","ow":["","العبارة صحيحة، فهذا تعريف المذكر الحقيقي."]},
  {"q":"العبارة: كلمة <b>دار</b> مؤنث مجازي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فدار ليست إنسانًا ولا حيوانًا، وهي مؤنثة، فنقول: هذه دار، فهي مؤنث مجازي.","ow":["","دار مؤنثة ومجازية، فلا تصح العبارة التي تنفي ذلك."]},
  {"q":"العبارة: كلمة <b>حمزة</b> مؤنث حقيقي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فحمزة اسم رجل أي مذكر حقيقي، لكنه ينتهي بتاء مربوطة فيسمى مؤنثًا لفظيًا، وليس مؤنثًا حقيقيًا.","ow":["حمزة ليس مؤنثًا حقيقيًا لأن المؤنث الحقيقي يدل على أنثى.",""]},
  {"q":"العبارة: كلمة <b>جمل</b> مذكر مجازي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالجمل حيوان ذكر، فهو مذكر حقيقي وليس مجازيًا، لأن المجازي يدل على غير الإنسان والحيوان.","ow":["الجمل حيوان ذكر، فلا يكون مذكرًا مجازيًا.",""]},
  {"q":"العبارة: كلمة <b>مريم</b> مؤنث معنوي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمريم إنسان أنثى فهي مؤنث حقيقي، وليس في آخرها علامة تأنيث ظاهرة، فهي مؤنث معنوي.","ow":["","العبارة صحيحة، فمريم لا علامة تأنيث ظاهرة فيها."]},
];
window.BANK['a7']['a7-1-2'] = [
  {"q":"الأمر طلب وقوع الفعل من:","o":["الغائب","الفاعل المخاطب","المتكلم","الجماد"],"a":1,"why":"الأمر هو طلب وقوع الفعل من الفاعل المخاطب، أي من الشخص الذي نكلمه ويسمعنا مباشرة، مثل: اترُكْ.","ow":["الغائب لا نخاطبه مباشرة، فالأمر يوجه للمخاطب.","","المتكلم لا يأمر نفسه بهذا المعنى، فالأمر للمخاطب.","الجماد لا يفهم الأمر، فالأمر يوجه للفاعل المخاطب."]},
  {"q":"أي الأفعال الآتية فعل ماضٍ؟","o":["يترقبُ","اتركْ","خرجَ","يأتمرون"],"a":2,"why":"خرجَ فعل ماضٍ لأنه يدل على حدث وقع وانتهى. أما يترقبُ ويأتمرون فمضارعان، واتركْ أمر.","ow":["يترقبُ فعل مضارع يدل على الحاضر أو المستقبل.","اتركْ فعل أمر يطلب من المخاطب أن يترك.","","يأتمرون فعل مضارع مسبوق بالياء وواو الجماعة."]},
  {"q":"أي الأفعال الآتية فعل مضارع؟","o":["يترقبُ","اخرجْ","استأجرتُ","خرجَ"],"a":0,"why":"يترقبُ فعل مضارع يبدأ بالياء، ويدل على حدث يقع الآن أو سيقع، فهو من الأفعال المضارعة.","ow":["","اخرجْ فعل أمر يطلب وقوع الفعل.","استأجرتُ فعل ماضٍ لأن الحدث انتهى.","خرجَ فعل ماضٍ لأن الحدث انتهى."]},
  {"q":"فعل الأمر من الأفعال الآتية هو:","o":["خرجَ","يترقبُ","استأجرتُ","اخرجْ"],"a":3,"why":"اخرجْ فعل أمر لأنه يطلب من المخاطب أن يخرج. أما خرجَ فماضٍ، ويترقبُ مضارع، واستأجرتُ ماضٍ.","ow":["خرجَ فعل ماضٍ لأن الحدث انتهى.","يترقبُ فعل مضارع يدل على الحاضر أو المستقبل.","استأجرتُ فعل ماضٍ، لأنه حدث انتهى، والتاء ضمير الفاعل.",""]},
  {"q":"من صيغ الأمر:","o":["الفعل الماضي","الفعل المضارع المقترن بلام الأمر","الاسم المنصوب","حرف الجر"],"a":1,"why":"للأمر صيغتان: فعل الأمر نفسه، والفعل المضارع المقترن بلام الأمر الجازمة، مثل لِتَخرُجْ.","ow":["الفعل الماضي لا يصلح أن يكون صيغة أمر.","","الاسم المنصوب ليس من صيغ الأمر.","حرف الجر ليس من صيغ الأمر."]},
  {"q":"الفعل المضارع المقترن بلام الأمر في الأمثلة الآتية:","o":["اخرُجْ","تخرُجُ","لِتَخرُجْ","خرجَ"],"a":2,"why":"لِتَخرُجْ فعل مضارع تخرجُ سبقته لام الأمر الجازمة، فهو مضارع مقترن بلام الأمر. أما اخرُجْ فأمر مباشر.","ow":["اخرُجْ فعل أمر مباشر وليس مضارعًا مقترنًا باللام.","تخرُجُ فعل مضارع بلا لام أمر فهو خبر وليس أمرًا.","","خرجَ فعل ماضٍ، يدل على حدث انتهى وليس طلبًا."]},
  {"q":"الصيغة الثانية للأمر من الفعل <b>اخرُجْ</b>:","o":["لِتَخرُجْ","يخرُجُ","خرجَ","خارجٌ"],"a":0,"why":"نحوّل اخرُجْ إلى المضارع المبدوء بتاء تخرجُ، ثم نضع قبله لام الأمر ونجزمه بالسكون فيصبح لِتَخرُجْ.","ow":["","يخرُجُ مضارع بلا لام أمر فهو خبر.","خرجَ فعل ماضٍ ولا يصلح صيغة أمر.","خارجٌ اسم فاعل وليس فعلًا."]},
  {"q":"عند اقتران المضارع بلام الأمر يُجزم آخره بـ:","o":["الضمة","السكون","الفتحة","الكسرة"],"a":1,"why":"الفعل المضارع بعد لام الأمر يُجزم، وعلامة جزمه السكون على آخره، مثل: لِتَخرُجْ، فالجيم ساكنة.","ow":["الضمة علامة رفع المضارع الأصلية وليست جزمًا.","","الفتحة علامة نصب المضارع، وليست جزمًا.","الكسرة ليست علامة جزم المضارع هنا."]},
  {"q":"خطوات تحويل فعل الأمر إلى المضارع المقترن بلام الأمر: الخطوة الأولى:","o":["نضيف اللام","نبدأ بالمضارع المبدوء بتاء","نكتب فعل الأمر","نحذف آخر الفعل"],"a":2,"why":"عند تحويل فعل الأمر إلى المضارع المقترن بلام الأمر نبدأ أولًا بكتابة فعل الأمر مثل اخرُجْ، ثم نكمل بقية الخطوات.","ow":["إضافة اللام تأتي في آخر الخطوات وليست الأولى.","المضارع المبدوء بتاء ننتقل إليه بعد كتابة فعل الأمر.","","لا نحذف آخر الفعل، بل نحول إلى المضارع المبدوء بتاء."]},
  {"q":"المضارع المبدوء بتاء من فعل الأمر <b>استأجِرْ</b>:","o":["يستأجرُ","استأجرتُ","استأجرَ","تستأجِرُ"],"a":3,"why":"من فعل الأمر استأجِرْ نأخذ المضارع المبدوء بتاء وهو تستأجرُ، ثم نضع قبله لام الأمر ونجزمه.","ow":["يستأجرُ مضارع للغائب وليس مبدوءًا بتاء.","استأجرتُ فعل ماضٍ.","استأجرَ فعل ماضٍ.",""]},
  {"q":"يخرج الأمر عن معناه إلى الدعاء إذا وُجّه إلى:","o":["الله جلّ جلاله","الصديق","المعلم","الأب"],"a":0,"why":"إذا وُجّه الأمر إلى الله جل جلاله خرج عن معناه الأصلي إلى الدعاء، لأننا نحن العباد ندعو الله ولا نأمره.","ow":["","الصديق يمكن أن نأمره أمرًا حقيقيًا.","المعلم يمكن أن نطلب منه، ولا يكون هذا دعاء كما في حق الله.","الأب يمكن أن نخاطبه بالأمر الحقيقي في حدود الأدب."]},
  {"q":"في قولنا <b>ربِّ اغفرْ وارحمْ</b> خرج الأمر إلى:","o":["التهديد","الدعاء","النصح","الطلب من مخلوق"],"a":1,"why":"في ربِّ اغفرْ وارحمْ الأمر موجّه إلى الله جل جلاله، فخرج إلى الدعاء، لأننا نطلب منه المغفرة والرحمة ولا نأمره.","ow":["التهديد يكون لمن هو أضعف منك ويُخشى أذاه، وليس في دعاء الله.","","النصح يكون للمخلوقين، وهذا الكلام موجه إلى الله.","الطلب من مخلوق لا يصح هنا لأن الكلام موجّه إلى الله."]},
  {"q":"الأسلوب الذي يبدأ بفعل أمر يسمى أسلوب:","o":["استفهام","نداء","طلب","نفي"],"a":2,"why":"الأسلوب الذي يبدأ بفعل أمر يسمى أسلوب طلب، لأننا نطلب فيه من المخاطب أن يفعل شيئًا.","ow":["الاستفهام أسلوب للسؤال بأدوات مثل هل.","النداء أسلوب يبدأ بحرف نداء مثل يا.","","النفي أسلوب يبدأ بأدوات نفي مثل لم ولا."]},
  {"q":"فعل الأمر من الفعل <b>تركَ</b>:","o":["يترُكُ","تاركٌ","تُركَ","اترُكْ"],"a":3,"why":"فعل الأمر من الفعل تركَ هو اترُكْ، أي نطلب من المخاطب أن يترك الشيء، وهو يبدأ بهمزة وصل.","ow":["يترُكُ فعل مضارع، وليس أمرًا.","تاركٌ اسم فاعل، وليس فعل أمر.","تُرِكَ فعل ماضٍ مبني للمجهول.",""]},
  {"q":"أي الكلمات الآتية ليست فعل أمر؟","o":["استأجرتُ","اتركْ","اخرجْ","استأجرْهُ"],"a":0,"why":"استأجرتُ فعل ماضٍ لأن الحدث انتهى، والتاء ضمير الفاعل، فليس فعل أمر. أما اتركْ واخرجْ واستأجرْهُ فأفعال أمر.","ow":["","اتركْ فعل أمر يطلب من المخاطب الترك.","اخرجْ فعل أمر يطلب من المخاطب الخروج.","استأجرْهُ فعل أمر يطلب من المخاطب الاستئجار."]},
  {"q":"العبارة: الأمر هو طلب وقوع الفعل من الفاعل المخاطب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأمر هو طلب وقوع الفعل من الفاعل المخاطب، مثل: اترُكْ واخرُجْ واستأجِرْ.","ow":["","العبارة صحيحة، فهذا هو تعريف الأمر."]},
  {"q":"العبارة: <b>استأجرتُ</b> فعل أمر.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فاستأجرتُ فعل ماضٍ لأن الحدث انتهى والتاء ضمير الفاعل، وليس فعل أمر.","ow":["استأجرتُ ليست أمرًا، لأن الأمر يطلب ولا يخبر عن حدث انتهى.",""]},
  {"q":"العبارة: <b>لِتَستأجِرْ</b> مضارع مقترن بلام الأمر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فلِتَستأجِرْ مضارع تستأجرُ سبقته لام الأمر الجازمة فجُزم بالسكون.","ow":["","العبارة صحيحة، فهذه هي الصيغة الثانية للأمر."]},
  {"q":"العبارة: الأمر الموجه إلى الله يسمى أمرًا حقيقيًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالأمر الموجه إلى الله لا يسمى أمرًا حقيقيًا، بل يخرج إلى معنى الدعاء، لأن العبد لا يأمر ربه.","ow":["الأمر الموجه إلى الله يخرج إلى الدعاء ولا يكون أمرًا حقيقيًا.",""]},
  {"q":"العبارة: <b>يترقبُ</b> فعل ماضٍ.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فيترقبُ فعل مضارع لأنه يبدأ بالياء ويدل على الحاضر أو المستقبل، وليس فعلًا ماضيًا.","ow":["يترقبُ مضارع وليس ماضيًا لأن الماضي حدث انتهى.",""]},
];
window.BANK['a7']['a7-1-3'] = [
  {"q":"همزة الوصل تُنطق:","o":["دائمًا","عند ابتداء الكلام ولا تُنطق عند وصلها بما قبلها","في آخر الكلمة فقط","لا تُنطق أبدًا"],"a":1,"why":"همزة الوصل تُنطق عند ابتداء الكلام، ولا تُنطق إذا وصلنا الكلمة بما قبلها، وهذا هو تعريفها.","ow":["همزة الوصل لا تُنطق دائمًا، بل في الابتداء فقط.","","همزة الوصل ليست في آخر الكلمة، بل في أولها.","همزة الوصل تُنطق في بدء الكلام، فلا تقل إنها لا تُنطق أبدًا."]},
  {"q":"كيف تُكتب همزة الوصل؟","o":["ألفًا فوقها همزة","ألفًا تحتها همزة","ألفًا دون رأس عين","واوًا"],"a":2,"why":"استفهمَ فعل ماضٍ سداسي أي من ستة أحرف، وكل ماضٍ سداسي همزته همزة وصل، تُنطق في الابتداء وتسقط عند الوصل.","ow":["الألف الذي فوقها همزة هي همزة القطع.","الألف الذي تحتها همزة هي همزة القطع المكسورة.","","الواو ليست رسم همزة الوصل."]},
  {"q":"أي الكلمات الآتية همزتها همزة وصل؟","o":["استفهمَ","أمرٌ","أبٌ","أخٌ"],"a":0,"why":"استفهمَ فعل ماضٍ سداسي، وكل ماضٍ سداسي همزته همزة وصل. أما أمرٌ وأبٌ وأخٌ فهمزاتها قطع.","ow":["","أمرٌ همزتها همزة قطع.","أبٌ همزتها همزة قطع.","أخٌ همزتها همزة قطع."]},
  {"q":"أمر الفعل الثلاثي <b>خرجَ</b>:","o":["أخرِجْ","خارجٌ","يخرجُ","اُخرُجْ"],"a":3,"why":"خرجَ فعل ثلاثي، وأمر الفعل الثلاثي يبدأ بهمزة وصل، فنقول: اُخرُجْ، وتُكتب الهمزة ألفًا دون رأس عين.","ow":["أخرِجْ أمر من أخرجَ الرباعي وليس من خرجَ.","خارجٌ اسم فاعل وليس أمرًا.","يخرجُ فعل مضارع وليس أمرًا.",""]},
  {"q":"أمر الفعل الثلاثي <b>علِمَ</b>:","o":["اِعلَمْ","أعلِمْ","عالِمٌ","يعلمُ"],"a":0,"why":"علِمَ فعل ثلاثي أي من ثلاثة أحرف، وأمر الفعل الثلاثي يبدأ بهمزة وصل، فأمر علِمَ هو: اِعلَمْ.","ow":["","أعلِمْ أمر من أعلمَ الرباعي وليس من علمَ.","عالِمٌ اسم فاعل وليس فعل أمر.","يعلمُ فعل مضارع وليس أمرًا."]},
  {"q":"الفعل <b>ائتمرَ</b> فعل ماضٍ:","o":["ثلاثي","خماسي","سداسي","رباعي"],"a":1,"why":"ائتمرَ حروفه ا ء ت م ر أي خمسة أحرف، فهو فعل خماسي، وكل ماضٍ خماسي همزته همزة وصل.","ow":["الثلاثي ثلاثة أحرف، وائتمر أكثر.","","السداسي ستة أحرف، وائتمر خمسة.","الرباعي أربعة أحرف، وائتمر خمسة."]},
  {"q":"الفعل <b>انكسرَ</b> فعل ماضٍ:","o":["ثلاثي","سداسي","خماسي","رباعي"],"a":2,"why":"انكسرَ حروفه ا ن ك س ر أي خمسة أحرف، فهو فعل خماسي، وكل ماضٍ خماسي همزته همزة وصل.","ow":["الثلاثي ثلاثة أحرف، وانكسر أكثر.","السداسي ستة أحرف، وانكسر خمسة.","","الرباعي أربعة أحرف، وانكسر خمسة."]},
  {"q":"الفعل <b>استفهمَ</b> فعل ماضٍ:","o":["ثلاثي","خماسي","رباعي","سداسي"],"a":3,"why":"استفهمَ حروفه ا س ت ف ه م أي ستة أحرف، فهو فعل سداسي، وكل ماضٍ سداسي همزته همزة وصل.","ow":["الثلاثي ثلاثة أحرف، واستفهم أكثر.","الخماسي خمسة أحرف، واستفهم ستة.","الرباعي أربعة أحرف، واستفهم ستة.",""]},
  {"q":"أمر الفعل الخماسي <b>انكسرَ</b>:","o":["انكسِرْ","كسِّرْ","أنكِرْ","اكسِرْ"],"a":0,"why":"أمر الفعل الخماسي انكسرَ هو انكسِرْ، ويبدأ بهمزة وصل مثل الماضي، وتسقط الهمزة عند وصله بما قبله.","ow":["","كسِّرْ أمر من كسَّرَ وليس من انكسرَ.","أنكِرْ أمر من أنكرَ وليس من انكسرَ.","اكسِرْ أمر من كسرَ الثلاثي وليس من انكسرَ."]},
  {"q":"مصدر الفعل <b>استفهمَ</b>:","o":["استفهِمْ","استفهام","فاهمٌ","يستفهمُ"],"a":1,"why":"مصدر الفعل السداسي استفهمَ هو استفهام، وهمزته همزة وصل مثل همزة الماضي، وتُكتب ألفًا دون رأس عين.","ow":["استفهِمْ فعل أمر وليس مصدرًا.","","فاهمٌ اسم فاعل من فهمَ.","يستفهمُ فعل مضارع وليس مصدرًا."]},
  {"q":"مصدر الفعل <b>ائتمرَ</b>:","o":["ائتمِرْ","مؤتمِرٌ","ائتمار","يأتمرُ"],"a":2,"why":"مصدر الفعل الخماسي ائتمرَ هو ائتمار، وهمزته همزة وصل مثل همزة الماضي، وتُكتب ألفًا دون رأس عين.","ow":["ائتمِرْ فعل أمر وليس مصدرًا.","مؤتمِرٌ اسم فاعل وليس مصدرًا.","","يأتمرُ فعل مضارع وليس مصدرًا."]},
  {"q":"أي الأسماء الآتية همزته همزة وصل؟","o":["أخ","أب","أمّ","اسم"],"a":3,"why":"اسم من الأسماء السماعية التي تبدأ بهمزة وصل، أي حفظناها عن العرب. أما أخ وأب وأم فهمزاتها قطع.","ow":["أخ همزتها همزة قطع.","أب همزتها همزة قطع.","أمّ همزتها همزة قطع.",""]},
  {"q":"من الأسماء التي تبدأ بهمزة وصل:","o":["امرأة","أرض","أسد","أمل"],"a":0,"why":"امرأة من الأسماء السماعية التي تبدأ بهمزة وصل، فنكتبها ألفًا دون رأس عين. أما أرض وأسد وأمل فهمزاتها قطع.","ow":["","أرض همزتها همزة قطع.","أسد همزتها همزة قطع.","أمل همزتها همزة قطع."]},
  {"q":"همزة (ال) التعريف في كلمة <b>الكتاب</b> همزة:","o":["قطع","وصل","متوسطة","متطرفة"],"a":1,"why":"همزة ال التعريف في الكتاب همزة وصل، فلا تُنطق إذا وصلناها بما قبلها، فنقول: قرأتُ الكتاب بلا همزة.","ow":["همزة القطع تُنطق دائمًا، وهمزة ال لا تُنطق عند الوصل.","","الهمزة المتوسطة في وسط الكلمة، وهمزة ال في أولها.","الهمزة المتطرفة في آخر الكلمة، وهمزة ال في أولها."]},
  {"q":"عدد مواضع همزة الوصل التي درسناها:","o":["ثلاثة","خمسة","أربعة","ستة"],"a":2,"why":"مواضع همزة الوصل التي درسناها أربعة: أمر الثلاثي، وماضي الخماسي والسداسي وأمرهما ومصدرهما، والأسماء السماعية، وال التعريف.","ow":["عدد المواضع أكثر من ثلاثة.","عدد المواضع أربعة وليس خمسة.","","عدد المواضع أربعة وليس ستة."]},
  {"q":"العبارة: همزة الوصل تُنطق عند وصل الكلمة بما قبلها.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فهمزة الوصل لا تُنطق إذا وصلنا الكلمة بما قبلها، وإنما تُنطق عند ابتداء الكلام فقط.","ow":["همزة الوصل تسقط عند الوصل، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: <b>ابن</b> اسم تبدأ همزته همزة وصل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فابن من الأسماء السماعية التي تبدأ بهمزة وصل، فنكتبها ألفًا دون رأس عين.","ow":["","العبارة صحيحة، فهمزة ابن همزة وصل وليست قطعًا."]},
  {"q":"العبارة: <b>أخٌ</b> تبدأ بهمزة وصل.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فأخٌ همزتها همزة قطع، فتُنطق دائمًا وتُكتب أ، وليست من الأسماء التي همزتها وصل.","ow":["أخ ليست من الأسماء السماعية التي همزتها وصل.",""]},
  {"q":"العبارة: همزة (ال) التعريف همزة وصل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فهمزة ال التعريف همزة وصل، مثل: المدينة والكتاب، فلا تُنطق عند الوصل.","ow":["","العبارة صحيحة، فال التعريف همزتها وصل."]},
  {"q":"العبارة: <b>استأجرَ</b> فعل ماضٍ سداسي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فاستأجرَ فيه ستة أحرف هي: ا س ت أ ج ر، فهو فعل ماضٍ سداسي، وهمزته همزة وصل.","ow":["","العبارة صحيحة، فهو سداسي وليس خماسيًا."]},
];
window.BANK['a7']['a7-1-4'] = [
  {"q":"أي الآتي من الخطوط العربية؟","o":["الرقعة","الإنجليزي","اللاتيني","الرومي"],"a":0,"why":"الرقعة من الخطوط العربية، وهي خط بسيط وسريع بلا حلية. أما الإنجليزي واللاتيني والرومي فليست خطوطًا عربية.","ow":["","الإنجليزي خط لغة أخرى.","اللاتيني خط لغة أخرى.","الرومي ليس خطًا عربيًا من الخطوط المذكورة."]},
  {"q":"الخط الذي لا توجد فيه حلية من الخطين المدروسين هو:","o":["النسخ","الرقعة","كلاهما","لا شيء"],"a":1,"why":"الرقعة لا حلية فيها لأنها خط بسيط وسريع، أما النسخ ففيه حلية، فالحلية في النسخ وحده.","ow":["النسخ فيه حلية.","","الحلية في الجدول للنسخ فقط، فلا يصح أن في كليهما.","يوجد فرق بين الخطين، فلا يصح أنه لا شيء."]},
  {"q":"النقطتان في خط الرقعة:","o":["منفردتان","غائبتان","مرسومتان بالألوان","متصلتان"],"a":3,"why":"النقطتان في خط الرقعة متصلتان، أما في النسخ فهما منفصلتان من غير طمس، وهذا من الفروق بين الخطين.","ow":["المنفردتان صفة خط النسخ.","النقطتان لا تغيبان في الرقعة، بل تكتبان متصلتين.","الألوان لا علاقة لها بالفرق بين الخطين.",""]},
  {"q":"رأس الحرف في خط الرقعة:","o":["مطموس","غير مطموس","محذوف","مزخرف"],"a":0,"why":"رأس الحرف في خط الرقعة مطموس، أما في النسخ فرأس الحرف غير مطموس، وهذا فرق بين الخطين.","ow":["","غير مطموس صفة خط النسخ.","رأس الحرف لا يُحذف في الرقعة، بل يكون مطموسًا.","الزخرفة ليست من صفات الرقعة، فالرقعة بسيطة."]},
  {"q":"الصعود في خط النسخ يكون:","o":["بزاوية قائمة","بدوران","أفقيًا","بخط متقطع"],"a":1,"why":"الصعود في خط النسخ يكون بدوران، أما في الرقعة فبزاوية قائمة، وهذا من الفروق بين الخطين.","ow":["الزاوية القائمة صفة الرقعة وليس النسخ.","","الصعود في النسخ ليس أفقيًا، بل بدوران.","الخط المتقطع ليس صفة الصعود في النسخ."]},
  {"q":"يتميز خط النسخ عن الرقعة بوجود:","o":["زاوية قائمة","نقطتين متصلتين","حلية","رأس مطموس"],"a":2,"why":"خط النسخ فيه حلية، أما الرقعة فلا حلية فيها، فالحلية هي ما يميز النسخ عن الرقعة في هذه النقطة.","ow":["الزاوية القائمة تميز الرقعة وليس النسخ.","النقطتان المتصلتان تميزان الرقعة.","","رأس الحرف المطموس يميز الرقعة."]},
  {"q":"أشكال الحرف في خط الرقعة هي:","o":["مطموسة منفردة ومطموسة في البدء والوسط والتطرف","مفتوحة فقط","مزخرفة فقط","متقطعة"],"a":0,"why":"في خط الرقعة تكون الحروف مطموسة الرأس سواء كانت منفردة أو في البدء أو الوسط أو التطرف، وهذه إحدى صفاته.","ow":["","الرقعة ليست مفتوحة فقط، فرأس الحرف فيها مطموس.","الرقعة بسيطة وليست مزخرفة فقط.","الرقعة خط متصل وليس متقطعًا."]},
  {"q":"الألف في خط الرقعة خط:","o":["أفقي","مقوّس","عمودي طويل مائل قليلًا إلى اليمين","منحنٍ"],"a":2,"why":"الألف في الرقعة خط عمودي طويل يميل قليلًا إلى اليمين، فلا نكتبه أفقيًا ولا مقوّسًا.","ow":["الأفقي تُكتب به حروف مثل الباء والتاء.","المقوّس تُكتب به حروف مثل العين والقاف.","","المنحني ليس شكل الألف في الرقعة."]},
  {"q":"الحرف الذي يُكتب بخط مقوّس من الحروف الآتية:","o":["ب","ت","ص","ع"],"a":3,"why":"العين من الحروف التي تُكتب بخط مقوّس، مثل الحاء والقاف. أما الباء والتاء والصاد فتُكتب بخط أفقي.","ow":["الباء تُكتب بخط أفقي.","التاء تُكتب بخط أفقي.","الصاد تُكتب بخط أفقي.",""]},
  {"q":"الحرف الذي يُكتب بخط أفقي من الحروف الآتية:","o":["ب","ح","ق","ع"],"a":0,"why":"الباء من الحروف التي تُكتب بخط أفقي مثل التاء والصاد. أما الحاء والقاف والعين فبخط مقوّس.","ow":["","الحاء تُكتب بخط مقوّس.","القاف تُكتب بخط مقوّس.","العين تُكتب بخط مقوّس."]},
  {"q":"يُمسك القلم أثناء الكتابة بين:","o":["السبابة والإبهام مستندًا على الوسطى","الخنصر والبنصر","الكف كلها","الوسطى فقط"],"a":0,"why":"يوضع القلم بين السبابة والإبهام مستندًا على الوسطى، وهذه هي الطريقة الصحيحة لمسك القلم.","ow":["","الخنصر والبنصر ليسا الإصبعين اللذين نمسك بهما القلم.","الكف كلها ليست طريقة صحيحة لإمساك القلم.","الوسطى وحدها لا تكفي لإمساك القلم."]},
  {"q":"تجنّب أثناء الكتابة:","o":["الجلسة الصحيحة","القبض بشدة على القلم","إبعاد الورقة عن العين","الإضاءة الجيدة"],"a":1,"why":"نتجنب أثناء الكتابة القبض بشدة على القلم، لأنه يتعب اليد ويضر جمال الخط، أما الباقي فمطلوب أثناء الكتابة.","ow":["الجلسة الصحيحة مطلوبة وليست مما نتجنبه.","","إبعاد الورقة عن العين مطلوب وليس مما نتجنبه.","الإضاءة الجيدة مطلوبة وليست مما نتجنبه."]},
  {"q":"المسافة بين الورقة والعين أثناء الكتابة:","o":["10 سم","20 سم","30 سم","5 سم"],"a":2,"why":"المسافة بين الورقة والعين أثناء الكتابة 30 سم، كما ورد في الكتاب، لحماية العين وتحسين الجلسة.","ow":["10 سم قريبة جدًا من العين.","20 سم ليست المسافة التي حدّدها الكتاب.","","5 سم قريبة جدًا من العين."]},
  {"q":"عن الخط الحسن قيل إنه:","o":["يخفي الحق","يزيد الحق وضوحًا","لا فائدة منه","يزيد الكلام طولًا"],"a":1,"why":"قيل إن الخط الحسن يزيد الحق وضوحًا، أي أن الكلام الصحيح إذا كُتب بخط جميل بان أكثر. وهذا يبيّن أهمية الخط الحسن.","ow":["الخط الحسن لا يخفي الحق، بل يوضحه.","","للخط الحسن فائدة كبيرة وليس بلا فائدة.","الخط الحسن لا يزيد طول الكلام، بل يزيده وضوحًا."]},
  {"q":"خط الرقعة خط:","o":["بسيط وسريع لا حلية فيه","مزخرف بالحلية","غير مستخدم","للمصاحف فقط"],"a":0,"why":"خط الرقعة خط بسيط وسريع لا حلية فيه، ولذلك نكتب به في المدرسة غالبًا. أما الحلية ففي خط النسخ.","ow":["","الحلية في النسخ وليست في الرقعة.","الرقعة مستخدمة في الكتابة اليومية، فليست غير مستخدمة.","الرقعة ليست للمصاحف فقط، بل للكتابة السريعة."]},
  {"q":"العبارة: في خط النسخ حلية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالحلية توجد في خط النسخ ولا توجد في خط الرقعة، وهذا من الفروق بين الخطين.","ow":["","العبارة صحيحة، فالنسخ فيه حلية."]},
  {"q":"العبارة: الصعود في خط الرقعة بدوران.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالصعود في خط الرقعة يكون بزاوية قائمة، أما الدوران فهو في خط النسخ.","ow":["الصعود في الرقعة بزاوية قائمة وليس بدوران.",""]},
  {"q":"العبارة: النقطتان في النسخ منفردتان دون طمس.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالنقطتان في خط النسخ منفردتان من غير طمس، أما في الرقعة فمتصلتان.","ow":["","العبارة صحيحة، فالنقطتان في النسخ منفصلتان."]},
  {"q":"العبارة: الثلث والديواني من الخطوط العربية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالثلث والديواني من الخطوط العربية مع النسخ والرقعة والكوفي، كما ذكر الدرس.","ow":["","العبارة صحيحة، فهما خطان عربيان."]},
  {"q":"العبارة: يجب أن نقبض على القلم بشدة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فلا نقبض على القلم بشدة، بل نمسكه برفق بين السبابة والإبهام، لأن القبض الشديد يتعب اليد.","ow":["القبض الشديد على القلم من الأمور التي نتجنبها.",""]},
];
window.BANK['a7']['a7-1-5'] = [
  {"q":"المعرفة هي الاسم الذي يدل على شيء أو شخص:","o":["غير معيّن","معيّن","مجهول","محذوف"],"a":1,"why":"المعرفة هي الاسم الذي يدل على شيء أو شخص معيّن بعينه، مثل: الكتاب ومحمد، فنعرف تمامًا ما المقصود به.","ow":["غير المعيّن هو النكرة، وليس المعرفة.","","المجهول ليس هو المعرفة، فالمعرفة تدل على شيء معروف.","المحذوف ليس هو المعرفة، فالمعرفة اسم ظاهر."]},
  {"q":"أي الكلمات الآتية تُعدّ نكرة؟","o":["رجلٌ","الرجلُ","محمدٌ","أنا"],"a":0,"why":"رجلٌ نكرة لأنه يدل على أي رجل غير معيّن وفيه تنوين. أما الرجل فمعرفة، ومحمد علم، وأنا ضمير.","ow":["","الرجل فيها ال التعريف فهي معرفة.","محمد علم، والعلم من المعارف.","أنا ضمير، والضمير من المعارف."]},
  {"q":"أي الكلمات الآتية معرفة؟","o":["كتابٌ","مودةٌ","المودةُ","رجلٌ"],"a":2,"why":"المودة معرفة لأنها بدأت بـ ال التعريف فصارت تدل على مودة معيّنة. أما كتابٌ ومودةٌ ورجلٌ فنكرات.","ow":["كتابٌ نكرة لأنها تدل على أي كتاب.","مودةٌ نكرة لأنها تدل على أي مودة.","","رجلٌ نكرة لأنها تدل على أي رجل."]},
  {"q":"عدد أنواع المعارف:","o":["أربعة","خمسة","ثلاثة","ستة"],"a":3,"why":"المعارف ستة أنواع: الضمير، والعلم، واسم الإشارة، والاسم الموصول، والمعرّف بـ ال، والمعرّف بالإضافة.","ow":["الأنواع ليست أربعة بل ستة.","الأنواع ليست خمسة بل ستة.","الأنواع ليست ثلاثة بل ستة.",""]},
  {"q":"كلمة <b>مكة</b> معرفة من نوع:","o":["علم","ضمير","اسم إشارة","اسم موصول"],"a":0,"why":"مكة اسم مكان معيّن، فهي علم، والعلم من المعارف الستة، لأنه يدل على مكان بعينه ولا يشاركه فيه غيره.","ow":["","الضمير مثل أنا وهو، ومكة ليست ضميرًا.","اسم الإشارة مثل هذه وهؤلاء، ومكة ليست منه.","الاسم الموصول مثل الذي والتي، ومكة ليست منه."]},
  {"q":"كلمة <b>هذه</b> معرفة من نوع:","o":["علم","اسم إشارة","ضمير","اسم موصول"],"a":1,"why":"هذه اسم إشارة يُشار به إلى مؤنث قريب، وهو من المعارف الستة، فنقول: هذه المدينة فنعيّن المقصود.","ow":["العلم هو اسم شخص أو مكان بعينه.","","الضمير مثل هي وأنا.","الاسم الموصول مثل التي والذي."]},
  {"q":"كلمة <b>نحن</b> معرفة من نوع:","o":["علم","اسم موصول","ضمير","اسم إشارة"],"a":2,"why":"نحن ضمير يدل على المتكلمين، والضمير من المعارف الستة لأنه يدل على أشخاص معيّنين هم المتكلمون.","ow":["العلم هو اسم شخص أو مكان بعينه.","الاسم الموصول مثل الذي والتي.","","اسم الإشارة مثل هذا وهؤلاء."]},
  {"q":"كلمة <b>الذين</b> معرفة من نوع:","o":["ضمير","علم","اسم إشارة","اسم موصول"],"a":3,"why":"الذين اسم موصول لجمع المذكر، ويحتاج إلى جملة بعده تسمى صلة الموصول، وهو من المعارف الستة.","ow":["الضمير مثل هم وأنتم.","العلم هو اسم شخص أو مكان بعينه.","اسم الإشارة مثل هؤلاء.",""]},
  {"q":"كلمة <b>المدينة</b> معرفة بـ:","o":["(ال)","الإضافة","الضمير","العلمية"],"a":0,"why":"المدينة بدأت بـ ال التعريف فصارت معرفة بـ ال، لأن ال حدّدت المدينة المقصودة بعد أن كانت نكرة.","ow":["","الإضافة تكون بإضافة اسم إلى اسم آخر مثل مدينة الرياض.","الضمير مثل هي وأنا، والمدينة ليست ضميرًا.","العلمية تكون باسم شخص أو مكان بعينه مثل مكة."]},
  {"q":"كلمة <b>كتابُ الطالب</b> معرفة بـ:","o":["(ال)","الإضافة","الإشارة","الموصولية"],"a":1,"why":"كتابُ الطالب معرفة بالإضافة، لأن كتاب أُضيف إلى الطالب وهو معرفة، فصار معيّنًا بعد أن كان نكرة.","ow":["ليست معرّفة بـ ال، لأن كلمة كتاب في أولها بلا ال.","","الإشارة تكون باسم إشارة مثل هذا.","الموصولية تكون باسم موصول مثل الذي."]},
  {"q":"من أسماء الإشارة:","o":["الذي","أنا","هؤلاء","محمد"],"a":2,"why":"هؤلاء اسم إشارة يُشار به إلى أشخاص معيّنين. أما الذي فاسم موصول، وأنا ضمير، ومحمد علم.","ow":["الذي اسم موصول يحتاج إلى صلة.","أنا ضمير يدل على المتكلم.","","محمد علم يدل على شخص بعينه."]},
  {"q":"من الأسماء الموصولة:","o":["هذا","هي","مكة","التي"],"a":3,"why":"التي اسم موصول، تحتاج إلى جملة بعدها تسمى صلة الموصول. أما هذا فاسم إشارة، وهي ضمير، ومكة علم.","ow":["هذا اسم إشارة وليس موصولًا.","هي ضمير وليست اسمًا موصولًا.","مكة علم وليست اسمًا موصولًا.",""]},
  {"q":"من الضمائر:","o":["هو","هذا","الذي","فاطمة"],"a":0,"why":"هو ضمير يدل على الغائب المذكر، والضمير من المعارف الستة. أما هذا فاسم إشارة، والذي موصول، وفاطمة علم.","ow":["","هذا اسم إشارة وليس ضميرًا.","الذي اسم موصول وليس ضميرًا.","فاطمة علم وليس ضميرًا."]},
  {"q":"تتصل الأسماء الموصولة بجملة تسمى:","o":["جملة الخبر","صلة الموصول","جملة النداء","جملة الشرط"],"a":1,"why":"الاسم الموصول يحتاج إلى جملة بعده توضح معناه تسمى صلة الموصول، مثل: الذي يجتهد ينجح.","ow":["جملة الخبر هي ما يكمّل المبتدأ، وليست صلة الموصول.","","جملة النداء تأتي بعد يا ولا تتصل بالموصول.","جملة الشرط تأتي بعد أداة شرط وليست صلة الموصول."]},
  {"q":"الاسم النكرة هو الذي يدل على شخص أو شيء:","o":["معيّن","محدد","غير معيّن","مذكور باسمه"],"a":2,"why":"النكرة هي الاسم الذي يدل على شخص أو شيء غير معيّن، أي ليس مقصودًا بذاته، مثل كتابٌ ورجلٌ.","ow":["المعيّن هو المعرفة.","المحدد هو المعرفة.","","المذكور باسمه هو العلم وهو من المعارف."]},
  {"q":"العبارة: <b>كتابٌ</b> نكرة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فكتابٌ نكرة لأنها تدل على أي كتاب غير معيّن، وفيها تنوين، وليست كتاب معين بعينه.","ow":["","العبارة صحيحة، فكتابٌ غير معيّن."]},
  {"q":"العبارة: <b>أنا</b> نكرة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فأنا ضمير، والضمائر من المعارف لأنها تدل على المتكلم المعيّن، فلا تكون نكرة.","ow":["أنا معرفة وليست نكرة، لأنها تدل على المتكلم بعينه.",""]},
  {"q":"العبارة: الاسم العلم من المعارف.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالعلم هو اسم شخص أو مكان بعينه مثل محمد ومكة، وهو من المعارف الستة.","ow":["","العبارة صحيحة، فالعلم يعيّن شخصًا أو مكانًا."]},
  {"q":"العبارة: المعارف خمسة أنواع.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمعارف ستة أنواع: الضمير والعلم واسم الإشارة والاسم الموصول والمعرّف بـ ال والمعرّف بالإضافة.","ow":["عدد المعارف ستة وليس خمسة.",""]},
  {"q":"العبارة: <b>هؤلاء</b> اسم إشارة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فهؤلاء اسم إشارة، يُشار به إلى أشخاص معيّنين، وهو من المعارف الستة.","ow":["","العبارة صحيحة، فهؤلاء ليس ضميرًا ولا علمًا."]},
];
window.BANK['a7']['a7-1-6'] = [
  {"q":"الجملة الاسمية تبدأ بـ:","o":["فعل","اسم","حرف جر","فاعل"],"a":1,"why":"الجملة الاسمية تبدأ باسم، وهذا ما يميزها عن الجملة الفعلية التي تبدأ بفعل، مثل: الحسناتُ ماحياتٌ.","ow":["الجملة التي تبدأ بفعل هي الفعلية.","","الجملة الاسمية لا تبدأ بحرف جر.","الفاعل لا تبدأ به الجملة الاسمية، بل المبتدأ."]},
  {"q":"الجملة الفعلية تتكون من:","o":["مبتدأ وخبر","فعل وفاعل","نداء ومنادى","اسم وحرف"],"a":1,"why":"الجملة الفعلية تتكون من فعل وفاعل، مثل: جاء المسلمُ، فجاء فعل والمسلم فاعل، أما المبتدأ والخبر فللجملة الاسمية.","ow":["المبتدأ والخبر ركنا الجملة الاسمية.","","النداء والمنادى من أساليب أخرى وليسا ركني الجملة الفعلية.","الاسم والحرف نوعان من أنواع الكلمة وليسا ركني الجملة الفعلية."]},
  {"q":"المبتدأ في جملة: <b>العالِمُ مشهورٌ</b>","o":["مشهورٌ","العالِمُ","لا يوجد","الجملة كلها"],"a":1,"why":"العالِمُ هو الاسم الذي بدأت به الجملة، فهو المبتدأ، ومشهورٌ خبر لأنه كمّل المعنى.","ow":["مشهورٌ هو الخبر وليس المبتدأ.","","يوجد مبتدأ في الجملة الاسمية دائمًا، وهو العالم.","الجملة كلها ليست المبتدأ، بل المبتدأ جزء منها."]},
  {"q":"الخبر في جملة: <b>الصدقُ فضيلةٌ</b>","o":["الصدقُ","فضيلةٌ","لا يوجد","الجملة"],"a":1,"why":"فضيلةٌ هي الخبر لأنها كمّلت معنى المبتدأ الصدقُ وأخبرت عنه، فنقول: الصدق فضيلة، فتم المعنى بها.","ow":["الصدقُ هو المبتدأ وليس الخبر.","","يوجد خبر في الجملة الاسمية دائمًا، وهو فضيلة.","الجملة كلها ليست الخبر، بل الخبر جزء منها."]},
  {"q":"يُعرّف الخبر بأنه الاسم الذي:","o":["نبدأ به الجملة","يدل على الفاعل","يخبر به عن المبتدأ ويفيد معه معنى تامًا","يدل على حدث"],"a":2,"why":"الخبر هو الاسم الذي يخبر به عن المبتدأ ويفيد معه معنى تامًا، مثل: ماحياتٌ في الحسنات ماحيات.","ow":["الاسم الذي نبدأ به الجملة هو المبتدأ.","الاسم الذي يدل على الفاعل ليس تعريف الخبر.","","الاسم الذي يدل على حدث هو المصدر أو الفعل."]},
  {"q":"حكم المبتدأ والخبر في الإعراب:","o":["منصوبان","مجروران","مجزومان","مرفوعان"],"a":3,"why":"المبتدأ والخبر مرفوعان دائمًا، وعلامة رفعهما قد تكون الضمة أو الألف أو الواو بحسب نوعهما.","ow":["لا يكونان منصوبين.","لا يكونان مجرورين.","الجزم يكون في الأفعال وليس في المبتدأ والخبر.",""]},
  {"q":"علامة رفع <b>العالِمان</b> في: العالِمان مشهوران","o":["الألف","الواو","الضمة","الياء"],"a":0,"why":"العالمان مثنى والمثنى يُرفع بالألف، ومشهوران خبر مثنى مرفوع بالألف كذلك، فعلامة رفع المبتدأ هي الألف.","ow":["","الواو علامة رفع جمع المذكر السالم والأسماء الخمسة.","الضمة علامة رفع المفرد وجمع التكسير وجمع المؤنث السالم.","الياء ليست علامة رفع."]},
  {"q":"علامة رفع <b>العالِمون</b> في: العالِمون مشهورون","o":["الألف","الواو","الضمة","الياء"],"a":1,"why":"العالمون جمع مذكر سالم والجمع المذكر السالم يُرفع بالواو، ومشهورون خبر مرفوع بالواو كذلك.","ow":["الألف علامة رفع المثنى.","","الضمة علامة رفع المفرد وجمع التكسير وجمع المؤنث السالم.","الياء ليست علامة رفع."]},
  {"q":"علامة رفع <b>العالِماتُ</b> في: العالِماتُ مشهوراتٌ","o":["الألف","الواو","الضمة","الياء"],"a":2,"why":"العالمات جمع مؤنث سالم والجمع المؤنث السالم يُرفع بالضمة، ومشهورات خبر مرفوع بالضمة كذلك.","ow":["الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","","الياء ليست علامة رفع."]},
  {"q":"من الأسماء الخمسة:","o":["ابن","أخو","عمّ","خال"],"a":1,"why":"أخو من الأسماء الخمسة وهي: أبو وأخو وحمو وذو وفو. أما ابن وعمّ وخال فليست من الأسماء الخمسة.","ow":["ابن ليس من الأسماء الخمسة.","","عمّ ليس من الأسماء الخمسة.","خال ليس من الأسماء الخمسة."]},
  {"q":"علامة رفع الأسماء الخمسة:","o":["الضمة","الألف","الياء","الواو"],"a":3,"why":"الأسماء الخمسة تُرفع بالواو، مثل: أخوك عالمٌ، فعلامة رفع أخوك الواو، ولا تُرفع بالضمة.","ow":["الضمة علامة رفع المفرد.","الألف علامة رفع المثنى.","الياء ليست علامة رفع.",""]},
  {"q":"إعراب <b>الحسناتُ</b> في: الحسناتُ ماحياتٌ للسيئات","o":["مبتدأ مرفوع","خبر مرفوع","فاعل مرفوع","اسم مجرور"],"a":0,"why":"الحسنات بدأت بها الجملة فهي مبتدأ، وهي مرفوعة بالضمة لأنها جمع مؤنث سالم، وماحيات خبر.","ow":["","ماحيات هي الخبر وليست المبتدأ.","الحسنات ليست فاعلًا لأنه لا يوجد فعل قبلها.","الحسنات ليست مجرورة بل مرفوعة لأنها مبتدأ."]},
  {"q":"إعراب <b>ماحياتٌ</b> في الجملة نفسها:","o":["مبتدأ مرفوع","فاعل","خبر مرفوع","مفعول به"],"a":2,"why":"ماحيات هي الاسم الذي أكمل معنى المبتدأ الحسنات، فهي خبر مرفوع بالضمة لأنها جمع مؤنث سالم.","ow":["ماحيات ليست مبتدأ لأن الجملة بدأت بالحسنات.","ماحيات ليست فاعلًا لأنه لا فعل في الجملة.","","ماحيات ليست مفعولًا به لأنه لا فعل في الجملة."]},
  {"q":"إعراب <b>القاضيان</b> في: القاضيان منصفان","o":["فاعل","خبر","اسم مجرور","مبتدأ مرفوع وعلامة رفعه الألف"],"a":3,"why":"القاضيان مثنى، بدأت به الجملة فهو مبتدأ، والمثنى يُرفع بالألف، فنقول: مبتدأ مرفوع وعلامة رفعه الألف.","ow":["القاضيان مبتدأ وليس فاعلًا لأنه لا يوجد فعل.","القاضيان مبتدأ وليس خبرًا لأنه بدأت به الجملة.","القاضيان مرفوع وليس مجرورًا.",""]},
  {"q":"إعراب <b>أخوك</b> في: أخوك عالمٌ","o":["مبتدأ مرفوع وعلامة رفعه الواو","مبتدأ مرفوع وعلامة رفعه الضمة","خبر مرفوع","فاعل"],"a":0,"why":"أخوك من الأسماء الخمسة، بدأت به الجملة فهو مبتدأ، ويُرفع بالواو، فعلامة رفعه الواو.","ow":["","الضمة علامة رفع المفرد، وأخوك من الأسماء الخمسة فيرفع بالواو.","أخوك مبتدأ وليس خبرًا لأنه بدأت به الجملة.","أخوك مبتدأ وليس فاعلًا لأنه لا فعل قبله."]},
  {"q":"العبارة: المبتدأ والخبر مرفوعان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمبتدأ والخبر مرفوعان دائمًا، وإنما تتغير علامة الرفع بحسب نوع الاسم.","ow":["","العبارة صحيحة، فالرفع هو حكمهما الثابت."]},
  {"q":"العبارة: يُرفع المثنى بالواو.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمثنى يُرفع بالألف مثل القاضيان، أما الواو فلجمع المذكر السالم والأسماء الخمسة.","ow":["المثنى يُرفع بالألف وليس بالواو.",""]},
  {"q":"العبارة: <b>أخو</b> من الأسماء الخمسة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأخو من الأسماء الخمسة وهي: أبو وأخو وحمو وذو وفو، وتُرفع بالواو.","ow":["","العبارة صحيحة، فأخو من الأسماء الخمسة."]},
  {"q":"العبارة: يُرفع جمع المؤنث السالم بالألف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فجمع المؤنث السالم يُرفع بالضمة مثل: ماحياتٌ، أما الألف فهي علامة رفع المثنى.","ow":["جمع المؤنث السالم يُرفع بالضمة وليس بالألف.",""]},
  {"q":"العبارة: الجملة الاسمية تتكون من مبتدأ وخبر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجملة الاسمية تتكون من ركنين أساسيين هما المبتدأ والخبر، مثل: الحسناتُ ماحياتٌ.","ow":["","العبارة صحيحة، فركنا الاسمية هما المبتدأ والخبر."]},
];
window.BANK['a7']['a7-1-7'] = [
  {"q":"القراءة الصامتة تكون:","o":["بصوت مرتفع","بالعينين دون صوت","بالهمس","بتحريك الشفاه"],"a":1,"why":"القراءة الصامتة تكون بالعينين دون صوت، فلا نصدر صوتًا ولا نحرك الشفاه ولا نهمس، وهذا يخالف القراءة الجهرية.","ow":["بصوت مرتفع تكون القراءة الجهرية.","","الهمس يخالف أسس القراءة الصامتة.","تحريك الشفاه يخالف أسس القراءة الصامتة."]},
  {"q":"أي الآتي من أسس القراءة الصامتة؟","o":["وضع خطوط تحت الألفاظ الجديدة بقلم الرصاص","رفع الصوت","تحريك الشفاه","الهمس"],"a":0,"why":"من أسس القراءة الصامتة وضع خطوط بقلم الرصاص تحت الألفاظ الجديدة لنرجع إليها ونعرف معانيها.","ow":["","رفع الصوت من القراءة الجهرية.","تحريك الشفاه ممنوع في القراءة الصامتة.","الهمس ممنوع في القراءة الصامتة."]},
  {"q":"أي الآتي من مهارات القراءة الجهرية؟","o":["تجنب التلفظ","جودة النطق","تحريك العينين فقط","عدم رفع الصوت"],"a":1,"why":"جودة النطق أولى مهارات القراءة الجهرية، فنقرأ الحروف والكلمات بوضوح وبصوت مسموع.","ow":["تجنب التلفظ من أسس القراءة الصامتة.","","القراءة الجهرية ليست بالعينين فقط، بل بصوت مسموع.","عدم رفع الصوت يناقض القراءة الجهرية."]},
  {"q":"في القراءة الجهرية نقف وقفة مناسبة عند:","o":["إهمال الضبط","القراءة بسرعة كبيرة","الوقف المناسب عند علامات الترقيم","الصمت التام"],"a":2,"why":"الوقف المناسب عند علامات الترقيم من مهارات القراءة الجهرية، فنقف عند النقطة والفاصلة حتى يفهم السامع.","ow":["إهمال الضبط يؤدي إلى الخطأ، وليس من المهارات.","القراءة بسرعة كبيرة تخالف السرعة الملائمة للفهم.","","الصمت التام ليس القراءة الجهرية."]},
  {"q":"لقب الشاعر <b>أحمد شوقي</b>:","o":["أمير البيان","شاعر النيل","شاعر الرسول","أمير الشعراء"],"a":3,"why":"لقب أحمد شوقي أمير الشعراء، وهو لقب معروف له في الأدب العربي الحديث، وقد أدخل المسرحيات الشعرية.","ow":["أمير البيان لقب لشخص آخر.","شاعر النيل لقب لشاعر آخر.","شاعر الرسول لقب لشاعر آخر.",""]},
  {"q":"من شعراء العصر الحديث الذين درسنا نصهم:","o":["أحمد شوقي","المتنبي","امرؤ القيس","الجاحظ"],"a":0,"why":"أحمد شوقي من شعراء العصر الحديث الذين درسنا نصهم، أما المتنبي وامرؤ القيس فمن العصور القديمة والجاحظ كاتب نثر.","ow":["","المتنبي شاعر عباسي قديم.","امرؤ القيس شاعر جاهلي قديم.","الجاحظ أديب كتب النثر وليس شاعرًا."]},
  {"q":"أول من أدخل المسرحيات الشعرية في الأدب العربي، ومن أمثلتها <b>مسرحية عنترة</b>، هو:","o":["الجاحظ","أحمد شوقي","المتنبي","عنترة"],"a":1,"why":"أحمد شوقي هو أول من أدخل المسرحيات الشعرية في الأدب العربي، ومن أمثلتها مسرحية عنترة.","ow":["الجاحظ أديب كتب النثر وليس المسرحيات الشعرية.","","المتنبي شاعر قديم لم يكتب المسرحيات الشعرية.","عنترة شخصية المسرحية وليس مؤلفها."]},
  {"q":"من إنتاج شوقي الأدبي:","o":["ديوان الشوقيات","المعلقات","كليلة ودمنة","البخلاء"],"a":0,"why":"من إنتاج شوقي الأدبي ديوان الشوقيات، وهو ديوان شعر جمع قصائده، أما الكتب الأخرى فلمؤلفين آخرين.","ow":["","المعلقات قصائد جاهلية وليست من إنتاج شوقي.","كليلة ودمنة كتاب ترجمه ابن المقفع وليس من إنتاج شوقي.","البخلاء كتاب للجاحظ وليس لشوقي."]},
  {"q":"الشاعر في قوله: «إذا عفوتَ فقادرٌ ومقدِّرٌ» يصف:","o":["العفو عن قدرة","الغضب","الحزن","الفقر"],"a":0,"why":"قول الشاعر إذا عفوتَ فقادر ومقدّر يصف العفو عن قدرة، أي أن النبي ﷺ يعفو وهو قادر على العقاب.","ow":["","الغضب ليس هو المعنى هنا، فالكلام عن العفو.","الحزن ليس موضوع البيت.","الفقر ليس موضوع البيت."]},
  {"q":"قوله: «إذا غضبتَ فإنما هي غضبةٌ في الحق» يدل على:","o":["الرحمة","العفو","الغضب للحق","الكرم"],"a":2,"why":"قوله إذا غضبتَ فإنما هي غضبة في الحق يدل على أن غضبه ﷺ يكون للحق فقط، لا لنفسه ولا لهواه.","ow":["الرحمة في بيت آخر وليست معنى هذا البيت.","العفو في بيت آخر وليس معنى هذا البيت.","","الكرم ليس موضوع هذا البيت."]},
  {"q":"تكرار كلمة (إذا) في الأبيات من أغراضه:","o":["الاستعطاف","السخرية","التحقير","النفي"],"a":0,"why":"تكرار كلمة إذا من أغراضه الاستعطاف، أي استمالة القلوب وبيان فضائل النبي ﷺ في كل حال.","ow":["","السخرية ليست غرض هذا التكرار.","التحقير ليس غرض هذا التكرار.","النفي ليس غرض هذا التكرار."]},
  {"q":"تكرار الشاعر لكلمة (إذا) غرضه:","o":["الحذف","الإلحاح","التقديم","النفي"],"a":1,"why":"تكرار الشاعر كلمة إذا غرضه الإلحاح، أي تأكيد المعنى وتقويته، ومنها أيضًا الاستعطاف.","ow":["الحذف عكس التكرار.","","التقديم ليس غرض التكرار.","النفي ليس غرض التكرار."]},
  {"q":"معنى <b>الصبا</b>:","o":["الكبر","الشيخوخة","الصغر والحداثة","القوة"],"a":2,"why":"الصبا معناها الصغر والحداثة، أي سن الطفولة والشباب المبكر، وهي عكس الكبر والشيخوخة.","ow":["الكبر عكس الصبا.","الشيخوخة عكس الصبا.","","القوة ليست هي المعنى المذكور للصبا."]},
  {"q":"معنى <b>حنّت</b>:","o":["مدّت صوتها من الشوق إلى ولدها","غضبت","نامت","جلست"],"a":0,"why":"حنّت أي مدّت صوتها من الشوق إلى ولدها، كما تفعل الناقة حين تشتاق إلى ولدها وتنادي عليه.","ow":["","غضبت ليست معنى حنّت.","نامت ليست معنى حنّت.","جلست ليست معنى حنّت."]},
  {"q":"ضد كلمة <b>رحمتَ</b> في قوله: «إذا رحمتَ فأنتَ أمٌّ أو أبٌ» هو:","o":["قسوتَ","عفوتَ","أحببتَ","غفرتَ"],"a":0,"why":"ضد رحمتَ هو قسوتَ، فالرحمة عكس القسوة. أما عفوتَ وغفرتَ وأحببتَ فمعانيها قريبة من الرحمة.","ow":["","عفوتَ قريبة في المعنى من رحمتَ وليست ضدها.","أحببتَ قريبة في المعنى من الرحمة.","غفرتَ قريبة في المعنى من رحمتَ وليست ضدها."]},
  {"q":"كاتب نص «محاسن المودة» هو:","o":["أحمد شوقي","أبو عثمان الجاحظ","المتنبي","ابن المقفع"],"a":1,"why":"نص محاسن المودة من كتاب المحاسن والأضداد لأبي عثمان الجاحظ، فهو كاتب النص وليس غيره.","ow":["أحمد شوقي شاعر القصيدة التي درسناها، وليس كاتب هذا النص.","","المتنبي شاعر وليس كاتب النص.","ابن المقفع ليس كاتب النص المذكور."]},
  {"q":"المودة هي:","o":["خصام القلوب","تعاطف القلوب وائتلاف الأرواح","كثرة الكلام","الغنى"],"a":1,"why":"ذكر النص أن المودة تعاطف القلوب وائتلاف الأرواح، أي ميل القلوب إلى بعضها واجتماع الأرواح.","ow":["خصام القلوب عكس المودة.","","كثرة الكلام ليست معنى المودة.","الغنى ليس معنى المودة."]},
  {"q":"العبارة: القراءة الصامتة تتجنب الهمس وتحريك الشفاه.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن أسس القراءة الصامتة تجنب الهمس وتجنب التلفظ وتجنب تحريك الشفاه.","ow":["","العبارة صحيحة، فهذه أسس القراءة الصامتة."]},
  {"q":"العبارة: الوقف عند علامات الترقيم من مهارات القراءة الجهرية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالوقف المناسب عند علامات الترقيم من مهارات القراءة الجهرية الخمس.","ow":["","العبارة صحيحة، فنقف عند علامات الترقيم في الجهرية."]},
  {"q":"العبارة: لُقّب أحمد شوقي بأمير الشعراء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فلقب أحمد شوقي أمير الشعراء، وهو لقب عُرف به في الأدب العربي الحديث.","ow":["","العبارة صحيحة، فالقب معروف لشوقي."]},
  {"q":"العبارة: الصبا تعني الكبر والشيخوخة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالصبا تعني الصغر والحداثة، أما الكبر والشيخوخة فهما عكس معناها تمامًا.","ow":["الصبا لا تعني الكبر والشيخوخة، بل عكسهما.",""]},
];
window.BANK['a7']['a7-1-8'] = [
  {"q":"من الخصائص الفنية للحوار الناجح:","o":["تعدد الموضوعات دون هدف","موضوع واحد وله هدف محدد","الانتقال المفاجئ","عدم الترتيب"],"a":1,"why":"من الخصائص الفنية للحوار الناجح أن يكون له موضوع واحد وهدف محدد، فلا يخرج الحوار عنه ولا يتشتت.","ow":["تعدد الموضوعات بلا هدف يشتت الحوار.","","الانتقال المفاجئ يخالف الترتيب المطلوب.","عدم الترتيب يضيع الحوار."]},
  {"q":"ترتيب الحوار يكون:","o":["عشوائيًا","تسلسلًا منطقيًا دون انتقال مفاجئ","من النهاية إلى البداية","بلا ترتيب"],"a":1,"why":"الترتيب في الحوار هو التسلسل المنطقي للحديث، فننتقل من فكرة إلى ما يليها دون قفز مفاجئ.","ow":["الحوار العشوائي لا ترتيب فيه.","","البدء من النهاية ليس ترتيبًا منطقيًا.","بلا ترتيب يخالف خاصية الترتيب."]},
  {"q":"عدد الخصائص الفنية للحوار المذكورة في الدرس:","o":["ثلاث","أربع","ست","خمس"],"a":3,"why":"خصائص الحوار الفنية خمس: الموضوع، ولغة الحوار، وعباراته وأساليبه، والترتيب، ووسائل التأثير.","ow":["ليست ثلاث خصائص بل خمس.","ليست أربع خصائص بل خمس.","ليست ست خصائص بل خمس.",""]},
  {"q":"بماذا بدأ الحوار القصصي لموسى عليه السلام في سورة القصص؟","o":["سؤال موسى عن حال المرأتين","اقتراح الفتاة على أبيها","عودة موسى إلى مصر","زواج موسى"],"a":0,"why":"بدأ الحوار بأن سأل موسى عليه السلام المرأتين عن حالهما، فذكرتا أنهما لا تقدران على سقي غنمهما.","ow":["","اقتراح الفتاة على أبيها جاء بعد ذلك.","عودة موسى إلى مصر ليست من أحداث هذا الحوار.","الزواج جاء في نهاية القصة وليس في بدايتها."]},
  {"q":"اقترحت إحدى البنتين على أبيها:","o":["استئجار موسى","الرحيل","بيع الغنم","ترك السقاية"],"a":0,"why":"اقترحت إحدى البنتين على أبيها أن يستأجر موسى عليه السلام، واعتمدت في اقتراحها على حجة منطقية.","ow":["","الرحيل ليس هو اقتراح البنت.","بيع الغنم ليس اقتراحها.","ترك السقاية ليس اقتراحها."]},
  {"q":"اعتمدت الفتاة في حجتها على:","o":["الغضب","المنطق والدليل","الخوف","الطمع"],"a":1,"why":"اعتمدت الفتاة على المنطق والدليل، فقد سقى موسى لهما ومشى أمامها، فاستدلت بذلك على صلاحه.","ow":["الغضب ليس حجة منطقية.","","الخوف ليس هو ما اعتمدت عليه.","الطمع ليس هو ما اعتمدت عليه."]},
  {"q":"من أهداف الحوار القائم على الحجة والدليل:","o":["فرض الرأي","إسكات الطرف الآخر","الإقناع والتأثير","إطالة الكلام"],"a":2,"why":"الحوار القائم على الحجة والدليل هدفه الإقناع والتأثير في الطرف الآخر بالمنطق، وليس فرض الرأي عليه.","ow":["فرض الرأي يخالف الحجة والدليل.","إسكات الطرف الآخر ليس هدف الحوار.","","إطالة الكلام ليست هدفًا."]},
  {"q":"يربّي القرآن الكريم الإنسان المسلم بأساليب منها:","o":["السخرية","الترغيب والترهيب","الإهمال","التجاهل"],"a":1,"why":"من أساليب القرآن في تربية الإنسان المسلم الترغيب والترهيب وضرب الأمثال والقصة، وليس السخرية ولا الإهمال.","ow":["السخرية ليست من أساليب التربية القرآنية.","","الإهمال ليس من أساليب القرآن.","التجاهل ليس من أساليب القرآن."]},
  {"q":"أي الآتي أسلوب تربوي في القرآن الكريم؟","o":["إهمال الحوار","ضرب الأمثال","التهديد فقط","الصمت"],"a":1,"why":"ضرب الأمثال من أساليب التربية في القرآن، يقرّب المعنى إلى الأذهان. أما الإهمال والصمت والتهديد فقط فليست منها.","ow":["إهمال الحوار ليس أسلوبًا تربويًا.","","التهديد فقط ليس أسلوبًا تربويًا كاملًا.","الصمت ليس أسلوبًا تربويًا في القرآن."]},
  {"q":"من أهداف القصة في القرآن:","o":["التسلية فقط","أخذ العظة والعبرة","الإطالة","الإبهام"],"a":1,"why":"من أهداف القصة في القرآن أخذ العظة والعبرة وغرس القيم الرفيعة، وليس التسلية فقط.","ow":["التسلية فقط ليست الهدف.","","الإطالة ليست هدفًا.","الإبهام ليس هدف القصة."]},
  {"q":"النهاية المغايرة هي نهاية:","o":["مطابقة للأصل","مختلفة نكتبها نحن","محذوفة","مكررة"],"a":1,"why":"النهاية المغايرة هي نهاية مختلفة عن النهاية الأصلية للقصة، نكتبها نحن بأفكارنا وأسلوبنا.","ow":["المطابقة للأصل ليست مغايرة.","","المحذوفة ليست نهاية.","المكررة ليست مغايرة بل نسخ."]},
  {"q":"من أنواع النهايات:","o":["المتوقعة والمفاجئة","الاسمية والفعلية","المرفوعة والمنصوبة","المذكرة والمؤنثة"],"a":0,"why":"من أنواع النهايات المتوقعة والمفاجئة وغيرها، أما الاسمية والفعلية فأنواع الجملة، والمرفوعة والمنصوبة أنواع الإعراب، والمذكرة والمؤنثة أنواع الاسم.","ow":["","الاسمية والفعلية أنواع للجملة وليست للنهايات.","المرفوعة والمنصوبة أنواع الإعراب وليست للنهايات.","المذكرة والمؤنثة أنواع الاسم وليست للنهايات."]},
  {"q":"عند كتابة نهاية مغايرة نراعي:","o":["جودة الأسلوب وسلامة اللغة","طول القصة فقط","السرعة","ترك الأخطاء"],"a":0,"why":"عند كتابة نهاية مغايرة نراعي جودة الأسلوب وسلامة اللغة لتكون النهاية جميلة وخالية من الأخطاء.","ow":["","طول القصة فقط ليس هو المعيار.","السرعة لا تهمّ مع جودة الأسلوب.","ترك الأخطاء يخالف سلامة اللغة."]},
  {"q":"في قصة الريال الفضي، يرى العم حمزة صبيًّا يتقافز في ماء ميناء:","o":["الدمام","جدة","الرياض","تبوك"],"a":1,"why":"في قصة الريال الفضي رأى العم حمزة صبيًّا يتقافز في ماء ميناء جدة، وكان يريد أن يعطيه شيئًا.","ow":["الدمام ليس المدينة المذكورة في القصة.","","الرياض مدينة بعيدة عن البحر.","تبوك ليست المدينة المذكورة في القصة."]},
  {"q":"في قصة الريال الفضي، يقدّم العم حمزة للصبي:","o":["ريالًا فضيًّا","ثوبًا","طعامًا","قاربًا"],"a":0,"why":"قدّم العم حمزة للصبي ريالًا فضيًّا، وهو القطعة النقدية التي سميت القصة بها، ولم يقدّم ثوبًا ولا طعامًا.","ow":["","الثوب ليس ما قدمه العم حمزة.","الطعام ليس ما قدمه العم حمزة.","القارب ليس ما قدمه العم حمزة."]},
  {"q":"ماذا فعل الصبي بالريال الفضي في القصة؟","o":["احتفظ به","أعاده","ألقاه في البحر وغطس خلفه","اشترى به"],"a":2,"why":"ألقى الصبي الريال الفضي في البحر ثم غطس خلفه، كما جاء في أحداث القصة، فلم يحتفظ به ولم يشترِ به شيئًا.","ow":["لم يحتفظ به بل ألقاه في البحر.","لم يعده إلى صاحبه.","","لم يشترِ به شيئًا بل ألقاه."]},
  {"q":"العبارة: الحوار الناجح له موضوع واحد وهدف محدد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن الخصائص الفنية للحوار الناجح أن يكون له موضوع واحد وهدف محدد، فلا يتشتت.","ow":["","العبارة صحيحة، فهذه أول الخصائص الفنية للحوار."]},
  {"q":"العبارة: من أهداف الحوار فرض الرأي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فهدف الحوار الإقناع والتأثير بالحجة والدليل، وليس فرض الرأي على الطرف الآخر.","ow":["فرض الرأي ليس من أهداف الحوار الناجح.",""]},
  {"q":"العبارة: القصة من أساليب التربية في القرآن.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالقصة من أساليب التربية في القرآن مع الترغيب والترهيب وضرب الأمثال.","ow":["","العبارة صحيحة، فالقصة أسلوب تربوي في القرآن."]},
  {"q":"العبارة: في النهاية المغايرة نكتب النهاية نفسها.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالنهاية المغايرة نهاية مختلفة نكتبها نحن، وليست النهاية الأصلية نفسها.","ow":["النهاية المغايرة لا تكون هي نفسها نهاية الأصل.",""]},
  {"q":"العبارة: النهاية المفاجئة نوع من أنواع النهايات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالنهاية المفاجئة من أنواع النهايات المذكورة في الدرس مع المتوقعة.","ow":["","العبارة صحيحة، فالمفاجئة نوع من النهايات."]},
];
window.BANK['a7']['a7-2-1'] = [
  {"q":"كلمة <b>الدنيا</b> اسم مفرد:","o":["صحيح","منقوص","ممدود","مقصور"],"a":3,"why":"الدنيا آخرها ألف لازمة وقبلها فتحة، وهذا تعريف الاسم المقصور، مثل: الدنيا وأذى وثرى، فنقول عنها اسم مقصور.","ow":["الصحيح ليس آخره ألفًا لازمة.","المنقوص آخره ياء لازمة قبلها كسرة.","الممدود آخره همزة بعد ألف زائدة.",""]},
  {"q":"كلمة <b>القضاء</b> اسم مفرد:","o":["مقصور","ممدود","منقوص","صحيح"],"a":1,"why":"القضاء آخرها همزة بعد ألف زائدة، وهذا تعريف الاسم الممدود، مثل: دعاء وكساء والقضاء.","ow":["المقصور آخره ألف لازمة بلا همزة.","","المنقوص آخره ياء لازمة.","الصحيح ليس ممدودًا ولا مقصورًا ولا منقوصًا."]},
  {"q":"كلمة <b>النادي</b> اسم مفرد:","o":["منقوص","مقصور","ممدود","صحيح"],"a":0,"why":"النادي آخرها ياء لازمة وقبلها كسرة، وهذا تعريف الاسم المنقوص، مثل: الداعي والقاضي والنادي.","ow":["","المقصور آخره ألف لازمة قبلها فتحة.","الممدود آخره همزة بعد ألف زائدة.","الصحيح ليس منقوصًا."]},
  {"q":"كلمة <b>مسجد</b> اسم مفرد:","o":["منقوص","مقصور","صحيح","ممدود"],"a":2,"why":"مسجد اسم صحيح لأن آخره حرف صحيح، فليس مقصورًا ولا منقوصًا ولا ممدودًا، مثل: رسول ودرس.","ow":["المنقوص آخره ياء لازمة.","المقصور آخره ألف لازمة.","","الممدود آخره همزة بعد ألف زائدة."]},
  {"q":"الاسم المنقوص هو الاسم الذي آخره:","o":["ياء لازمة مكسور ما قبلها","ألف لازمة مفتوح ما قبلها","همزة بعد ألف زائدة","حرف صحيح"],"a":0,"why":"الاسم المنقوص هو الذي آخره ياء لازمة وقبلها كسرة، مثل: الداعي والقاضي والنادي، وليس الألف ولا الهمزة.","ow":["","هذا تعريف المقصور وليس المنقوص.","هذا تعريف الممدود وليس المنقوص.","الحرف الصحيح في آخره يجعل الاسم صحيحًا وليس منقوصًا."]},
  {"q":"الاسم الممدود هو الاسم الذي آخره:","o":["ياء لازمة","همزة بعد ألف زائدة","ألف لازمة","نون"],"a":1,"why":"الاسم الممدود هو الذي آخره همزة بعد ألف زائدة، مثل: دعاء وكساء والقضاء، وليس الياء ولا الألف اللازمة.","ow":["الياء اللازمة في آخره يجعله منقوصًا.","","الألف اللازمة في آخره تجعله مقصورًا.","النون ليست من علامات الاسم الممدود."]},
  {"q":"الاسم المقصور هو الاسم الذي آخره:","o":["ياء مكسور ما قبلها","همزة بعد ألف","ألف لازمة مفتوح ما قبلها","تاء مربوطة"],"a":2,"why":"الاسم المقصور هو الذي آخره ألف لازمة وقبلها فتحة، مثل: أذى وثرى والدنيا، وليس الياء ولا الهمزة.","ow":["الياء المكسور ما قبلها تجعل الاسم منقوصًا.","الهمزة بعد الألف تجعل الاسم ممدودًا.","","التاء المربوطة ليست من علامات المقصور."]},
  {"q":"مثنى كلمة <b>مسلم</b> في حالة الرفع:","o":["مسلمين","مسلمات","مسلمون","مسلمان"],"a":3,"why":"مثنى مسلم في حالة الرفع يكون بزيادة ألف ونون على المفرد، فنقول: مسلمان، وفي النصب والجر مسلمين.","ow":["مسلمين مثنى لكن للنصب والجر.","مسلمات جمع مؤنث سالم.","مسلمون جمع مذكر سالم.",""]},
  {"q":"مثنى كلمة <b>عالم</b> في حالة النصب:","o":["عالمين","عالمان","علماء","عالمات"],"a":0,"why":"مثنى عالم في حالة النصب يكون بزيادة ياء ونون على المفرد، فنقول: عالمين، وفي الرفع عالمان.","ow":["","عالمان مثنى لكن للرفع.","علماء جمع تكسير.","عالمات جمع مؤنث سالم."]},
  {"q":"مثنى كلمة <b>مدينة</b> في حالة الرفع:","o":["مدينتين","مدينتان","مدن","مدينات"],"a":1,"why":"مدينة مؤنث، وعند التثنية في الرفع نضيف ألفًا ونونًا فتصبح مدينتان، وتتحول التاء المربوطة إلى تاء مفتوحة.","ow":["مدينتين مثنى لكن في حالتي النصب والجر.","","مدن جمع تكسير للمدينة، وليس مثنى لها.","مدينات جمع مؤنث سالم وليس مثنى."]},
  {"q":"يُكوَّن المثنى في حالتي النصب والجر بزيادة:","o":["ألف ونون","واو ونون","ياء ونون","ألف وتاء"],"a":2,"why":"يُكوَّن المثنى في حالتي النصب والجر بزيادة ياء ونون، مثل: مسلمين، وفي الرفع بألف ونون.","ow":["ألف ونون تكون في حالة الرفع.","واو ونون في جمع المذكر السالم.","","ألف وتاء في جمع المؤنث السالم."]},
  {"q":"من ملحقات المثنى:","o":["ثلاثة","أربعة","خمسة","اثنتان"],"a":3,"why":"ملحقات المثنى هي: اثنان واثنتان وكلا وكلتا، فاثنتان منها لأنها تدل على اثنتين ولا مفرد لها من لفظها.","ow":["ثلاثة عدد يدل على الجمع وليس ملحقًا بالمثنى.","أربعة عدد يدل على الجمع وليس ملحقًا بالمثنى.","خمسة عدد يدل على الجمع وليس ملحقًا بالمثنى.",""]},
  {"q":"تُعرب <b>كلا</b> و<b>كلتا</b> إعراب المثنى إذا أُضيفتا إلى:","o":["ضمير","اسم ظاهر","فعل","حرف"],"a":0,"why":"تُعرب كلا وكلتا إعراب المثنى إذا أُضيفتا إلى ضمير، مثل: كلاهما وكلتاهما، أما مع الاسم الظاهر فلا.","ow":["","إذا أُضيفتا إلى اسم ظاهر لم يُعربا إعراب المثنى.","الفعل لا يضاف إليه.","الحرف لا يضاف إليه."]},
  {"q":"تُحذف نون المثنى عند:","o":["النداء","الإضافة","الاستفهام","النفي"],"a":1,"why":"تُحذف نون المثنى عند الإضافة، كما يُحذف التنوين من المفرد عند الإضافة، مثل: كتابا الطالب.","ow":["النداء لا تُحذف فيه نون المثنى.","","الاستفهام لا تُحذف فيه نون المثنى.","النفي لا تُحذف فيه نون المثنى."]},
  {"q":"مثنى <b>مدينتان</b> عند إضافته إلى القاهرة يصبح:","o":["مدينتان","مدينتين","مدينتا","مدينة"],"a":2,"why":"عند إضافة مدينتان إلى القاهرة تُحذف النون فتصبح مدينتا القاهرة، كما نقول كتابا الطالب.","ow":["مدينتان بالنون لا تكون مع الإضافة.","مدينتين مثنى في النصب والجر ولا تتغير النون بهذا الشكل.","","مدينة مفرد وليست مثنى."]},
  {"q":"العبارة: كلمة <b>ثرى</b> اسم مقصور.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فثرى آخرها ألف لازمة وقبلها فتحة، فهي اسم مقصور، مثل أذى والدنيا في الأمثلة المقصورة.","ow":["","العبارة صحيحة، فثرى مثل أذى والدنيا."]},
  {"q":"العبارة: كلمة <b>الداعي</b> اسم ممدود.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالداعي آخره ياء لازمة وقبلها كسرة، فهو اسم منقوص وليس ممدودًا، فالممدود ينتهي بهمزة بعد ألف.","ow":["الداعي ليس ممدودًا لأنه لا ينتهي بهمزة بعد ألف.",""]},
  {"q":"العبارة: يُكوَّن المثنى في حالة النصب بزيادة ألف ونون.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمثنى في حالة النصب يُكوَّن بياء ونون، أما ألف ونون ففي حالة الرفع.","ow":["المثنى في النصب والجر بياء ونون وليس بألف ونون.",""]},
  {"q":"العبارة: <b>اثنان</b> من ملحقات المثنى.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فاثنان من ملحقات المثنى لأنها تدل على اثنين لكن لا مفرد لها من لفظها.","ow":["","العبارة صحيحة، فاثنان ملحقة بالمثنى."]},
  {"q":"العبارة: تُحذف نون المثنى عند الإضافة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فنون المثنى تُحذف عند الإضافة، مثل: كتابا الطالب، كما يُحذف التنوين من المفرد.","ow":["","العبارة صحيحة، فحذف النون من أحكام المثنى مع الإضافة."]},
];
window.BANK['a7']['a7-2-2'] = [
  {"q":"من الأفعال الناسخة (كان وأخواتها):","o":["ذهب","أصبح","كتب","جلس"],"a":1,"why":"أصبح من أخوات كان، وتفيد حدوث الخبر في وقت الصباح. أما ذهب وكتب وجلس فأفعال عادية تدل على حدث ولا تدخل على الجملة الاسمية.","ow":["ذهب فعل عادي يدل على حدث الذهاب.","","كتب فعل عادي يدل على حدث الكتابة.","جلس فعل عادي يدل على حدث الجلوس."]},
  {"q":"أي الأفعال الآتية <b>ليس</b> من كان وأخواتها؟","o":["بات","ما دام","ليس","جاء"],"a":3,"why":"جاء فعل عادي يدل على حدث المجيء وليس ناسخًا، أما بات وما دام وليس فمن كان وأخواتها.","ow":["بات من أخوات كان.","ما دام من أخوات كان.","ليس من أخوات كان.",""]},
  {"q":"يدخل الفعل الناسخ على الجملة:","o":["الفعلية","الاسمية","النداء","الاستفهام"],"a":1,"why":"الأفعال الناسخة تدخل على الجملة الاسمية المكونة من مبتدأ وخبر وتغير إعرابها، ولا تدخل على الجملة الفعلية.","ow":["الجملة الفعلية لا تدخل عليها كان وأخواتها.","","النداء أسلوب لا تدخل عليه الأفعال الناسخة.","الاستفهام أسلوب لا تدخل عليه الأفعال الناسخة."]},
  {"q":"في جملة: <b>كان الرسولُ قدوةً لأصحابه</b> اسم كان هو:","o":["كان","قدوةً","الرسولُ","أصحابه"],"a":2,"why":"اسم كان هو المبتدأ الأصلي بعد دخول كان، وهنا هو الرسول، وبقي مرفوعًا، أما قدوة فهي الخبر المنصوب.","ow":["كان فعل ناسخ وليس اسمها.","قدوةً هي خبر كان وليست اسمها.","","أصحابه جار ومجرور بعد حرف الجر ولا يكون اسم كان."]},
  {"q":"في جملة: <b>كان الرسولُ قدوةً لأصحابه</b> خبر كان هو:","o":["الرسولُ","قدوةً","كان","لأصحابه"],"a":1,"why":"خبر كان هو الخبر الأصلي بعد دخول كان، وهو منصوب، وهنا هو قدوةً، أما الرسول فهو اسم كان المرفوع.","ow":["الرسول هو اسم كان.","","كان فعل ناسخ وليس خبرها.","لأصحابه جار ومجرور متعلق بالخبر وليس الخبر نفسه."]},
  {"q":"علامة نصب خبر كان إذا كان مفردًا:","o":["الضمة","الكسرة","الفتحة","الياء"],"a":2,"why":"خبر كان إذا كان مفردًا يُنصب بالفتحة الظاهرة على آخره، مثل: كان الرسول قدوةً، فالفتحة علامة نصبه.","ow":["الضمة علامة رفع وليست نصبًا.","الكسرة علامة نصب جمع المؤنث السالم وجر.","","الياء علامة نصب المثنى وجمع المذكر السالم."]},
  {"q":"علامة نصب خبر كان إذا كان جمع مؤنث سالمًا:","o":["الفتحة","الكسرة","الألف","الواو"],"a":1,"why":"جمع المؤنث السالم يُنصب بالكسرة نيابة عن الفتحة، فنقول: كانت الطالبات مجتهداتٍ، فعلامة النصب الكسرة.","ow":["الفتحة لنصب المفرد.","","الألف لرفع المثنى.","الواو لرفع جمع المذكر السالم."]},
  {"q":"علامة نصب خبر كان إذا كان مثنى:","o":["الألف","الفتحة","الواو","الياء"],"a":3,"why":"المثنى يُنصب بالياء، فنقول: كان الطالبان مجتهدين، وعلامة نصب مجتهدين الياء لأنه مثنى.","ow":["الألف علامة رفع المثنى.","الفتحة علامة نصب المفرد.","الواو علامة رفع جمع المذكر السالم.",""]},
  {"q":"علامة رفع اسم كان إذا كان مثنى:","o":["الألف","الضمة","الياء","الواو"],"a":0,"why":"اسم كان يبقى مرفوعًا، فإذا كان مثنى رُفع بالألف، مثل: كان الطالبان مجتهدين، فالطالبان اسم كان مرفوع بالألف.","ow":["","الضمة لرفع المفرد.","الياء علامة نصب وجر.","الواو لرفع جمع المذكر السالم."]},
  {"q":"علامة رفع اسم أمسى في: <b>أمسى الفتحُ قريبًا</b>","o":["الفتحة","الضمة","الألف","الواو"],"a":1,"why":"الفتح اسم مفرد، فعلامة رفعه الضمة، فنقول: الفتحُ اسم أمسى مرفوع وعلامة رفعه الضمة.","ow":["الفتحة علامة نصب.","","الألف لرفع المثنى.","الواو لرفع جمع المذكر السالم."]},
  {"q":"الفعل الناسخ <b>ما زال</b> يفيد:","o":["النفي","التحول","الاستمرار","الزمن الماضي"],"a":2,"why":"ما زال تفيد الاستمرار، أي أن الخبر مستمر ولم ينقطع بعد، مثل: ما زال المطر نازلًا.","ow":["النفي يفيده ليس.","التحول يفيده صار.","","الزمن الماضي تفيده كان."]},
  {"q":"الفعل الناسخ <b>ليس</b> يفيد:","o":["النفي","الاستمرار","التحول","الظرفية"],"a":0,"why":"ليس تفيد نفي الخبر عن الاسم، مثل: ليس الكذب فضيلةً، فتنفي صفة الفضيلة عن الكذب، وهي أداة النفي من أخوات كان.","ow":["","الاستمرار تفيده ما زال.","التحول يفيده صار.","الظرفية يفيدها ما دام."]},
  {"q":"الفعل الناسخ <b>أصبح</b> يفيد حدوث الخبر في وقت:","o":["الليل","المساء","الظهر","الصباح"],"a":3,"why":"أصبح تفيد حدوث الخبر في وقت الصباح، مثل: أصبح الجو جميلًا. أما الليل فتفيده بات، والمساء يفيده أمسى.","ow":["الليل تفيده بات.","المساء يفيده أمسى.","الظهر ليس وقتًا مخصصًا لفعل ناسخ.",""]},
  {"q":"الفعل الناسخ <b>بات</b> يفيد حدوث الخبر في وقت:","o":["الليل","الصباح","الضحى","المساء"],"a":0,"why":"بات تفيد حدوث الخبر في وقت الليل، مثل: بات المسافر مرتاحًا. أما الصباح فتفيده أصبح، والمساء تفيده أمسى.","ow":["","الصباح يفيده أصبح.","الضحى يفيده أضحى.","المساء يفيده أمسى."]},
  {"q":"الفعل الناسخ <b>كان</b> يفيد اتصاف اسمها بمعنى خبرها في الزمن:","o":["المستقبل","الماضي","الحاضر فقط","لا زمن"],"a":1,"why":"كان تفيد اتصاف الاسم بمعنى الخبر في الزمن الماضي، مثل: كان الرسول قدوةً لأصحابه، فتدل على الماضي.","ow":["المستقبل لا تفيده كان وحدها.","","كان تدل على زمن وليس الحاضر فقط.","كان تدل على زمن، وهو الماضي."]},
  {"q":"العبارة: الفعل الناسخ يرفع المبتدأ وينصب الخبر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالفعل الناسخ مثل كان يرفع المبتدأ ويسميه اسمه وينصب الخبر ويسميه خبره.","ow":["","العبارة صحيحة، فهذا عمل كان وأخواتها."]},
  {"q":"العبارة: خبر كان يكون مرفوعًا دائمًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فخبر كان منصوب دائمًا، وإنما المرفوع هو اسمها، فنقول: كان الرسول قدوةً.","ow":["خبر كان منصوب وليس مرفوعًا.",""]},
  {"q":"العبارة: <b>صار</b> يفيد التحول.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فصار تفيد التحول، أي انتقال الشيء من حال إلى حال، مثل: صار المسلمون منتصرين.","ow":["","العبارة صحيحة، فصار للتحول."]},
  {"q":"العبارة: <b>ما دام</b> من أخوات كان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فما دام من أخوات كان وتفيد الظرفية، أي بيان الزمن الذي يستمر فيه الخبر.","ow":["","العبارة صحيحة، فما دام من الأفعال الناسخة."]},
  {"q":"العبارة: في <b>صار المسلمون منتصرين</b> علامة نصب الخبر الضمة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فعلامة نصب الخبر في صار المسلمون منتصرين الياء لأنه جمع مذكر سالم، وليست الضمة.","ow":["الضمة علامة رفع وليست علامة نصب خبر صار هنا.",""]},
];
window.BANK['a7']['a7-2-3'] = [
  {"q":"الاستفهام هو طلب:","o":["الفهم أو العلم بشيء لم يكن معلومًا","النفي","التعجب","الأمر"],"a":0,"why":"الاستفهام هو طلب الفهم أو العلم بشيء لم يكن معلومًا، ويكون بإحدى أدوات الاستفهام.","ow":["","النفي ليس هو الاستفهام.","التعجب ليس هو الاستفهام.","الأمر طلب فعل وليس استفهامًا."]},
  {"q":"أسأل بالأداة <b>أين</b> عن:","o":["الزمان","المكان","العدد","الحال"],"a":1,"why":"أين أداة استفهام نسأل بها عن المكان، مثل: أين تقع مكة؟ فجوابها مكان، وليست للزمان ولا للعدد.","ow":["الزمان نسأل عنه بمتى.","","العدد نسأل عنه بكم.","الحال نسأل عنه بكيف."]},
  {"q":"أسأل عن الحال بالأداة:","o":["أين","كم","كيف","متى"],"a":2,"why":"كيف أداة استفهام نسأل بها عن الحال، مثل: كيف حالك؟ فهي تسأل عن حال الإنسان أو الشيء وليس عن مكانه.","ow":["أين تسأل عن المكان.","كم تسأل عن العدد.","","متى تسأل عن الزمان."]},
  {"q":"أسأل عن الزمان بالأداة:","o":["أين","كم","كيف","متى"],"a":3,"why":"متى أداة استفهام نسأل بها عن الزمان، مثل: متى بدأ الرسول دعوته؟ فهي تسأل عن وقت وقوع الحدث.","ow":["أين تسأل عن المكان.","كم تسأل عن العدد.","كيف تسأل عن الحال.",""]},
  {"q":"أسأل عن العدد بالأداة:","o":["كم","لماذا","من","هل"],"a":0,"why":"كم أداة استفهام نسأل بها عن العدد، مثل: كم عاش رسول الله ﷺ؟ فهي تسأل عن الكمية وليس عن العلة.","ow":["","لماذا تسأل عن العلة.","من تسأل عن العاقل.","هل تسأل عن التصديق."]},
  {"q":"أسأل عن العلة بالأداة:","o":["من","ما","لماذا","هل"],"a":2,"why":"لماذا أداة استفهام نسأل بها عن العلة أي السبب، مثل: لماذا هاجر الرسول ﷺ؟ فهي تبحث عن سبب الحدث.","ow":["من تسأل عن العاقل.","ما تسأل عن غير العاقل.","","هل تسأل عن التصديق."]},
  {"q":"أسأل عن العاقل بالأداة:","o":["ما","مَن","متى","أين"],"a":1,"why":"من أداة استفهام نسأل بها عن العاقل أي الإنسان، مثل: من فتح مكة؟ أما غير العاقل فنسأل عنه بما.","ow":["ما تسأل عن غير العاقل.","","متى تسأل عن الزمان.","أين تسأل عن المكان."]},
  {"q":"أسأل عن غير العاقل بالأداة:","o":["مَن","ما","كم","هل"],"a":1,"why":"ما أداة استفهام نسأل بها عن غير العاقل، مثل: ما هذا؟ أما العاقل أي الإنسان فنسأل عنه بمن.","ow":["من تسأل عن العاقل.","","كم تسأل عن العدد.","هل تسأل عن التصديق."]},
  {"q":"يُسأل بالأداة <b>هل</b> عن:","o":["التصديق","المكان","العدد","الزمان"],"a":0,"why":"هل أداة استفهام نسأل بها عن التصديق، أي هل الأمر صحيح أم لا، فنجيب بنعم أو لا، وليس بمكان ولا عدد.","ow":["","المكان نسأل عنه بأين.","العدد نسأل عنه بكم.","الزمان نسأل عنه بمتى."]},
  {"q":"الهمزة للتصديق، وجوابها يكون بـ:","o":["أحد الأمرين المذكورين","نعم أو لا","العدد","المكان"],"a":1,"why":"الهمزة التي للتصديق يكون جوابها بنعم أو لا، لأن السائل لا يعرف هل الأمر صحيح، فيجاب بالإثبات أو النفي.","ow":["أحد الأمرين المذكورين جواب الهمزة التي للتعيين.","","العدد جواب كم وليس الهمزة.","المكان جواب أين وليس الهمزة."]},
  {"q":"الهمزة للتعيين، وجوابها يكون:","o":["نعم أو لا","بلى","تعيين واحد مما ذُكر في السؤال","بالسكوت"],"a":2,"why":"الهمزة التي للتعيين يكون جوابها بتعيين واحد مما ذُكر في السؤال، لأن السائل يعرف المضمون ويريد معرفة أيهما.","ow":["نعم أو لا جواب الهمزة التي للتصديق.","بلى جواب سؤال منفي في الإثبات.","","السكوت ليس جوابًا للاستفهام."]},
  {"q":"في سؤال: <b>أزيدٌ خادمُ الرسول أم ابن مسعود؟</b> الهمزة تفيد:","o":["التصديق","النفي","التعجب","التعيين"],"a":3,"why":"في أزيدٌ خادمُ الرسول أم ابن مسعود؟ جاء بعد الهمزة اسمان بينهما أم، فالسائل يريد تعيين أحدهما، فهي للتعيين.","ow":["التصديق جوابه نعم أو لا.","النفي ليس معنى الهمزة هنا.","التعجب ليس معنى الهمزة هنا.",""]},
  {"q":"في سؤال: <b>أتعرف واجبك تجاه الرسول؟</b> الهمزة تفيد:","o":["التصديق","التعيين","النفي","العدد"],"a":0,"why":"في أتعرف واجبك تجاه الرسول؟ نسأل هل يعرف أم لا، فجوابها نعم أو لا، فالهمزة للتصديق.","ow":["","التعيين يكون بين أمرين مذكورين في السؤال.","النفي ليس معنى الهمزة هنا.","العدد تسأل عنه كم وليس الهمزة."]},
  {"q":"الاستفهام غير الحقيقي هو الذي:","o":["يُطلب به جواب","لا يُطلب به جواب ويخرج إلى معانٍ أخرى","يُطلب به العدد","لا يوجد"],"a":1,"why":"الاستفهام غير الحقيقي هو الذي لا يُطلب به جواب لأن السائل لا يريد معلومة، ويخرج إلى معانٍ أخرى كالإنكار.","ow":["الذي يطلب به جواب هو الاستفهام الحقيقي.","","العدد يُطلب بكم وهو استفهام حقيقي.","يوجد استفهام غير حقيقي ولا يُطلب به جواب."]},
  {"q":"الاستفهام الحقيقي هو الذي:","o":["لا جواب له","يخرج إلى معنى الإنكار","يُطلب به معرفة شيء مجهول لدى السائل","للتهديد فقط"],"a":2,"why":"الاستفهام الحقيقي هو الذي يُطلب به معرفة شيء مجهول لدى السائل، فيريد جوابًا حقيقيًا.","ow":["الذي لا جواب له هو الاستفهام غير الحقيقي.","الذي يخرج إلى الإنكار هو غير الحقيقي.","","التهديد معنى يخرج إليه الاستفهام غير الحقيقي."]},
  {"q":"العبارة: <b>كم</b> يُسأل بها عن العدد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فكم أداة استفهام نسأل بها عن العدد، مثل: كم عاش الرسول ﷺ؟ فهي تسأل عن الكمية.","ow":["","العبارة صحيحة، فكم للعدد."]},
  {"q":"العبارة: <b>مَن</b> يُسأل بها عن غير العاقل.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فمن يُسأل بها عن العاقل أي الإنسان، أما غير العاقل فنسأل عنه بأداة الاستفهام ما.","ow":["من للعاقل وليست لغير العاقل.",""]},
  {"q":"العبارة: جواب الهمزة التي بعدها نفي في حالة النفي يكون بـ <b>نعم</b>.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجواب الهمزة التي بعدها نفي في حالة النفي يكون بنعم، وفي الإثبات بلى.","ow":["","العبارة صحيحة، فنعم لتأكيد النفي."]},
  {"q":"العبارة: جواب الهمزة التي بعدها نفي في حالة الإثبات يكون بـ <b>نعم</b>.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فجواب الهمزة التي بعدها نفي في حالة الإثبات يكون ببلى، لا بنعم، فبلى تبطل النفي.","ow":["نعم لا تُستعمل لإثبات المنفي، بل بلى.",""]},
  {"q":"العبارة: <b>أين</b> أداة استفهام عن المكان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأين أداة استفهام نسأل بها عن المكان، مثل: أين تقع المدينة؟ فهي تدل على المكان.","ow":["","العبارة صحيحة، فأين تدل على المكان."]},
];
window.BANK['a7']['a7-2-4'] = [
  {"q":"همزة القطع تُنطق:","o":["في بدء الكلام ووصله","في بدء الكلام فقط","عند الوصل فقط","لا تُنطق"],"a":0,"why":"همزة القطع تُنطق في بدء الكلام ووصله، أي في الحالتين، فلا تسقط، مثل: أخذ وفأخذنا.","ow":["","في بدء الكلام فقط تصف همزة الوصل.","عند الوصل فقط ليس صحيحًا، فهي تُنطق في الابتداء أيضًا.","همزة القطع تُنطق ولا يصح أنها لا تُنطق."]},
  {"q":"تُكتب همزة القطع المفتوحة أو المضمومة:","o":["تحت الألف","فوق الألف","ألفًا دون همزة","على واو"],"a":1,"why":"همزة القطع المفتوحة أو المضمومة تُكتب فوق الألف هكذا أ، مثل: أَكَلَ وأُعلِنُ، وتُكتب المكسورة تحت الألف.","ow":["تحت الألف تُكتب الهمزة المكسورة.","","ألف دون همزة هي همزة الوصل.","الواو ليست مكان كتابة همزة القطع في أول الكلمة."]},
  {"q":"همزة القطع التي حركتها الكسرة تُكتب:","o":["فوق الألف","دون همزة","تحت الألف","على ياء"],"a":2,"why":"همزة القطع المكسورة تُكتب تحت الألف هكذا إ، مثل: إسراع وإحسان، أما المفتوحة والمضمومة فتُكتب فوق الألف.","ow":["فوق الألف تُكتب الهمزة المفتوحة أو المضمومة.","دون همزة هو رسم همزة الوصل.","","الياء لا تُكتب عليها همزة القطع في أول الكلمة."]},
  {"q":"أي الأفعال الآتية همزته همزة قطع؟","o":["استأجرَ","انكسرَ","ائتمرَ","أسرعَ"],"a":3,"why":"أسرعَ فعل ماضٍ رباعي وهمزته همزة قطع. أما استأجرَ وانكسرَ وائتمرَ فهمزاتها همزات وصل.","ow":["استأجرَ ماضٍ سداسي وهمزته وصل.","انكسرَ ماضٍ خماسي وهمزته وصل.","ائتمرَ ماضٍ خماسي وهمزته وصل.",""]},
  {"q":"مصدر الفعل الرباعي <b>أسرعَ</b>:","o":["إسراعًا","أسرِعْ","سريعٌ","مسرعٌ"],"a":0,"why":"أسرعَ فعل رباعي، ومصدره يكون بهمزة قطع هو إسراعًا، وأمره أسرِعْ، فلا نخلط بين المصدر والأمر.","ow":["","أسرِعْ أمر الفعل وليس المصدر.","سريعٌ صفة وليست مصدر أسرعَ.","مسرعٌ اسم فاعل وليس مصدرًا."]},
  {"q":"الأمر من الفعل الرباعي <b>أعلنَ</b>:","o":["أعلانًا","أعلِنْ","اعلَنْ","يعلنُ"],"a":1,"why":"أعلنَ فعل رباعي، وأمر الفعل الرباعي يبدأ بهمزة قطع، فنقول: أعلِنْ، وتُكتب الهمزة فوق الألف.","ow":["أعلانًا ليست كلمة صحيحة.","","اعلَنْ بهمزة وصل خطأ لأن أمر الرباعي همزته قطع.","يعلنُ فعل مضارع وليس أمرًا."]},
  {"q":"مصدر الفعل الرباعي <b>أحسنَ</b>:","o":["حسنٌ","أحسِنْ","إحسانًا","محسنٌ"],"a":2,"why":"أحسنَ فعل رباعي، ومصدره يكون بهمزة قطع هو إحسانًا، وأمره أحسِنْ، فلا نخلط بين المصدر والأمر.","ow":["حسنٌ صفة أو اسم وليس مصدر أحسنَ.","أحسِنْ أمر وليس مصدرًا.","","محسنٌ اسم فاعل وليس مصدرًا."]},
  {"q":"مصدر الفعل الثلاثي المهموز <b>أخذَ</b>:","o":["أخذًا","إخذًا","آخذٌ","مأخوذ"],"a":0,"why":"أخذَ فعل ثلاثي مهموز، ومصدره أخذًا بهمزة قطع. أما إخذًا فليست مصدره، وآخذٌ اسم فاعل، ومأخوذ اسم مفعول.","ow":["","إخذًا ليس مصدر الفعل أخذ.","آخذٌ اسم فاعل وليس مصدرًا.","مأخوذ اسم مفعول وليس مصدرًا."]},
  {"q":"همزة المضارع للمتكلم في <b>أختارُ</b> همزة:","o":["وصل","قطع","متوسطة","متطرفة"],"a":1,"why":"أختارُ مضارع للمتكلم، وهمزة المضارع للمتكلم همزة قطع تُنطق دائمًا، فلا تسقط عند وصل الكلام.","ow":["الوصل لا يكون في المضارع للمتكلم.","","المتوسطة تكون في وسط الكلمة.","المتطرفة تكون في آخر الكلمة."]},
  {"q":"همزة الحروف قطع ما عدا:","o":["أو","أنْ","إنّ","ال التعريف"],"a":3,"why":"الحروف همزتها قطع، إلا ال التعريف فهمزتها وصل. أما أو وأنْ وإنّ ففيها همزة قطع تُنطق دائمًا.","ow":["أو حرف همزته قطع.","أنْ حرف همزته قطع.","إنّ حرف همزته قطع.",""]},
  {"q":"أي الحروف الآتية همزته همزة قطع؟","o":["ال","أو","ابن","اسم"],"a":1,"why":"أو حرف همزته همزة قطع، وكل الحروف كذلك إلا ال التعريف. أما ابن واسم فاسمان همزتهما وصل.","ow":["ال التعريف همزتها وصل.","","ابن اسم همزته وصل.","اسم اسم همزته وصل."]},
  {"q":"أمر الفعل <b>أخذَ</b> هو:","o":["اُخذْ","أخِذْ","خُذْ","إخذ"],"a":2,"why":"أمر الفعل أخذ هو خُذْ بلا همزة، لأن الهمزة تُحذف في أمر بعض الأفعال المهموزة مثل أخذ وأكل.","ow":["اُخذْ خطأ لأن الهمزة تُحذف.","أخِذْ ليس أمر الفعل أخذ.","","إخذ ليس أمر الفعل أخذ."]},
  {"q":"أمر الفعل <b>أكلَ</b> هو:","o":["كُلْ","اُكلْ","أكلْ","إكلْ"],"a":0,"why":"أمر الفعل أكل هو كُلْ بلا همزة، وهذا من الأفعال المهموزة التي تُحذف همزتها في الأمر، مثل أخذ.","ow":["","اُكلْ خطأ لأن الهمزة تُحذف.","أكلْ ليس أمر الفعل أكل.","إكلْ ليس أمر الفعل أكل."]},
  {"q":"سُمّيت همزة القطع بذلك لأنها:","o":["تقطع لفظ ما قبلها عما بعدها","تُحذف","تُكتب في الوسط","تُنطق في الوصل فقط"],"a":0,"why":"سُميت همزة القطع بذلك لأنها تقطع لفظ ما قبلها عما بعدها، فتُنطق دائمًا ولا تسقط عند الوصل.","ow":["","همزة القطع لا تُحذف.","همزة القطع في أول الكلمة غالبًا وليس وسطها فقط.","همزة القطع تُنطق في الابتداء والوصل."]},
  {"q":"الفعل الثلاثي المهموز مثل:","o":["أَمَرَ","استأجرَ","انكسرَ","ائتمرَ"],"a":0,"why":"أَمَرَ فعل ثلاثي مهموز همزته همزة قطع. أما استأجرَ وانكسرَ وائتمرَ فهمزاتها همزات وصل لأنها خماسية أو سداسية.","ow":["","استأجرَ ماضٍ سداسي همزته وصل.","انكسرَ ماضٍ خماسي همزته وصل.","ائتمرَ ماضٍ خماسي همزته وصل."]},
  {"q":"العبارة: همزة القطع تُنطق في بدء الكلام ووصله.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فهمزة القطع تُنطق في بدء الكلام ووصله، مثل: أخذ وفأخذنا، فلا تسقط في الوصل.","ow":["","العبارة صحيحة، فهي لا تسقط في الوصل."]},
  {"q":"العبارة: الهمزة المكسورة تُكتب فوق الألف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالهمزة المكسورة تُكتب تحت الألف هكذا إ، أما فوق الألف فللمفتوحة والمضمومة.","ow":["الهمزة المكسورة تُكتب تحت الألف وليست فوقها.",""]},
  {"q":"العبارة: الأسماء همزتها قطع، إلا السماعية ومصادر الخماسي والسداسي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأسماء همزتها همزة قطع إلا الأسماء السماعية ومصادر الأفعال الخماسية والسداسية فهمزتها وصل.","ow":["","العبارة صحيحة، فهذه هي القاعدة في الأسماء."]},
  {"q":"العبارة: همزة (ال) التعريف همزة قطع.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فهمزة ال التعريف همزة وصل وليست قطعًا، فلا تُنطق عند وصل الكلام بما قبلها.","ow":["همزة ال التعريف وصل وليست قطعًا.",""]},
  {"q":"العبارة: الفعل <b>أسرعَ</b> همزته قطع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأسرعَ فعل رباعي وهمزته همزة قطع تُنطق دائمًا، فنقول: أسرع فأسرع بلا سقوط للهمزة.","ow":["","العبارة صحيحة، فأسرع رباعي وليس خماسيًا."]},
];
window.BANK['a7']['a7-2-5'] = [
  {"q":"الألف المنفردة في خط الرقعة هي:","o":["خط أفقي","خط مقوّس","خط رأسي من أعلى إلى أسفل","نقطة"],"a":2,"why":"الألف المنفردة في خط الرقعة خط رأسي ينزل من أعلى إلى أسفل دون حلية، فهي بسيطة وليست أفقية ولا مقوّسة.","ow":["الخط الأفقي تُكتب به حروف مثل الباء.","الخط المقوّس تُكتب به حروف مثل العين.","","النقطة لا تمثل الألف."]},
  {"q":"تميل الألف المنفردة في الرقعة قليلًا نحو:","o":["اليمين","اليسار","الأسفل","لا تميل"],"a":0,"why":"تميل الألف المنفردة في الرقعة قليلًا نحو اليمين، فلا تكون مستقيمة تمامًا، وهذا الميل خفيف.","ow":["","اليسار ليس اتجاه الميل.","الأسفل ليس اتجاه ميل الألف.","الألف في الرقعة تميل ميلًا خفيفًا."]},
  {"q":"الألف في خط الرقعة تكون:","o":["بحلية","دون حلية","مزخرفة","مقوّسة"],"a":1,"why":"الألف في خط الرقعة تُكتب دون حلية، أي دون زخرفة، لأن الرقعة خط بسيط وسريع، أما الحلية ففي النسخ.","ow":["الحلية في النسخ وليست في الرقعة.","","الألف في الرقعة بسيطة غير مزخرفة.","الألف رأسية وليست مقوّسة."]},
  {"q":"تتصل الألف المتصلة بما قبلها بوصلة:","o":["نازلة","مقوّسة","صاعدة بزاوية قائمة","أفقية"],"a":2,"why":"الألف المتصلة تتصل بالحرف الذي قبلها بوصلة صاعدة من أسفل إلى أعلى وبزاوية قائمة، وهذا هو الصحيح في الرقعة.","ow":["الوصلة النازلة ليست طريقة اتصال الألف.","الوصلة المقوّسة ليست طريقة اتصالها في الرقعة.","","الوصلة الأفقية ليست طريقة اتصالها في الرقعة."]},
  {"q":"الصعود في خط الرقعة يكون:","o":["بدوران","بزاوية قائمة","بخط متقطع","بنقطة"],"a":1,"why":"الصعود في خط الرقعة يكون بزاوية قائمة، أما في خط النسخ فيكون بدوران، وهذا من الفروق بين الخطين.","ow":["الدوران صفة الصعود في النسخ.","","الصعود لا يكون بخط متقطع.","الصعود لا يكون بنقطة."]},
  {"q":"من الحروف الصاعدة في الرقعة:","o":["ل","ب","ن","س"],"a":0,"why":"الحروف الصاعدة في الرقعة هي ا ل ك د لا ه، فاللام منها لأنها ترتفع فوق السطر، أما ب وي وس فليست منها.","ow":["","الباء ليست من الحروف الصاعدة.","النون ليست من الحروف الصاعدة.","السين ليست من الحروف الصاعدة."]},
  {"q":"أي الحروف الآتية صاعد في خط الرقعة؟","o":["ب","ن","س","ك"],"a":3,"why":"الكاف من الحروف الصاعدة في الرقعة مع ا ل د لا ه، أما ب ون وس فليست من الحروف الصاعدة.","ow":["الباء ليست من الحروف الصاعدة.","النون ليست من الحروف الصاعدة.","السين ليست من الحروف الصاعدة.",""]},
  {"q":"همزة الألف المنفردة في الرقعة شكلها يشبه:","o":["رأس الياء","رأس الدال","رأس الميم","النقطة"],"a":0,"why":"همزة الألف المنفردة في الرقعة تشبه رأس الياء، فهي نقطة صغيرة مدورة فوق الخط، وليس رأس الدال ولا الميم.","ow":["","رأس الدال ليس هو الشكل المقصود.","رأس الميم ليس هو الشكل المقصود.","النقطة تقريب فقط، والشكل المقصود رأس الياء."]},
  {"q":"في رسم <b>لا</b> بخط الرقعة ترسم الألف:","o":["فوق اللام","في وسط اللام موازية لرأسها","تحت اللام","منفصلة بعيدة"],"a":1,"why":"في لا بخط الرقعة نكتب اللام والألف معًا، فنرسم الألف في وسط اللام موازية لرأسها.","ow":["فوق اللام ليس موضع الألف.","","تحت اللام ليس موضع الألف.","الألف لا تُنفصل بعيدًا في لا."]},
  {"q":"في كلمة <b>أعالمنا</b> الألف الثانية (في الوسط):","o":["منفردة","متصلة بالعين","محذوفة","مزخرفة"],"a":1,"why":"في أعالمنا الألف الوسطى متصلة بالعين التي قبلها بوصلة صاعدة بزاوية قائمة، فهي ليست منفردة.","ow":["الألف الوسطى ليست منفردة لأن قبلها حرفًا.","","الألف لا تُحذف.","الألف في الرقعة لا تُزخرف."]},
  {"q":"في كلمة <b>أعالمنا</b> الألف الأولى في البدء:","o":["متصلة بما قبلها","منفردة","محذوفة","مقوّسة"],"a":1,"why":"الدقة في اختيار الألفاظ من مميزات الحوار الجيد، فتكون الألفاظ دقيقة وواضحة. أما الغموض والإطالة والتشعب فكلها عيوب.","ow":["الألف الأولى ليس قبلها حرف لتتصل به.","","الألف لا تُحذف.","الألف في الرقعة ليست مقوّسة."]},
  {"q":"الفرق بين ألف النسخ وألف الرقعة أن ميل الرقعة:","o":["أخف","أكثر","معدوم","للأسفل"],"a":0,"why":"الألف في الرقعة تميل ميلًا أخف من ميل الألف في النسخ، وهذا من الفروق بين الخطين.","ow":["","الميل في الرقعة ليس أكثر من النسخ.","ميل الألف في الرقعة موجود لكنه خفيف.","الألف لا تميل للأسفل."]},
  {"q":"من خطوات التدرب على رسم الحرف:","o":["إهمال الشكل","ملاحظة شكل الحرف وإعادة كتابته مرات","الكتابة بلا تركيز","الاعتماد على الحفظ فقط"],"a":1,"why":"من خطوات التدرب على رسم الحرف أن ألاحظ شكله ثم أرسمه وأعيد الكتابة عدة مرات حتى أتقنه.","ow":["إهمال الشكل يضيع جمال الخط.","","الكتابة بلا تركيز تضعف جودة الخط.","الحفظ وحده لا يكفي لإتقان الرسم."]},
  {"q":"الألف حرف:","o":["صاعد","نازل","أفقي","منقوط"],"a":0,"why":"الألف من الحروف الصاعدة في الرقعة مثل ل ك د لا ه، فهي ترتفع عن السطر قليلًا ولا تنزل تحته.","ow":["","الألف لا تنزل تحت السطر.","الألف لا تُكتب أفقية.","الألف ليس فيها نقط."]},
  {"q":"الألف المنفردة في الرقعة خط رأسي يكون:","o":["مرتفعًا عن السطر","نازلًا تحت السطر","أفقيًا على السطر","مقوّسًا"],"a":0,"why":"الألف المنفردة خط رأسي يرتفع عن السطر شيئًا ويميل إلى اليمين قليلًا، فلا تنزل تحت السطر ولا تكون أفقية.","ow":["","الألف لا تنزل تحت السطر.","الألف ليست أفقية.","الألف ليست مقوّسة."]},
  {"q":"العبارة: الألف المنفردة في خط الرقعة خط رأسي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالألف المنفردة في خط الرقعة خط رأسي ينزل من أعلى إلى أسفل دون حلية.","ow":["","العبارة صحيحة، فهي رأسية وليست أفقية."]},
  {"q":"العبارة: في خط الرقعة تتصل الألف بما قبلها بدوران.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالألف تتصل بما قبلها في الرقعة بوصلة صاعدة بزاوية قائمة، وليس بدوران.","ow":["الاتصال في الرقعة بزاوية قائمة وليس بدوران.",""]},
  {"q":"العبارة: <b>ل</b> من الحروف الصاعدة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فاللام من الحروف الصاعدة في الرقعة مع ا ك د لا ه، فهي ترتفع فوق السطر.","ow":["","العبارة صحيحة، فاللام ترتفع فوق السطر."]},
  {"q":"العبارة: الألف في الرقعة لها حلية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالألف في خط الرقعة تُكتب دون حلية لأن الرقعة خط بسيط، أما الحلية ففي خط النسخ.","ow":["الحلية في النسخ وليس في الرقعة.",""]},
  {"q":"العبارة: ميل ألف الرقعة أخف من ميل ألف النسخ.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فميل الألف في الرقعة خفيف، أخف من ميل الألف في النسخ، وهذا من الفروق بين الخطين.","ow":["","العبارة صحيحة، فالرقعة أخف ميلًا."]},
];
window.BANK['a7']['a7-2-6'] = [
  {"q":"الحوار محادثة بين:","o":["طرف واحد","طرفين أو أكثر","ثلاثة فقط","لا أحد"],"a":1,"why":"الحوار محادثة بين طرفين أو أكثر حول موضوع مطروح، فلا يكون الحوار من طرف واحد، لأن لا بد من أحد يرد.","ow":["طرف واحد لا يصنع حوارًا لأنه لا يوجد من يرد.","","ثلاثة فقط تحديد خاطئ، فالحوار يكون بين طرفين أو أكثر.","لا أحد يعني عدم وجود حوار."]},
  {"q":"تتنامى في الحوار:","o":["الأصوات","أفكار الموضوع حتى تتضح جوانبه","الأرقام","الأسماء"],"a":1,"why":"تتنامى في الحوار أفكار الموضوع حتى تتضح جوانبه كلها، فكل طرف يضيف فكرة فيزداد الموضوع وضوحًا.","ow":["الأصوات لا تتنامى، فالحوار ليس عن علو الصوت.","","الأرقام ليست ما يتنامى في الحوار.","الأسماء ليست ما يتنامى في الحوار."]},
  {"q":"موضوع الحوار الذي درسناه في الكتاب (الراوي والشيخ):","o":["الصحة","العلم والجهل","السفر","التجارة"],"a":1,"why":"موضوع الحوار في الكتاب بين الراوي والشيخ هو العلم والجهل، فالشيخ رأى الجهل نعمة والراوي رأى العلم نورًا.","ow":["الصحة ليست موضوع هذا الحوار.","","السفر ليس موضوع هذا الحوار.","التجارة ليست موضوع هذا الحوار."]},
  {"q":"طرفا الحوار في الكتاب:","o":["الراوي وشيخ من شيوخ الحارة","الأب والابن","المعلم والطالب","البائع والمشتري"],"a":0,"why":"طرفا الحوار في الكتاب هما الراوي وشيخ من شيوخ الحارة، وقد دار بينهما كلام عن العلم والجهل.","ow":["","الأب والابن ليسا طرفي هذا الحوار.","المعلم والطالب ليسا طرفي هذا الحوار.","البائع والمشتري ليسا طرفي هذا الحوار."]},
  {"q":"أي الآتي مهارة من مهارات الحوار؟","o":["مقاطعة المتكلم","الخروج عن الموضوع","مراعاة آداب الحوار","رفع الصوت"],"a":2,"why":"من مهارات الحوار مراعاة آداب الحوار، مثل احترام الآخر وعدم رفع الصوت والتزام الموضوع.","ow":["مقاطعة المتكلم تفسد الحوار.","الخروج عن الموضوع يفسد الحوار.","","رفع الصوت ليس من آداب الحوار."]},
  {"q":"في مهارات الحوار نصوغ الحوار:","o":["صياغة الحوار بلغتي الخاصة ورأيي الخاص","نسخ حوار جاهز","الإطالة","إخفاء الرأي"],"a":0,"why":"من مهارات الحوار أن نصوغ الحوار بلغتنا الخاصة وبرأينا الخاص، فلا ننسخ كلام غيرنا.","ow":["","نسخ حوار جاهز يخالف الصياغة بلغتنا.","الإطالة ليست من مهارات الحوار.","إخفاء الرأي يخالف مهارة صياغة الحوار برأينا."]},
  {"q":"تدعيم الرأي في الحوار يكون بـ:","o":["الأدلة والشواهد المناسبة","الصراخ","الإطالة","تكرار الكلام"],"a":0,"why":"تدعيم الرأي في الحوار يكون بالأدلة والشواهد المناسبة، فهذا أقوى وسيلة للإقناع، أما الصراخ والإطالة فلا يقنعان.","ow":["","الصراخ لا يقوّي الرأي.","الإطالة لا تقوّي الرأي.","تكرار الكلام لا يقوّي الرأي."]},
  {"q":"يفسد الحوار:","o":["احترام الدور","التزام الموضوع","مقاطعة المتكلم","الدقة في الألفاظ"],"a":2,"why":"المقاطعة تفسد الحوار لأن المتكلم لا يكمل فكرته. أما احترام الدور والتزام الموضوع والدقة فمن مميزاته.","ow":["احترام الدور ميزة من مميزات الحوار.","التزام الموضوع ميزة من مميزات الحوار.","","الدقة في الألفاظ ميزة من مميزات الحوار."]},
  {"q":"أي الآتي يُفسد الحوار؟","o":["الخروج عن الموضوع","احترام رأي الآخر","تجنب الحشو","الموضوعية"],"a":0,"why":"الخروج عن الموضوع يفسد الحوار لأنه يشتت الأفكار. أما احترام رأي الآخر وتجنب الحشو والموضوعية فمن مميزات الحوار.","ow":["","احترام رأي الآخر ميزة من مميزات الحوار.","تجنب الحشو ميزة من مميزات الحوار.","الموضوعية ميزة من مميزات الحوار."]},
  {"q":"من مميزات الحوار الجيد:","o":["الحشو والإطالة","احترام رأي الآخر","مقاطعة المتكلم","التسرع"],"a":1,"why":"من مميزات الحوار الجيد احترام رأي الآخر والاستماع له. أما الحشو والإطالة والمقاطعة والتسرع فعيوب.","ow":["الحشو والإطالة عيب يفسد الحوار.","","مقاطعة المتكلم عيب يفسد الحوار.","التسرع عيب يضعف الحوار."]},
  {"q":"أي الآتي ميزة من ميزات الحوار الجيد؟","o":["غموض الألفاظ","الدقة في اختيار الألفاظ","الإطالة","التشعب"],"a":1,"why":"الدقة في اختيار الألفاظ من مميزات الحوار الجيد، فتكون الألفاظ دقيقة وواضحة. أما الغموض والإطالة والتشعب فعيوب.","ow":["غموض الألفاظ عيب في الحوار.","","الإطالة عيب في الحوار.","التشعب في أفكار كثيرة عيب في الحوار."]},
  {"q":"عند كتابة الحوار نراعي:","o":["علامات الترقيم","حذف الأطراف","عدم تحديد الموضوع","الإهمال"],"a":0,"why":"عند كتابة الحوار نراعي علامات الترقيم لتوضيح كلام كل طرف. أما حذف الأطراف وإهمال الموضوع فيفسدان الحوار.","ow":["","حذف الأطراف يفسد الحوار.","عدم تحديد الموضوع يفسد الحوار.","الإهمال يفسد جودة الكتابة."]},
  {"q":"من وسائل الإقناع والتأثير في الحوار:","o":["الأدلة والشواهد","الصمت","الصياح","التجاهل"],"a":0,"why":"من وسائل الإقناع والتأثير في الحوار الأدلة والشواهد المناسبة. أما الصمت والصياح والتجاهل فلا تقنع أحدًا.","ow":["","الصمت لا يقنع الطرف الآخر.","الصياح لا يقنع الطرف الآخر.","التجاهل لا يقنع الطرف الآخر."]},
  {"q":"في حوار «وصارت السماء قريبة» الطرفان هما:","o":["محمد والعالم الجليل","الراوي والشيخ","خالد وأخوه","التاجر والصانع"],"a":0,"why":"في حوار وصارت السماء قريبة الطرفان هما محمد والعالم الجليل، كما ورد في الكتاب، وليس الراوي والشيخ.","ow":["","الراوي والشيخ طرفا حوار آخر.","خالد وأخوه ليسا طرفي هذا الحوار.","التاجر والصانع ليسا طرفي هذا الحوار."]},
  {"q":"في حوار «وصارت السماء قريبة» وسيلة الاقتراب من النجوم هي:","o":["الطائرة","المرصد","السيارة","السفينة"],"a":1,"why":"في حوار وصارت السماء قريبة وسيلة الاقتراب من النجوم هي المرصد، وبه صارت السماء قريبة.","ow":["الطائرة ليست الوسيلة المذكورة.","","السيارة ليست الوسيلة المذكورة.","السفينة ليست الوسيلة المذكورة."]},
  {"q":"العبارة: الحوار محادثة بين طرفين أو أكثر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالحوار محادثة بين طرفين أو أكثر حول موضوع مطروح، وتنمو أفكاره حتى تتضح.","ow":["","العبارة صحيحة، فهذا هو تعريف الحوار."]},
  {"q":"العبارة: مقاطعة المتكلم من مميزات الحوار الجيد.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فمقاطعة المتكلم تفسد الحوار لأنها تمنعه من إكمال فكرته، فهي ليست من مميزاته.","ow":["المقاطعة عيب وليست ميزة.",""]},
  {"q":"العبارة: من مهارات الحوار تدعيم الرأي بالأدلة والشواهد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن مهارات الحوار تدعيم الرأي بالأدلة والشواهد المناسبة حتى يقتنع الآخر.","ow":["","العبارة صحيحة، فالدليل مهارة أساسية في الحوار."]},
  {"q":"العبارة: نحدد موضوع الحوار وأطرافه وهدفه عند كتابته.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن خطوات كتابة الحوار تحديد الموضوع والأطراف والهدف، ثم نكتب كلام كل طرف.","ow":["","العبارة صحيحة، فهذه أول خطوات كتابة الحوار."]},
  {"q":"العبارة: الخروج عن الموضوع يُحسّن الحوار.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالخروج عن الموضوع يفسد الحوار ويشتت أفكاره، فلا يحسّنه، والمطلوب التزام الموضوع.","ow":["الخروج عن الموضوع يفسد الحوار، فلا تصح العبارة.",""]},
];
window.BANK['a7']['a7-2-7'] = [
  {"q":"معنى <b>عادَ</b> في: عادَ خالدٌ المريضَ","o":["زار","رجع","حارب","اهتدى"],"a":0,"why":"عادَ خالدٌ المريضَ أي زاره، لأن الجملة تتحدث عن مريض، والمعنى الذي يناسبها هو الزيارة.","ow":["","رجع هو معنى عاد في جملة أخرى.","حارب هو معنى عادى مع الشرك.","اهتدى هو معنى عاد مع الضال."]},
  {"q":"معنى <b>عادَ</b> في: عادَ محمدٌ من المدرسة","o":["زار","حارب","رجع","اهتدى"],"a":2,"why":"عادَ محمدٌ من المدرسة أي رجع، لأنه كان في المدرسة ثم عاد منها إلى بيته، فمعنى عاد هنا هو الرجوع.","ow":["زار هو معنى عاد مع المريض.","حارب هو معنى عادى مع الشرك.","","اهتدى هو معنى عاد مع الضال."]},
  {"q":"معنى <b>عادَى</b> في: عادَى الشركَ بالله","o":["زار","رجع","اهتدى","حارب"],"a":3,"why":"عادَى الشركَ بالله أي حاربه، فالمعنى يتغير بحسب الجملة، والمعنى هنا هو المحاربة والعداوة للشرك.","ow":["زار هو معنى عاد المريض.","رجع هو معنى عاد من المدرسة.","اهتدى هو معنى عاد الضال إلى رشده.",""]},
  {"q":"معنى <b>عادَ</b> في: عادَ الضالُّ إلى رشده","o":["اهتدى","زار","حارب","ذهب"],"a":0,"why":"عادَ الضالُّ إلى رشده أي اهتدى، أي رجع إلى الطريق الصحيح، وهذا هو المعنى المناسب للسياق.","ow":["","زار هو معنى عاد المريض.","حارب هو معنى عادى الشرك.","ذهب ليس معنى عاد هنا."]},
  {"q":"معنى <b>تضافروا</b>:","o":["تفرقوا","تعاونوا","تخاصموا","ذهبوا"],"a":1,"why":"تضافروا معناها تعاونوا، أي ساعد بعضهم بعضًا واتحدت جهودهم، وهي عكس تفرقوا وتخاصموا.","ow":["تفرقوا عكس تضافروا.","","تخاصموا عكس تضافروا.","ذهبوا ليس معنى تضافروا."]},
  {"q":"معنى <b>سَبَرَ أحوالَهم</b>:","o":["أهملهم","اختبرهم","ظلمهم","سافر إليهم"],"a":1,"why":"سَبَرَ أحوالَهم أي اختبرهم وعرف أحوالهم، فسبر بمعنى اختبر، وليس بمعنى أهملهم ولا ظلمهم.","ow":["أهملهم يعاكس سبر أحوالهم.","","ظلمهم ليس معنى سبر.","سافر إليهم ليس معنى سبر."]},
  {"q":"معنى <b>مُعوِز</b>:","o":["غني","مفتقر","كريم","قوي"],"a":1,"why":"المعوِز هو المفتقر أي المحتاج الذي ينقصه ما يحتاج إليه، وهو عكس الغني الذي لا يحتاج.","ow":["الغني عكس المعوز.","","الكريم ليس معنى المعوز.","القوي ليس معنى المعوز."]},
  {"q":"عبارة «ما لا يُدرك كلُّه لا يُترك جُلُّه» تُستخدم في مواقف:","o":["محمودة","مذمومة","مضحكة","محزنة فقط"],"a":0,"why":"عبارة ما لا يُدرك كلّه لا يُترك جلّه تُستخدم في مواقف محمودة، حين يحاول الإنسان أن يأخذ بعض ما يريد إن عجز عن كله.","ow":["","المذمومة ليست مواقف استخدام العبارة.","المضحكة ليست مواقف استخدام العبارة.","المحزنة فقط ليست مواقف استخدام العبارة."]},
  {"q":"صاحب العبارة «ما لا يُدرك كلُّه...» يتمنى إدراك:","o":["كل حاجته ثم يحاول بعضها إن عجز","لا شيء","بعض حاجته فقط","ما لا يحتاجه"],"a":0,"why":"صاحب عبارة ما لا يُدرك كلّه يتمنى إدراك كل حاجته، فإن عجز حاول إدراك بعضها ولا يتركها كلها.","ow":["","لا يتمنى لا شيء بل يريد حاجته.","لا يريد بعض حاجته فقط من البداية، بل كلها أولًا.","لا يسعى لما لا يحتاجه."]},
  {"q":"لُقّب جابر بن حيان بـ:","o":["شيخ الكيمياويين العرب","أمير الشعراء","أبي الطب","شاعر الرسول"],"a":0,"why":"لُقّب جابر بن حيان بشيخ الكيمياويين العرب لأنه رائد علم الكيمياء عندهم، وليس هذا لقب أحد الشعراء.","ow":["","أمير الشعراء لقب أحمد شوقي.","أبو الطب ليس لقب جابر.","شاعر الرسول ليس لقب جابر."]},
  {"q":"تتلمذ جابر بن حيان على يد:","o":["ابن سينا","جعفر الصادق","الخوارزمي","الجاحظ"],"a":1,"why":"تتلمذ جابر بن حيان على يد جعفر الصادق، كما ذكر النص، ثم صار شيخ الكيمياويين العرب.","ow":["ابن سينا ليس أستاذ جابر المذكور.","","الخوارزمي ليس أستاذ جابر المذكور.","الجاحظ ليس أستاذ جابر المذكور."]},
  {"q":"منهج جابر بن حيان العلمي يقوم على:","o":["التخمين","الخرافة","العمل والتجربة","الحفظ فقط"],"a":2,"why":"منهج جابر العلمي يقوم على العمل والتجربة، فكان يجرّب بنفسه ولا يعتمد على الكلام فقط.","ow":["التخمين ليس منهجه.","الخرافة هي ما كان في الكيمياء قبله.","","الحفظ فقط ليس منهجه."]},
  {"q":"أوصى جابر تلاميذه بـ:","o":["التسرع","الرفق والتأني وترك العجلة","ترك التجارب","الكتمان فقط"],"a":1,"why":"أوصى جابر تلاميذه بالرفق والتأني وترك العجلة في التجارب، لأن العجلة قد تفسد العمل.","ow":["التسرع يخالف وصية جابر.","","ترك التجارب يخالف منهجه.","الكتمان فقط ليس هو وصيته."]},
  {"q":"رأى جابر أن الأجسام لها:","o":["أصول واحدة والاختلاف في النسب والمقادير","أصول مختلفة تمامًا","لا أصول","أسماء فقط"],"a":0,"why":"رأى جابر أن الأجسام لها أصول واحدة وأن الاختلاف بينها في النسب والمقادير، فصارت الكيمياء علمًا له أصول.","ow":["","أصول مختلفة تمامًا تخالف رأي جابر.","لا أصول لها تخالف رأي جابر.","أسماء فقط ليس رأي جابر."]},
  {"q":"كانت الكيمياء قبل جابر بن حيان تتصف بـ:","o":["الدقة التامة","الغموض والخرافة","التجربة","الأسس العلمية"],"a":1,"why":"كانت الكيمياء قبل جابر تتصف بالغموض والخرافة، ثم جعلها جابر علمًا له أسس وتجارب، فاختلفت صورتها.","ow":["الدقة التامة لم تكن صفتها قبله.","","التجربة جاءت مع جابر.","الأسس العلمية جاءت مع جابر."]},
  {"q":"العبارة: معنى الكلمة يحدده السياق.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمعنى الكلمة يحدده السياق، أي الجملة التي جاءت فيها، مثل عاد بمعنى زار أو رجع.","ow":["","العبارة صحيحة، فنفهم المعنى من الجملة."]},
  {"q":"العبارة: <b>تضافروا</b> تعني تفرقوا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فتضافروا معناها تعاونوا، أما تفرقوا فعكسها تمامًا، فلا تصح العبارة.","ow":["تضافروا لا تعني تفرقوا بل عكسها.",""]},
  {"q":"العبارة: جابر بن حيان تتلمذ على يد جعفر الصادق.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فقد ذكر الدرس أن جابر بن حيان تتلمذ على يد جعفر الصادق، ثم صار شيخ الكيمياويين.","ow":["","العبارة صحيحة، فجعفر الصادق هو أستاذه."]},
  {"q":"العبارة: منهج جابر قائم على التجربة وعدم التسرع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمنهج جابر قائم على التجربة ووصى تلاميذه بالرفق والتأني وترك العجلة.","ow":["","العبارة صحيحة، فالتأني من وصاياه."]},
  {"q":"العبارة: <b>عادَ</b> لها معنى واحد فقط.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فكلمة عاد تتغير معانيها بحسب الجملة: زار، رجع، حارب، اهتدى، وليس لها معنى واحد.","ow":["عاد لها عدة معانٍ بحسب السياق.",""]},
];
window.BANK['a7']['a7-3-1'] = [
  {"q":"الجمع في اللغة العربية قسمان:","o":["سالم وتكسير","مذكر ومؤنث فقط","مفرد ومثنى","اسم وفعل"],"a":0,"why":"الجمع في العربية قسمان: سالم وتكسير. والجمع السالم نوعان هما جمع المذكر السالم وجمع المؤنث السالم.","ow":["","المذكر والمؤنث تقسيم بحسب النوع وليس أقسام الجمع.","مفرد ومثنى تقسيم بحسب العدد وليس أقسام الجمع.","اسم وفعل تقسيم للكلمة وليس أقسام الجمع."]},
  {"q":"يُكوَّن جمع المذكر السالم في حالة الرفع بزيادة:","o":["ألف وتاء","ياء ونون","ألف ونون","واو ونون"],"a":3,"why":"جمع المذكر السالم يُكوَّن في حالة الرفع بزيادة واو ونون على المفرد، مثل: مخلصون ومهندسون ومواطنون.","ow":["ألف وتاء لجمع المؤنث السالم.","ياء ونون في حالتي النصب والجر.","ألف ونون للمثنى في الرفع.",""]},
  {"q":"يُكوَّن جمع المذكر السالم في حالتي النصب والجر بزيادة:","o":["ياء ونون","واو ونون","ألف وتاء","ألف ونون"],"a":0,"why":"جمع المذكر السالم يُكوَّن في حالتي النصب والجر بزيادة ياء ونون، مثل: مخلصين ومهندسين.","ow":["","واو ونون في حالة الرفع.","ألف وتاء لجمع المؤنث السالم.","ألف ونون للمثنى."]},
  {"q":"جمع <b>مواطن</b> جمع مذكر سالم في حالة النصب:","o":["مواطنون","مواطنين","مواطنات","مواطنان"],"a":1,"why":"مواطن + ين = مواطنين في حالة النصب أو الجر، وهي جمع مذكر سالم، وتبقى صورة المفرد سليمة.","ow":["مواطنون جمع مذكر سالم لكن في حالة الرفع.","","مواطنات جمع مؤنث سالم وليس مذكرًا.","مواطنان مثنى يدل على اثنين وليس جمعًا."]},
  {"q":"جمع <b>مهندس</b> جمع مذكر سالم في حالة الرفع:","o":["مهندسين","مهندسات","مهندسون","مهندسان"],"a":2,"why":"مهندس + ون = مهندسون في حالة الرفع، وهي جمع مذكر سالم، وتبقى فيها صورة المفرد كما هي دون تغيير.","ow":["مهندسين جمع مذكر سالم لكن في حالتي النصب والجر.","مهندسات جمع مؤنث سالم وليس مذكرًا.","","مهندسان مثنى يدل على اثنين وليس جمعًا."]},
  {"q":"نون جمع المذكر السالم تكون:","o":["مكسورة دائمًا","مضمومة دائمًا","ساكنة","مفتوحة دائمًا"],"a":3,"why":"نون جمع المذكر السالم مفتوحة دائمًا، أما نون المثنى فمكسورة، وهذا فرق مهم بين الجمع والمثنى.","ow":["ليست مكسورة دائمًا، فالمكسورة نون المثنى.","ليست مضمومة، بل مفتوحة دائمًا في جمع المذكر السالم.","ليست ساكنة، بل مفتوحة دائمًا في جمع المذكر السالم.",""]},
  {"q":"يكون جمع المذكر السالم في الأصل:","o":["لكل اسم","للعَلَم العاقل المذكر أو لصفته","لغير العاقل","للمؤنث"],"a":1,"why":"الأصل في جمع المذكر السالم أن يكون للعَلَم العاقل المذكر أو لصفته، مثل: محمدون ومخلصون.","ow":["ليس لكل اسم، فشروطه تخصه.","","ليس لغير العاقل.","ليس للمؤنث، فللمؤنث جمع المؤنث السالم."]},
  {"q":"أي الكلمات الآتية من ملحقات جمع المذكر السالم؟","o":["أولات","مجالات","سنون","جبال"],"a":2,"why":"سنون من ملحقات جمع المذكر السالم، لأنها تُعرب إعرابه فتُرفع بالواو وتُنصب وتُجر بالياء، مثل: سنون وسنين.","ow":["أولات ملحقة بجمع المؤنث السالم.","مجالات جمع مؤنث سالم أصلي.","","جبال جمع تكسير."]},
  {"q":"من ملحقات جمع المذكر السالم:","o":["أولو","ثروات","فاطمات","مجالات"],"a":0,"why":"أولو بمعنى أصحاب، وهي ملحقة بجمع المذكر السالم، وتُرفع بالواو وتُنصب وتُجر بالياء.","ow":["","ثروات جمع مؤنث سالم.","فاطمات جمع مؤنث سالم أصلي.","مجالات جمع مؤنث سالم أصلي."]},
  {"q":"تُعرب ألفاظ العقود مثل (عشرون، ثلاثون) إعراب:","o":["المثنى","جمع المذكر السالم","جمع المؤنث السالم","جمع التكسير"],"a":1,"why":"ألفاظ العقود مثل عشرون وثلاثون تُعرب إعراب جمع المذكر السالم، فترفع بالواو وتنصب وتجر بالياء.","ow":["المثنى يدل على اثنين.","","جمع المؤنث السالم ينتهي بألف وتاء.","جمع التكسير تتغير فيه صورة المفرد."]},
  {"q":"يُكوَّن جمع المؤنث السالم بإضافة:","o":["واو ونون","ياء ونون","ألف وتاء","ألف ونون"],"a":2,"why":"جمع المؤنث السالم يُكوَّن بإضافة ألف وتاء إلى المفرد، مثل: فاطمة ← فاطمات، ومجال ← مجالات.","ow":["الواو والنون لجمع المذكر السالم في الرفع.","الياء والنون لجمع المذكر السالم في النصب والجر.","","الألف والنون للمثنى."]},
  {"q":"جمع <b>فاطمة</b> جمع مؤنث سالم:","o":["فواطم","فاطمون","فاطمان","فاطمات"],"a":3,"why":"فاطمة + ات = فاطمات، وهي جمع مؤنث سالم، وتُحذف التاء المربوطة قبل زيادة الألف والتاء.","ow":["فواطم جمع تكسير.","فاطمون ليس جمعًا صحيحًا لاسم مؤنث.","فاطمان ليس جمعًا، بل مثنى.",""]},
  {"q":"جمع <b>مجال</b> جمع مؤنث سالم:","o":["مجالات","مجالون","مجالان","أمجال"],"a":0,"why":"مجال + ات = مجالات، جمع مؤنث سالم، وصورة المفرد سليمة، فنقول: مجالات الحياة كثيرة.","ow":["","مجالون ليس جمعًا صحيحًا لمجال.","مجالان مثنى وليس جمعًا.","أمجال ليس جمع مؤنث سالم."]},
  {"q":"من ملحقات جمع المؤنث السالم كلمة:","o":["عالمون","أولات","عشرون","سنون"],"a":1,"why":"أولات بمعنى صاحبات، وهي ملحقة بجمع المؤنث السالم لأنها تُعرب إعرابه. أما عالمون وسنون وعشرون فملحقة بالمذكر.","ow":["عالمون ملحقة بجمع المذكر السالم.","","عشرون ملحقة بجمع المذكر السالم.","سنون ملحقة بجمع المذكر السالم."]},
  {"q":"جمع العَلَم المذكر المختوم بتاء مثل <b>طلحة</b> جمع مؤنث سالم هو:","o":["طلاح","طلحون","طلحات","طلحان"],"a":2,"why":"طلحة مذكر تنتهي بتاء مربوطة، فيُجمع جمع مؤنث سالم بحذف التاء وزيادة ألف وتاء فيصبح طلحات.","ow":["طلاح ليس جمع مؤنث سالم.","طلحون ليس جمعًا صحيحًا لهذا العلم المختوم بتاء.","","طلحان مثنى وليس جمعًا."]},
  {"q":"العبارة: في الجمع السالم تبقى صورة المفرد سليمة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجمع السالم تبقى فيه صورة المفرد سليمة دون تغيير، ولذلك سُمّي سالمًا.","ow":["","العبارة صحيحة، فسلامة المفرد سبب التسمية."]},
  {"q":"العبارة: <b>أولو</b> ملحقة بجمع المؤنث السالم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فأولو ملحقة بجمع المذكر السالم، أما أولات فملحقة بجمع المؤنث السالم.","ow":["أولو ليست ملحقة بالمؤنث بل بالمذكر.",""]},
  {"q":"العبارة: <b>مجالات</b> جمع مؤنث سالم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمجالات هي مجال + ألف وتاء، فهي جمع مؤنث سالم وصورة مفردها سليمة.","ow":["","العبارة صحيحة، فمجالات جمع مؤنث سالم."]},
  {"q":"العبارة: نون جمع المذكر السالم مكسورة دائمًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فنون جمع المذكر السالم مفتوحة دائمًا، أما المكسورة فهي نون المثنى، وهذا فرق بينهما.","ow":["النون في جمع المذكر السالم ليست مكسورة.",""]},
  {"q":"العبارة: <b>عالمون</b> ملحقة بجمع المذكر السالم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فعالمون ملحقة بجمع المذكر السالم لأنها تُعرب إعرابه، فتُرفع بالواو.","ow":["","العبارة صحيحة، فعالمون من ملحقات جمع المذكر."]},
];
window.BANK['a7']['a7-3-2'] = [
  {"q":"جمع التكسير هو ما دلّ على أكثر من اثنين مع:","o":["بقاء صورة المفرد","تغيّر صورة المفرد","زيادة واو ونون","زيادة ألف وتاء"],"a":1,"why":"جمع التكسير هو ما دلّ على أكثر من اثنين مع تغيّر صورة المفرد، أما الجمع السالم فتبقى فيه صورة المفرد.","ow":["بقاء صورة المفرد من صفات الجمع السالم.","","زيادة واو ونون من صفات جمع المذكر السالم.","زيادة ألف وتاء من صفات جمع المؤنث السالم."]},
  {"q":"أي الكلمات الآتية من جموع التكسير؟","o":["ثروات","اتفاقات","أقلام","الجيولوجيون"],"a":2,"why":"أقلام جمع تكسير لأن صورة قلم تغيّرت، أما ثروات واتفاقات فجمع مؤنث سالم، والجيولوجيون جمع مذكر سالم.","ow":["ثروات جمع مؤنث سالم.","اتفاقات جمع مؤنث سالم.","","الجيولوجيون جمع مذكر سالم."]},
  {"q":"جمع <b>قلب</b> جمع تكسير:","o":["قلوب","قلبات","قلبون","قلبان"],"a":0,"why":"قلب تصبح قلوب في جمع التكسير بتغيير صورة المفرد وزيادة حرف عليه، وهو ليس جمعًا سالمًا.","ow":["","قلبات ليست الجمع المعروف لقلب.","قلبون ليست جمعًا صحيحًا لقلب.","قلبان مثنى وليس جمعًا."]},
  {"q":"جمع <b>جسر</b> جمع تكسير:","o":["جسرات","جسرون","جسور","جسران"],"a":2,"why":"جسر تصبح جسور في جمع التكسير بزيادة حرف على المفرد فتتغير صورته، فهو جمع تكسير وليس جمعًا سالمًا.","ow":["جسرات ليست الجمع المعروف لجسر.","جسرون ليست جمعًا صحيحًا لجسر.","","جسران مثنى وليس جمعًا."]},
  {"q":"جمع <b>مركز</b> جمع تكسير:","o":["مراكز","مركزات","مركزون","مركزان"],"a":0,"why":"مركز تصبح مراكز في جمع التكسير بزيادة ألف في وسطه فتتغير صورة المفرد، فهو جمع تكسير وليس جمعًا سالمًا.","ow":["","مركزات ليست الجمع المعروف.","مركزون ليست جمعًا صحيحًا.","مركزان مثنى وليس جمعًا."]},
  {"q":"جمع <b>نفق</b> جمع تكسير:","o":["نفقات","أنفاق","نفقون","نفقان"],"a":1,"why":"نفق تصبح أنفاق في جمع التكسير بزيادة حروف على المفرد فتتغير صورته، فهو جمع تكسير وليس جمعًا سالمًا.","ow":["نفقات جمع مؤنث سالم قد يُستعمل لكن المطلوب جمع التكسير.","","نفقون ليست جمعًا صحيحًا لنفق.","نفقان مثنى وليس جمعًا."]},
  {"q":"جمع <b>قرية</b> جمع تكسير:","o":["قريات","قريتان","قرى","قريون"],"a":2,"why":"قرية تصبح قرى في جمع التكسير بنقصان حرف من المفرد وتغيّر صورته، فنقول: قرية ← قرى.","ow":["قريات جمع مؤنث سالم وليس تكسيرًا.","قريتان مثنى وليس جمعًا.","","قريون ليست جمعًا صحيحًا لقرية."]},
  {"q":"جمع <b>رسول</b> جمع تكسير فيه تغيير بـ:","o":["زيادة","نقص","تغيير ضبط فقط","لا تغيير"],"a":1,"why":"رسول تصبح رسل بنقصان حرف من المفرد، وهذا أحد وجوه التكسير مع الزيادة وتغيير الضبط.","ow":["الزيادة تكون في مثل سهم ← سهام.","","تغيير الضبط فقط يكون في مثل أَسَد ← أُسْد.","التغيير موجود، لأن الجمع تكسير."]},
  {"q":"جمع <b>كتاب</b> جمع تكسير:","o":["كتابات","كتب","كتابون","كتابان"],"a":1,"why":"كتاب تصبح كُتُب بنقصان حرف الألف، وهذا من جمع التكسير الذي تتغير فيه صورة المفرد.","ow":["كتابات جمع مؤنث سالم.","","كتابون ليست جمعًا صحيحًا لكتاب.","كتابان مثنى وليس جمعًا."]},
  {"q":"جمع <b>أَسَد</b> هو <b>أُسْد</b> وفيه:","o":["زيادة حرف","نقص حرف","تغيير ضبط بعض الحروف","لا تغيير"],"a":2,"why":"أَسَد تصبح أُسْد، ولم يُزَد ولم يُنقص حرف، وإنما تغيّر ضبط الحروف فقط، وهذه طريقة ثالثة من التكسير.","ow":["لم يُزَد حرف في أُسْد.","لم يُنقص حرف في أُسْد.","","يوجد تغيير في الضبط."]},
  {"q":"كلمة <b>الثروات</b> جمع:","o":["تكسير","مذكر سالم","مثنى","مؤنث سالم"],"a":3,"why":"الثروات جمع مؤنث سالم لأن مفردها ثروة وبقيت صورتها كما هي مع زيادة الألف والتاء.","ow":["التكسير تتغير فيه صورة المفرد، وهنا لم تتغير.","المذكر السالم ينتهي بواو ونون.","المثنى يدل على اثنين وينتهي بألف ونون.",""]},
  {"q":"كلمة <b>اتفاقات</b> جمع:","o":["مؤنث سالم","مذكر سالم","تكسير","مثنى"],"a":0,"why":"اتفاقات هي اتفاق + ألف وتاء، وصورة المفرد سليمة لم تتغير، فهي جمع مؤنث سالم وليست تكسيرًا.","ow":["","جمع المذكر السالم ينتهي بواو ونون.","التكسير تتغير فيه صورة المفرد، وهنا لم تتغير.","المثنى ينتهي بألف ونون."]},
  {"q":"كلمة <b>الجيولوجيون</b> جمع:","o":["مؤنث سالم","مذكر سالم","تكسير","مثنى"],"a":1,"why":"الجيولوجيون هي جيولوجي + ون، وصورة المفرد سليمة لم تتغير، فهي جمع مذكر سالم وليست تكسيرًا.","ow":["المؤنث السالم ينتهي بألف وتاء.","","التكسير تتغير فيه صورة المفرد.","المثنى يدل على اثنين."]},
  {"q":"كلمة <b>بلاد</b> جمع تكسير مفردها:","o":["بلدة","بلدان","بلد","أبلاد"],"a":2,"why":"بلاد جمع تكسير مفرده بلد، وقد تغيرت صورة المفرد بزيادة ألف، فنقول: بلد ← بلاد، وهي طريقة من طرق التكسير.","ow":["بلدة مفرد آخر، وجمعها بلدات أو بلاد.","بلدان مثنى كما في بلدان، وليس مفرد بلاد.","","أبلاد ليس مفرد بلاد."]},
  {"q":"كلمة <b>آمال</b> جمع تكسير مفردها:","o":["أمل","آمل","مأمول","أمّة"],"a":0,"why":"آمال جمع تكسير مفرده أمل، وقد تغيرت صورة المفرد بزيادة ألف، فنقول: أمل ← آمال، وهي طريقة من طرق التكسير.","ow":["","آمل اسم فاعل وليس مفرد آمال.","مأمول اسم مفعول وليس مفرد آمال.","أمّة اسم آخر وليس مفرد آمال."]},
  {"q":"العبارة: جمع التكسير تتغير فيه صورة المفرد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع التكسير تتغير فيه صورة المفرد، وهذا ما يميزه عن الجمع السالم.","ow":["","العبارة صحيحة، فتغيّر الصورة صفة التكسير."]},
  {"q":"العبارة: <b>ثروات</b> جمع تكسير.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فثروات جمع مؤنث سالم لأن صورة ثروة لم تتغير، بل زيدت عليها الألف والتاء.","ow":["ثروات لم تتغير صورة مفردها، فهي ليست تكسيرًا.",""]},
  {"q":"العبارة: <b>الصخور</b> جمع تكسير.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالصخور جمع صخرة، وقد تغيرت صورة المفرد عند الجمع، فهي جمع تكسير.","ow":["","العبارة صحيحة، فصورة صخرة تغيرت."]},
  {"q":"العبارة: نميّز نوع الجمع بمقارنته بمفرده.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فنميّز نوع الجمع بأن نرجع إلى المفرد ونقارن بينه وبين الجمع، فإن تغيرت صورته فهو تكسير.","ow":["","العبارة صحيحة، فالمقارنة بالمفرد هي الطريقة."]},
  {"q":"العبارة: <b>سهام</b> جمع تكسير مفرده سهم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فسهام جمع تكسير مفرده سهم، وقد زيدت ألف على المفرد فتغيرت صورته، وهذا هو التكسير.","ow":["","العبارة صحيحة، فسهام جمع سهم."]},
];
window.BANK['a7']['a7-3-3'] = [
  {"q":"النداء هو توجيه الدعوة إلى المخاطب وتنبيهه من أجل:","o":["الإصغاء وسماع ما يريده المتكلم","الجواب بنعم","النفي","السؤال عن الحال"],"a":0,"why":"النداء هو توجيه الدعوة إلى المخاطب وتنبيهه من أجل الإصغاء وسماع ما يريده المتكلم.","ow":["","الجواب بنعم يكون في الاستفهام وليس النداء.","النفي أسلوب آخر وليس هدف النداء.","السؤال عن الحال هو الاستفهام وليس النداء."]},
  {"q":"عدد حروف النداء المذكورة في الدرس:","o":["اثنان","ثلاثة","ستة","أربعة"],"a":3,"why":"حروف النداء أربعة هي: يا وأي وأيا وهيا، وأشهرها يا، فنقول: يا زملائي، ويا أيها الناس.","ow":["عدد حروف النداء ليس اثنين.","عدد حروف النداء ليس ثلاثة.","عدد حروف النداء ليس ستة.",""]},
  {"q":"من حروف النداء:","o":["هل","أيا","لم","في"],"a":1,"why":"أيا من حروف النداء الأربعة: يا وأي وأيا وهيا. أما هل فللاستفهام ولم للنفي وفي حرف جر.","ow":["هل حرف استفهام وليس نداء.","","لم حرف نفي وجزم وليس نداء.","في حرف جر وليس نداء."]},
  {"q":"أي الآتي حرف نداء؟","o":["كيف","أين","أيْ","لماذا"],"a":2,"why":"أي من حروف النداء الأربعة: يا وأي وأيا وهيا. أما كيف وأين ولماذا فكلها أدوات استفهام وليست حروف نداء.","ow":["كيف أداة استفهام عن الحال.","أين أداة استفهام عن المكان.","","لماذا أداة استفهام عن العلة."]},
  {"q":"أي الجمل الآتية بدأت بحرف نداء؟","o":["يا زملائي، أحبوا وطنكم","هل ذهبت إلى المدرسة؟","لم يحضر محمد","كم عمرك؟"],"a":0,"why":"يا زملائي، أحبوا وطنكم جملة نداء لأنها بدأت بحرف النداء يا، والمنادى زملائي، ثم المطلوب منهم.","ow":["","هل ذهبت إلى المدرسة؟ جملة استفهام.","لم يحضر محمد جملة منفية.","كم عمرك؟ جملة استفهام عن العدد."]},
  {"q":"أي الجمل الآتية فيها المنادى (أبناءَ وطني)؟","o":["أين المكتبة؟","أيا أبناءَ وطني، نحن إخوة","ما أجمل السماء","كتب الطالب"],"a":1,"why":"أيا أبناءَ وطني، نحن إخوة جملة نداء لأنها بدأت بحرف النداء أيا، والمنادى أبناء وطني.","ow":["أين المكتبة؟ جملة استفهام وليست نداء.","","ما أجمل السماء جملة تعجب وليست نداء.","كتب الطالب جملة فعلية وليست نداء."]},
  {"q":"عند نداء المذكر الذي فيه (ال) نأتي بكلمة:","o":["أيتها","هيا","أيُّها","أيْ"],"a":2,"why":"عند نداء المذكر الذي فيه ال نأتي بكلمة أيُّها بعد حرف النداء، فنقول: يا أيها الطالب.","ow":["أيتها للمؤنث، وليست للمذكر.","هيا حرف نداء وليست كلمة تأتي بعد حرف النداء.","","أي حرف نداء، ولا تُستخدم هنا بدل أيها."]},
  {"q":"عند نداء المؤنث الذي فيه (ال) نأتي بكلمة:","o":["أيتها","أيها","يا فقط","هل"],"a":0,"why":"عند نداء المؤنث الذي فيه ال نأتي بكلمة أيتها بعد حرف النداء، فنقول: يا أيتها الطالبة.","ow":["","أيها للمذكر وليست للمؤنث.","يا فقط لا تدخل على ما فيه ال التعريف مباشرة.","هل أداة استفهام وليست من النداء."]},
  {"q":"الجملة الصحيحة في نداء المؤنث المعرّف بـ (ال):","o":["يا الطالبة","يا أيتها الطالبة","يا أيها الطالبة","أيتها يا الطالبة"],"a":1,"why":"الجملة الصحيحة في نداء المؤنث المعرّف بـ ال هي: يا أيتها الطالبة، لأن أيتها للمؤنث.","ow":["يا الطالبة خطأ لأن حرف النداء لا يدخل على ما فيه ال مباشرة.","","يا أيها الطالبة خطأ لأن أيها للمذكر وليست للمؤنث.","أيتها يا الطالبة ترتيب خاطئ، فحرف النداء يأتي أولًا."]},
  {"q":"قد يُحذف حرف النداء مع:","o":["العَلَم","الفعل","الحرف","الجملة الفعلية"],"a":0,"why":"قد يُحذف حرف النداء مع العَلَم، مثل: يوسفُ أعرضْ عن هذا، والأصل يا يوسف، ولا يُحذف مع الفعل أو الحرف.","ow":["","لا يُحذف حرف النداء مع الفعل.","لا يُحذف حرف النداء مع الحرف.","الجملة الفعلية ليست ما يُحذف معه حرف النداء."]},
  {"q":"الأصل في ﴿يوسفُ أَعْرِضْ عن هذا﴾:","o":["هل يوسفُ","يا يوسفُ","لم يوسفُ","في يوسفُ"],"a":1,"why":"الأصل في يوسفُ أعرضْ عن هذا هو يا يوسفُ، فحُذف حرف النداء يا لأن المنادى علم، وهذا جائز.","ow":["هل يوسف ليس الأصل لأن هل للاستفهام.","","لم يوسف ليس الأصل لأن لم للنفي.","في يوسف ليس الأصل لأن في حرف جر."]},
  {"q":"في جملة: <b>يا معلمُ، ساعدني</b> المنادى هو:","o":["يا","ساعدني","معلمُ","لا يوجد"],"a":2,"why":"المنادى هو الاسم الذي نناديه بعد حرف النداء، وفي يا معلمُ ساعدني المنادى هو معلمُ.","ow":["يا حرف النداء وليست المنادى.","ساعدني فعل أمر وهو المطلوب من المنادى.","","في الجملة منادى هو معلمُ."]},
  {"q":"في جملة: <b>يا زملائي، إن حبَّ الوطن لا يكمن في الهتاف له</b> يحمل النداء معنى:","o":["النصح والإرشاد","الاستهزاء","السؤال","النفي"],"a":0,"why":"في يا زملائي، إن حب الوطن لا يكمن في الهتاف له النداء يحمل النصح والإرشاد، حيث ينبّه المتكلم زملاءه بلطف.","ow":["","الاستهزاء ليس هو المعنى في هذه الجملة.","السؤال ليس هو المعنى في هذه الجملة.","النفي ليس هو معنى النداء هنا."]},
  {"q":"أي الكلمات الآتية ليست من حروف النداء؟","o":["يا","هيا","أيا","هل"],"a":3,"why":"هل ليست من حروف النداء، فهي حرف استفهام. أما يا وهيا وأيا فحروف نداء من الحروف الأربعة.","ow":["يا حرف نداء وهو أشهر حروف النداء.","هيا حرف نداء من الحروف الأربعة.","أيا حرف نداء من الحروف الأربعة.",""]},
  {"q":"عناصر جملة النداء هي:","o":["حرف النداء + المنادى + المطلوب","فعل + فاعل","مبتدأ + خبر","اسم + حرف جر"],"a":0,"why":"جملة النداء تتكون من حرف النداء والمنادى والمطلوب، مثل: يا معلمُ ساعدني، وليس من فعل وفاعل.","ow":["","فعل وفاعل هما ركنا الجملة الفعلية وليسا عناصر جملة النداء.","مبتدأ وخبر ركنا الجملة الاسمية وليسا عناصر النداء.","اسم وحرف جر ليسا عناصر جملة النداء."]},
  {"q":"العبارة: <b>هيا</b> من حروف النداء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فهيا من حروف النداء الأربعة: يا وأي وأيا وهيا، فنقول: هيا يا أصدقائي.","ow":["","العبارة صحيحة، فهيا حرف نداء."]},
  {"q":"العبارة: نقول: يا الطالبُ.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فلا نقول يا الطالب، بل نقول: يا أيها الطالب، لأن حرف النداء لا يدخل على ما فيه ال.","ow":["يا الطالب خطأ، فالصحيح يا أيها الطالب.",""]},
  {"q":"العبارة: <b>أيتها</b> تُستخدم مع المؤنث.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأيتها تُستخدم في نداء المؤنث الذي فيه ال، فنقول: يا أيتها الطالبة.","ow":["","العبارة صحيحة، فأيتها للمؤنث وأيها للمذكر."]},
  {"q":"العبارة: لا يجوز حذف حرف النداء مطلقًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فحرف النداء قد يُحذف، مثل يوسفُ أعرضْ عن هذا، والأصل يا يوسف، فيجوز حذفه مع العلم.","ow":["يجوز حذف حرف النداء مع العلم، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: النداء فيه تنبيه للمخاطب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالنداء فيه تنبيه للمخاطب ليصغي إلى المتكلم ويسمع ما يريده منه، مثل: يا زملائي.","ow":["","العبارة صحيحة، فالتنبيه من معاني النداء."]},
];
window.BANK['a7']['a7-3-4'] = [
  {"q":"عدد الحروف الناسخة المذكورة في الدرس:","o":["أربعة","ثلاثة","ستة","خمسة"],"a":2,"why":"الحروف الناسخة ستة هي: إنّ وأنّ ولكنّ وكأنّ وليت ولعلّ، وكلها تدخل على الجملة الاسمية فتنصب المبتدأ.","ow":["الحروف الناسخة أكثر من أربعة.","الحروف الناسخة أكثر من ثلاثة.","","الحروف الناسخة ستة وليست خمسة."]},
  {"q":"تدخل الحروف الناسخة على الجملة:","o":["الفعلية","الاسمية","النداء","الأمر"],"a":1,"why":"تدخل الحروف الناسخة على الجملة الاسمية المكونة من مبتدأ وخبر وتغير إعرابها، ولا تدخل على الجملة الفعلية.","ow":["الجملة الفعلية لا تدخل عليها الحروف الناسخة.","","النداء أسلوب لا تدخل عليه الحروف الناسخة.","الأمر أسلوب لا تدخل عليه الحروف الناسخة."]},
  {"q":"عمل الحروف الناسخة:","o":["ترفع الاسم وتنصب الخبر","تنصب الاسم وترفع الخبر","تجزم الاسم","تجر الخبر"],"a":1,"why":"الحروف الناسخة تنصب الاسم وترفع الخبر، فاسمها منصوب وخبرها مرفوع، وهذا عكس كان وأخواتها.","ow":["هذا عمل كان وأخواتها وليس الحروف الناسخة.","","الحروف الناسخة لا تجزم الاسم.","الحروف الناسخة لا تجر الخبر."]},
  {"q":"عمل كان وأخواتها:","o":["ترفع الاسم وتنصب الخبر","تنصب الاسم وترفع الخبر","تجر الاسم","تجزم الخبر"],"a":0,"why":"كان وأخواتها ترفع الاسم وتنصب الخبر، فاسمها مرفوع وخبرها منصوب، وهذا عكس الحروف الناسخة.","ow":["","هذا عمل الحروف الناسخة وليس كان.","كان لا تجر الاسم.","كان لا تجزم الخبر."]},
  {"q":"الحرف الناسخ الذي يفيد التشبيه:","o":["إنّ","لعلّ","كأنّ","ليت"],"a":2,"why":"كأنّ حرف ناسخ يفيد التشبيه، مثل: كأنّ الجبيل قلعة صناعية، فنشبّه الجبيل بالقلعة، وليست للتمني ولا للترجي.","ow":["إنّ تفيد التوكيد.","لعلّ تفيد الترجي.","","ليت تفيد التمني."]},
  {"q":"الحرف الناسخ الذي يفيد التمني:","o":["ليت","إنّ","لكنّ","كأنّ"],"a":0,"why":"ليت حرف ناسخ يفيد التمني، أي تمنّي شيء بعيد الحصول، مثل: ليت الشباب يعود، وليست للتوكيد ولا للتشبيه.","ow":["","إنّ تفيد التوكيد.","لكنّ تفيد الاستدراك.","كأنّ تفيد التشبيه."]},
  {"q":"الحرف الناسخ الذي يفيد الترجي:","o":["ليت","لكنّ","كأنّ","لعلّ"],"a":3,"why":"لعلّ حرف ناسخ يفيد الترجي، أي توقع أمر محبوب يمكن حصوله، أما ليت فتفيد التمني، أي تمنّي ما يبعد حصوله.","ow":["ليت تفيد التمني وليس الترجي.","لكنّ تفيد الاستدراك.","كأنّ تفيد التشبيه.",""]},
  {"q":"الحرف الناسخ الذي يفيد الاستدراك:","o":["إنّ","لكنّ","أنّ","لعلّ"],"a":1,"why":"لكنّ حرف ناسخ يفيد الاستدراك، أي تصحيح ما قد يُفهم من الكلام السابق، أما إنّ وأنّ فللتوكيد.","ow":["إنّ تفيد التوكيد.","","أنّ تفيد التوكيد.","لعلّ تفيد الترجي."]},
  {"q":"الحرف الناسخ الذي يفيد التوكيد:","o":["ليت","لعلّ","إنّ","كأنّ"],"a":2,"why":"إنّ حرف ناسخ يفيد التوكيد، فيؤكد معنى الجملة ويقوّيه، وكذلك أنّ، أما ليت فللتمني ولعلّ للترجي.","ow":["ليت تفيد التمني.","لعلّ تفيد الترجي.","","كأنّ تفيد التشبيه."]},
  {"q":"علامة نصب اسم إنّ إذا كان مفردًا:","o":["الضمة","الفتحة","الياء","الألف"],"a":1,"why":"اسم إنّ المفرد يُنصب بالفتحة، مثل: إنّ حقلَ الدمام واحدٌ، فالفتحة هي علامة نصب حقل.","ow":["الضمة علامة رفع المفرد.","","الياء علامة نصب المثنى وجمع المذكر السالم.","الألف علامة رفع المثنى."]},
  {"q":"علامة نصب اسم إنّ إذا كان جمع مؤنث سالمًا:","o":["الكسرة","الفتحة","الياء","الألف"],"a":0,"why":"جمع المؤنث السالم يُنصب بالكسرة نيابة عن الفتحة، فنقول: إنّ المواطناتِ مخلصاتٌ، فعلامة النصب الكسرة.","ow":["","الفتحة علامة نصب المفرد.","الياء علامة نصب المثنى وجمع المذكر السالم.","الألف علامة رفع المثنى."]},
  {"q":"علامة نصب اسم إنّ إذا كان مثنى:","o":["الفتحة","الكسرة","الألف","الياء"],"a":3,"why":"المثنى يُنصب بالياء، فنقول: إنّ الطالبين مجتهدان، وعلامة نصب اسم إنّ الياء لأنه مثنى.","ow":["الفتحة علامة نصب المفرد.","الكسرة علامة نصب جمع المؤنث السالم.","الألف علامة رفع المثنى.",""]},
  {"q":"علامة رفع خبر إنّ إذا كان مثنى:","o":["الألف","الواو","الضمة","الياء"],"a":0,"why":"خبر إنّ مرفوع، فإذا كان مثنى رُفع بالألف، مثل: إنّ الطالبين مجتهدان، فعلامة رفع الخبر الألف.","ow":["","الواو علامة رفع جمع المذكر السالم.","الضمة علامة رفع المفرد.","الياء علامة نصب وجر."]},
  {"q":"علامة رفع خبر إنّ إذا كان جمع تكسير:","o":["الألف","الواو","الضمة","الياء"],"a":2,"why":"خبر إنّ يُرفع، وإذا كان جمع تكسير رُفع بالضمة، مثل: إنّ الأعمال موجبات للأجر، فالضمة علامة رفعه.","ow":["الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","","الياء علامة نصب وجر."]},
  {"q":"في جملة: <b>كأنَّ الجبيلَ قلعةٌ صناعيةٌ</b> اسم كأنّ:","o":["قلعةٌ","الجبيلَ","صناعيةٌ","كأنّ"],"a":1,"why":"في كأنَّ الجبيلَ قلعةٌ صناعية الجبيل هو اسم كأنّ، لأنه المبتدأ الأصلي الذي نُصب، أما قلعة فخبرها المرفوع.","ow":["قلعةٌ هي خبر كأنّ المرفوع.","","صناعيةٌ صفة للقلعة وليست اسم كأنّ.","كأنّ حرف ناسخ وليس اسمه."]},
  {"q":"العبارة: الحروف الناسخة تنصب الاسم وترفع الخبر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالحروف الناسخة تنصب الاسم ويسمى اسمها، وترفع الخبر ويسمى خبرها، وهذا عكس كان.","ow":["","العبارة صحيحة، وهي عكس كان وأخواتها."]},
  {"q":"العبارة: <b>ليت</b> تفيد الترجي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فليت تفيد التمني، أما الترجي فتفيده لعلّ، فلا نخلط بين معنى الحرفين.","ow":["ليت للتمني وليست للترجي.",""]},
  {"q":"العبارة: <b>كأنّ</b> حرف ناسخ يفيد التشبيه.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فكأنّ حرف ناسخ يفيد التشبيه، مثل: كأنّ الجبيل قلعة صناعية، فنشبه الجبيل بالقلعة.","ow":["","العبارة صحيحة، فكأنّ للتشبيه."]},
  {"q":"العبارة: <b>إنّ</b> وأنّ تفيدان التوكيد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فإنّ وأنّ تفيدان التوكيد، أي تقويان معنى الجملة وتثبتانه في ذهن السامع.","ow":["","العبارة صحيحة، فالتوكيد معنى إنّ وأنّ."]},
  {"q":"العبارة: اسم إنّ يكون مرفوعًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فاسم إنّ منصوب وليس مرفوعًا، لأن الحروف الناسخة تنصب المبتدأ وترفع الخبر.","ow":["اسم إنّ ليس مرفوعًا بل منصوبًا.",""]},
];
window.BANK['a7']['a7-3-5'] = [
  {"q":"عند الوقف على التاء المفتوحة بالسكون تنطق:","o":["هاءً","تاءً","ألفًا","نونًا"],"a":1,"why":"عند الوقف على التاء المفتوحة بالسكون تُنطق تاءً، مثل: قامتْ، أما المربوطة فتُنطق هاءً.","ow":["الهاء تكون للتاء المربوطة في الوقف.","","الألف ليست نطق التاء المفتوحة.","النون ليست نطق التاء المفتوحة."]},
  {"q":"تُكتب التاء المفتوحة على صورة:","o":["ة","هـ","ت","ط"],"a":2,"why":"التاء المفتوحة تُكتب على صورة ت، مثل: قامتْ وبيتٌ، وتُنطق تاءً في الوصل والوقف، أما المربوطة فتُكتب ة.","ow":["ة صورة التاء المربوطة.","هـ ليست صورة التاء.","","ط حرف آخر ليس صورة التاء."]},
  {"q":"تُكتب التاء المربوطة على صورة:","o":["ة","ت","هـ","ط"],"a":0,"why":"التاء المربوطة تُكتب على صورة ة، مثل: دولة ومدينة، وتُنطق هاءً عند الوقف، أما المفتوحة فتُكتب ت.","ow":["","ت صورة التاء المفتوحة.","هـ ليست صورة التاء المربوطة.","ط حرف آخر ليس صورة التاء المربوطة."]},
  {"q":"في كلمة <b>دولة</b> نوع التاء:","o":["مفتوحة","مربوطة","أصلية","ضمير"],"a":1,"why":"في دولة التاء مربوطة لأننا نقف عليها فننطقها هاءً فنقول: دولهْ، والتاء المربوطة تأتي في آخر الأسماء.","ow":["التاء المفتوحة تُنطق تاءً عند الوقف.","","التاء ليست أصلية في دولة، بل هي مربوطة.","التاء ليست ضميرًا هنا."]},
  {"q":"في كلمة <b>بيتٌ</b> نوع التاء:","o":["مربوطة","مفتوحة","همزة","ألف"],"a":1,"why":"بيتٌ اسم ثلاثي ساكن الوسط، فتاؤه مفتوحة، ونقول عند الوقف بيتْ بالتاء، أما المربوطة فتُنطق هاءً عند الوقف.","ow":["التاء المربوطة تُنطق هاءً عند الوقف وبيت لا تُنطق كذلك.","","التاء في بيت ليست همزة.","التاء في بيت ليست ألفًا."]},
  {"q":"أي الكلمات الآتية تُكتب بتاء مربوطة؟","o":["قلعة","بيت","الإمكانات","ثبات"],"a":0,"why":"قلعة اسم مفرد مؤنث فتُكتب بتاء مربوطة. أما بيت والإمكانات وثبات فتاؤها مفتوحة لأنها تُنطق تاءً عند الوقف.","ow":["","بيت اسم ثلاثي ساكن الوسط تاؤه مفتوحة.","الإمكانات جمع مؤنث سالم تاؤه مفتوحة.","ثبات تاؤه أصلية مفتوحة."]},
  {"q":"أي الكلمات الآتية تُكتب بتاء مفتوحة؟","o":["مدينة","دولة","الطاقات","قلعة"],"a":2,"why":"الطاقات جمع مؤنث سالم، وتاؤه مفتوحة. أما مدينة ودولة وقلعة فتاؤها مربوطة لأنها أسماء مفردة مؤنثة.","ow":["مدينة اسم مفرد مؤنث تاؤه مربوطة.","دولة اسم مفرد مؤنث تاؤه مربوطة.","","قلعة اسم مفرد مؤنث تاؤه مربوطة."]},
  {"q":"التاء في كلمة <b>ثباتٌ</b>:","o":["مربوطة","مفتوحة أصلية","ضمير","همزة"],"a":1,"why":"ثباتٌ اسم تاؤه أصلية في آخره، وتُنطق تاءً عند الوقف، فهي تاء مفتوحة وليست مربوطة.","ow":["المربوطة تُنطق هاءً في الوقف.","","التاء ليست ضميرًا في ثبات.","التاء ليست همزة."]},
  {"q":"لا تأتي التاء المربوطة إلا في أواخر:","o":["الأفعال","الحروف","الأسماء فقط","الأفعال والأسماء"],"a":2,"why":"التاء المربوطة لا تأتي إلا في أواخر الأسماء، مثل: دولة ومدينة، ولا تأتي في الأفعال ولا الحروف.","ow":["لا تأتي التاء المربوطة في آخر الأفعال.","لا تأتي في الحروف.","","لا تأتي في الأفعال."]},
  {"q":"التاء في جمع المؤنث السالم مثل <b>الإمكانات</b>:","o":["مربوطة","مفتوحة","همزة","ألف"],"a":1,"why":"تاء جمع المؤنث السالم مفتوحة، مثل الإمكانات والطاقات، لأننا ننطقها تاءً عند الوقف، فلا تكون مربوطة.","ow":["المربوطة تكون في المفرد مثل مدينة.","","التاء ليست همزة.","التاء ليست ألفًا."]},
  {"q":"التاء في آخر الفعل الماضي <b>قامَتْ</b>:","o":["مربوطة","همزة","مفتوحة (تاء التأنيث الساكنة)","هاء"],"a":2,"why":"التاء في قامَتْ تاء التأنيث الساكنة في آخر الفعل الماضي، وهي مفتوحة وليست مربوطة، فنقول: قامتْ بالتاء.","ow":["المربوطة لا تأتي في الأفعال.","الهمزة ليست التاء.","","التاء المفتوحة تُنطق تاءً عند الوقف وليست هاءً."]},
  {"q":"التاء في <b>كتبتُ</b> هي:","o":["تاء الضمير المفتوحة","تاء مربوطة","تاء التأنيث","همزة"],"a":0,"why":"التاء في كتبتُ هي تاء الضمير وهي مفتوحة، وتدل على الفاعل المتكلم، فلا تكون مربوطة ولا همزة.","ow":["","التاء المربوطة لا تأتي في الأفعال.","تاء التأنيث تكون في مثل كتبتْ وليس كتبتُ.","التاء ليست همزة."]},
  {"q":"عند مخاطبة المرأة نقول:","o":["كتبتي","كتبتِ","كتبتُ","كتبتَ"],"a":1,"why":"عند مخاطبة المرأة نقول كتبتِ بكسر التاء، ولا نقول كتبتي بإضافة ياء، فالكسرة تكفي علامة للمخاطبة.","ow":["كتبتي خطأ في الكتابة لأننا نضيف ياء.","","كتبتُ بالضمة للمتكلم.","كتبتَ بالفتحة للمخاطب المذكر."]},
  {"q":"كلمة <b>ثَمَّةَ</b> (بفتح الثاء) بمعنى (هناك) تاؤها:","o":["مربوطة","مفتوحة","همزة","ألف"],"a":0,"why":"ثَمَّةَ ظرف بمعنى هناك، وتاؤها مربوطة، لأنها كلمة اسمية ننطقها هاءً عند الوقف، بخلاف ثُمَّتْ الحرف.","ow":["","التاء المفتوحة تكون في ثُمَّتْ الحرف.","التاء ليست همزة.","التاء ليست ألفًا."]},
  {"q":"كلمة <b>ثُمَّتْ</b> (بضم الثاء) حرف عطف تاؤها:","o":["مربوطة","مفتوحة","همزة","ألف"],"a":1,"why":"ثُمَّتْ بضم الثاء حرف عطف، وتاؤها مفتوحة، فننطقها تاءً عند الوقف، بخلاف ثَمَّةَ الظرف.","ow":["المربوطة في ثَمَّةَ الظرف.","","التاء ليست همزة.","التاء ليست ألفًا."]},
  {"q":"العبارة: التاء المربوطة تنطق هاءً عند الوقف بالسكون.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالتاء المربوطة تُنطق هاءً عند الوقف بالسكون، مثل: دولة تصبح دولهْ.","ow":["","العبارة صحيحة، فالهاء هي نطقها في الوقف."]},
  {"q":"العبارة: التاء المربوطة تأتي في آخر الأفعال.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالتاء المربوطة تأتي في أواخر الأسماء فقط، ولا تأتي في آخر الأفعال أبدًا.","ow":["الأفعال لا تكون فيها تاء مربوطة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: جمع المؤنث السالم يُكتب بتاء مفتوحة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع المؤنث السالم يُكتب بتاء مفتوحة، مثل: الطاقات والإمكانات، لأنها تُنطق تاءً عند الوقف.","ow":["","العبارة صحيحة، فتاء جمع المؤنث السالم مفتوحة."]},
  {"q":"العبارة: الصواب أن نقول للمخاطبة: كتبتي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالصواب أن نقول للمخاطبة: كتبتِ بكسر التاء، وليس كتبتي بإضافة ياء بعد التاء.","ow":["كتبتي خطأ إملائي.",""]},
  {"q":"العبارة: <b>أوقات</b> جمع تكسير مفرده مختوم بتاء مفتوحة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأوقات جمع مفرده وقت، وهو ينتهي بتاء مفتوحة، فيكون أصل تاء الجمع هو تاء المفرد.","ow":["","العبارة صحيحة، فمفرد أوقات وقت وليس مختومًا بتاء مربوطة."]},
];
window.BANK['a7']['a7-3-6'] = [
  {"q":"الراء والزاي في خط الرقعة يُكتبان:","o":["بالطريقة نفسها","بطريقتين مختلفتين تمامًا","مثل الباء","مثل الدال"],"a":0,"why":"الراء والزاي في خط الرقعة يُكتبان بالطريقة نفسها، والفرق الوحيد نقطة أعلى الزاي.","ow":["","لا يُكتبان بطريقتين مختلفتين تمامًا.","الراء والزاي ليستا مثل الباء في الرسم.","الراء والزاي ليستا مثل الدال في الرسم."]},
  {"q":"الفرق بين الراء والزاي هو:","o":["النقطة أعلى الزاي","نقطتان أسفل الراء","النقطة أسفل الزاي","لا فرق"],"a":0,"why":"الفرق بين الراء والزاي هو النقطة، فالزاي عليها نقطة أعلاها والراء بلا نقطة، وهذا هو الفرق الوحيد بينهما.","ow":["","نقطتان أسفل الراء ليستا هما الفرق.","نقطة الزاي أعلى الحرف وليست أسفله.","يوجد فرق وهو النقطة."]},
  {"q":"الراء والزاي منفردين في الرقعة يكتبان بخط:","o":["مائل نحو اليسار","مائل نحو اليمين","أفقي","رأسي مستقيم"],"a":0,"why":"الراء والزاي منفردين في خط الرقعة يُكتبان بخط مائل نحو اليسار، وليس نحو اليمين ولا بشكل أفقي.","ow":["","الميل نحو اليمين ليس ميل هذين الحرفين.","الخط الأفقي ليس طريقة كتابتهما.","الخط الرأسي المستقيم هو شكل الألف وليس الراء."]},
  {"q":"نقطة الزاي في خط الرقعة تكون:","o":["أسفل الحرف","أعلى الحرف","داخل الحرف","بلا نقطة"],"a":1,"why":"نقطة الزاي في خط الرقعة تكون أعلى الحرف، فهي التي تفرق بين الزاي والراء، ولا تكون أسفل الحرف ولا داخله.","ow":["ليست أسفل الحرف.","","لا تكون النقطة داخل الحرف.","للزاي نقطة وليست بلا نقطة."]},
  {"q":"الراء والزاي المتصلان بما قبلهما يُرسمان:","o":["بسنّ ووصلة صاعدة","بدون سنّ وبوصلة نازلة","بدون وصلة","بسنّ ووصلة أفقية"],"a":1,"why":"الراء والزاي المتصلان بما قبلهما يُرسمان بدون سنّ وبوصلة نازلة، أي نصل الحرف السابق بهما بخط ينزل.","ow":["السنّ والوصلة الصاعدة ليست طريقة رسمهما.","","يتصلان بوصلة، فليس بدون وصلة.","الوصلة الأفقية ليست طريقة رسمهما."]},
  {"q":"يستقر الراء في خط الرقعة على:","o":["السطر","تحت السطر","فوق السطر","نصف السطر"],"a":0,"why":"يستقر الراء في خط الرقعة على السطر ولا ينزل تحته، بخلاف النسخ الذي ينزل فيه جزء منها تحت السطر.","ow":["","لا ينزل تحت السطر في الرقعة.","لا يرتفع فوق السطر.","لا يكون في منتصف السطر."]},
  {"q":"في خط النسخ ينزل جزء من الراء:","o":["فوق السطر","تحت السطر","على السطر","لا ينزل"],"a":1,"why":"في خط النسخ ينزل جزء من الراء تحت السطر، أما في الرقعة فتستقر الراء على السطر، وهذا من الفروق بين الخطين.","ow":["الراء لا ينزل فوق السطر.","","في الرقعة تكون على السطر وليس في النسخ.","ينزل جزء من الراء في النسخ."]},
  {"q":"الراء في كلمة <b>الشورى</b> بخط الرقعة:","o":["متصلة بالواو","منفصلة عن الواو","محذوفة","مزخرفة"],"a":0,"why":"في كلمة الشورى الراء متصلة بالواو التي قبلها بوصلة نازلة، فهي ليست منفصلة عنها ولا محذوفة.","ow":["","الراء متصلة بما قبلها.","الراء لا تُحذف.","الراء في الرقعة ليست مزخرفة."]},
  {"q":"الراء في كلمة <b>تدبير</b> بخط الرقعة موضعها:","o":["في البدء","في الوسط","في آخر الكلمة","غير موجودة"],"a":2,"why":"الراء في كلمة تدبير في آخر الكلمة، لأن آخر حرف في الكلمة هو الراء، وقد اتصلت بالياء قبلها.","ow":["ليست في البدء، فالكلمة تبدأ بالتاء.","ليست في الوسط، بل في آخر الكلمة.","","الراء موجودة في الكلمة وليست غير موجودة."]},
  {"q":"الزاي في كلمة <b>العزيز</b> عليها:","o":["نقطة أعلاها","نقطتان","ثلاث نقاط","لا شيء"],"a":0,"why":"الزاي في كلمة العزيز عليها نقطة واحدة أعلاها، وهذه النقطة هي التي تفرقها عن الراء.","ow":["","ليس عليها نقطتان.","ليس عليها ثلاث نقاط.","عليها نقطة وليست بلا شيء."]},
  {"q":"الحرفان اللذان يتشابهان في الشكل ويفرق بينهما النقطة:","o":["الراء والزاي","الباء والتاء","السين والصاد","الدال والذال"],"a":0,"why":"الراء والزاي تتشابهان في الشكل ويفرق بينهما النقطة أعلى الزاي، وهما موضوع الدرس.","ow":["","الباء والتاء تفرق بينهما نقطة أسفل وأخرى نقطتان أعلى.","السين والصاد ليستا الحرفين المقصودين.","الدال والذال يفرق بينهما نقطة لكن ليستا موضوع الدرس."]},
  {"q":"أي الحرفين عليه نقطة في الرقعة؟","o":["الراء","الزاي","كلاهما","لا أحد"],"a":1,"why":"الزاي هي التي عليها نقطة في الرقعة، أما الراء فلا نقطة عليها، وهذا هو الفرق الوحيد بين الحرفين.","ow":["الراء ليس عليها نقطة.","","الزاي وحدها عليها نقطة.","يوجد حرف عليه نقطة وهو الزاي."]},
  {"q":"من طرق إتقان رسم الحرف:","o":["إهماله","إعادة كتابته وملاحظته","نسيانه","تغييره"],"a":1,"why":"من طرق إتقان رسم الحرف أن ألاحظ شكله ثم أرسمه وأعيد كتابته مرات عديدة حتى أتقنه وأحسّن خطي.","ow":["إهمال الحرف يضعف الخط.","","نسيان الحرف لا يتقنه.","تغيير الحرف يغير الكلمة."]},
  {"q":"يتميز خط الرقعة عن النسخ في الراء بأنه:","o":["أكثر ترتيبًا على السطر","ينزل تحت السطر","بحلية","غير منقوط"],"a":0,"why":"خط الرقعة أكثر ترتيبًا على السطر، فالراء تستقر عليه ولا تنزل تحته كما في النسخ، وهذا ما يميزه.","ow":["","النزول تحت السطر في النسخ وليس في الرقعة.","الحلية في النسخ وليست في الرقعة.","الراء حرف غير منقوط، وهذا ليس ما يميز الرقعة عن النسخ."]},
  {"q":"الراء بلا نقطة، والزاي:","o":["بنقطة أعلاها","بنقطتين","بلا نقطة","بنقطة أسفلها"],"a":0,"why":"الراء بلا نقطة، أما الزاي فنقطتها أعلاها، وهذا هو الفرق بين الحرفين، وإذا نسيت النقطة تغيّرت الكلمة.","ow":["","لا يوجد نقطتان فوق الزاي.","للزاي نقطة وليست بلا نقطة.","النقطة تكون أعلى الزاي وليست أسفلها."]},
  {"q":"العبارة: الزاي هي الراء مع نقطة أعلاها.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالزاي هي الراء مع نقطة أعلاها، وهذا هو الفرق الوحيد بينهما في الرسم.","ow":["","العبارة صحيحة، فالنقطة هي الفرق."]},
  {"q":"العبارة: ينزل جزء من الراء تحت السطر في خط الرقعة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالراء في الرقعة تستقر على السطر ولا ينزل جزء منها تحته، أما في النسخ فينزل جزء منها.","ow":["في الرقعة لا ينزل جزء منها تحت السطر.",""]},
  {"q":"العبارة: يُرسم الراء المتصل بما قبله بدون سنّ.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالراء المتصل بما قبله يُرسم بدون سنّ ويتصل بوصلة نازلة في خط الرقعة.","ow":["","العبارة صحيحة، فلا سنّ في الراء المتصلة."]},
  {"q":"العبارة: نقطة الزاي أسفل الحرف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فنقطة الزاي أعلى الحرف وليست أسفله، وبهذه النقطة تتميز الزاي عن الراء في الرقعة.","ow":["النقطة أعلى الزاي وليست أسفلها.",""]},
  {"q":"العبارة: الراء والزاي منفردين خط مائل نحو اليسار.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالراء والزاي منفردين خط مائل نحو اليسار، وهكذا يُرسمان في الرقعة.","ow":["","العبارة صحيحة، فالميل نحو اليسار."]},
];
window.BANK['a7']['a7-3-7'] = [
  {"q":"من صفات الخطيب:","o":["الخجل","التردد","الفصاحة والبيان","قلة الثقافة"],"a":2,"why":"الفصاحة والبيان من صفات الخطيب، فهو يتكلم بوضوح وبلاغة، أما الخجل والتردد وقلة الثقافة فتضعفه.","ow":["الخجل يضعف الخطيب.","التردد يضعف الخطيب.","","قلة الثقافة تضعف الخطيب، والمطلوب سعة الثقافة."]},
  {"q":"أي الآتي صفة يحتاجها الخطيب؟","o":["سعة الثقافة","الصمت","الضعف","الإهمال"],"a":0,"why":"سعة الثقافة من صفات الخطيب لأنها تعطيه مادة غنية يتكلم بها. أما الصمت والضعف والإهمال فليست صفات مطلوبة.","ow":["","الصمت لا يناسب الخطيب.","الضعف لا يناسب الخطيب.","الإهمال لا يناسب الخطيب."]},
  {"q":"أي الآتي صفة مطلوبة في مظهر الخطيب؟","o":["المظهر غير اللائق","المظهر اللائق","تجنب التفاعل","الارتباك"],"a":1,"why":"من صفات الخطيب المظهر اللائق، فيظهر أمام الجمهور بهيئة حسنة. أما المظهر غير اللائق والارتباك فمرفوضان.","ow":["المظهر غير اللائق يضعف الخطيب.","","تجنب التفاعل يخالف صفة القدرة على التفاعل مع الجمهور.","الارتباك يضعف الخطيب."]},
  {"q":"من مميزات الخطبة:","o":["التوسع في موضوعات كثيرة","التركيز على موضوع واحد","عدم ترتيب الأفكار","الابتداء بكلام ممل"],"a":1,"why":"من مميزات الخطبة التركيز على موضوع واحد، فتكون الخطبة واضحة وقوية، ولا نتوسع في موضوعات كثيرة تشتتها.","ow":["التوسع في موضوعات كثيرة يشتت الخطبة.","","عدم ترتيب الأفكار يضعف الخطبة.","الابتداء بكلام ممل يخالف الاستهلال الشائق."]},
  {"q":"تبدأ الخطبة بـ:","o":["خاتمة","جملة شائقة وجذابة","اعتذار","صمت"],"a":1,"why":"تبدأ الخطبة بجملة شائقة وجذابة تشد انتباه السامعين، وهذا من مميزاتها، أما الخاتمة فتأتي في آخرها.","ow":["الخاتمة تكون في آخر الخطبة.","","الاعتذار ليس من مميزات بداية الخطبة.","الصمت لا يبدأ به الخطيب."]},
  {"q":"يستدل الخطيب للإقناع بـ:","o":["القرآن والحديث والأمثلة","الشائعات","الصمت","الغضب"],"a":0,"why":"يستدل الخطيب بالقرآن الكريم والحديث الشريف والأمثلة ليقنع السامعين بكلامه ويقوي حجته أمام الجمهور.","ow":["","الشائعات ليست دليلًا صحيحًا يُقنع به.","الصمت لا يقنع الجمهور بشيء.","الغضب لا يقنع الجمهور ويضعف الخطبة."]},
  {"q":"من الأساليب اللغوية في الخطبة:","o":["النداء","الحذف فقط","الصمت","الرسم"],"a":0,"why":"من الأساليب اللغوية في الخطبة أسلوب النداء، مثل: أيها الإخوة، وهو يشدّ انتباه السامعين.","ow":["","الحذف فقط ليس هو أسلوب الخطبة.","الصمت ليس أسلوبًا لغويًا.","الرسم ليس أسلوبًا لغويًا."]},
  {"q":"تحريك الرأس يمينًا ويسارًا يدل على:","o":["الموافقة","النفي","الغضب","الفرح"],"a":1,"why":"تحريك الرأس يمينًا ويسارًا يدل على النفي، وهي إشارة جسدية تدعم الكلام وقت الإلقاء.","ow":["الموافقة تكون بهز الرأس لأعلى ولأسفل.","","الغضب يدل عليه تقطيب الجبين.","الفرح يدل عليه الابتسام."]},
  {"q":"هز الرأس لأعلى ولأسفل يدل على:","o":["النفي","الغضب","الموافقة","النهي"],"a":2,"why":"هز الرأس لأعلى ولأسفل يدل على الموافقة، وهي إشارة جسدية تدعم الكلام عند الإلقاء.","ow":["النفي يكون بتحريك الرأس يمينًا ويسارًا.","الغضب يدل عليه تقطيب الجبين.","","النهي يدل عليه تحريك السبابة."]},
  {"q":"تقطيب الجبين يدل على:","o":["الفرح","الموافقة","النفي","الغضب"],"a":3,"why":"تقطيب الجبين يدل على الغضب، وهو من إشارات الجسد والوجه التي تدعم الإلقاء وتعبّر عن المعنى.","ow":["الفرح يدل عليه الابتسام.","الموافقة تدل عليها هز الرأس لأعلى ولأسفل.","النفي يدل عليه تحريك الرأس يمينًا ويسارًا.",""]},
  {"q":"تحريك السبابة يدل على:","o":["النهي","الفرح","الموافقة","الارتياح"],"a":0,"why":"تحريك السبابة يدل على النهي، وهي إشارة جسدية تساعد في الإلقاء وتوضيح المعنى للجمهور.","ow":["","الفرح يدل عليه الابتسام.","الموافقة تدل عليها هز الرأس لأعلى ولأسفل.","الارتياح يدل عليه الابتسام وانفراج الأسارير."]},
  {"q":"الابتسام وانفراج الأسارير يدلان على:","o":["الغضب","الارتياح والفرح","النفي","النهي"],"a":1,"why":"الابتسام وانفراج الأسارير يدلان على الارتياح والفرح، وهي إشارات جسدية في الإلقاء.","ow":["الغضب يدل عليه تقطيب الجبين.","","النفي يدل عليه تحريك الرأس يمينًا ويسارًا.","النهي يدل عليه تحريك السبابة."]},
  {"q":"الوقفة في الحديث تقابل في الكتابة:","o":["الألوان","علامات الترقيم","العنوان","الصور"],"a":1,"why":"الوقفة في الحديث تقابل علامات الترقيم في الكتابة، مثل النقطة والفاصلة، فهي تفصل بين الجمل والأفكار.","ow":["الألوان لا تقابل الوقفة.","","العنوان لا يقابل الوقفة.","الصور لا تقابل الوقفة."]},
  {"q":"عند الانتقال إلى موضوع رئيسي جديد تكون الوقفة:","o":["أقصر","أطول","معدومة","مثل غيرها"],"a":1,"why":"عند الانتقال إلى موضوع رئيسي جديد تكون الوقفة أطول، لأنها تفصل بين فكرتين كبيرتين.","ow":["الوقفة الأقصر تكون بين جملتين من الفكرة نفسها.","","لا بد من وقفة عند الانتقال لموضوع جديد.","الوقفة تختلف باختلاف الموضع، فليست مثل غيرها."]},
  {"q":"تُعبّأ الاستمارة بمعلومات:","o":["في نموذج محدد لغرض معين","بلا نموذج","للتسلية","دون هدف"],"a":0,"why":"تُعبّأ الاستمارة بمعلومات في نموذج محدد لغرض معين، مثل طلب وظيفة أو عضوية نادٍ أو تسجيل.","ow":["","الاستمارة لها نموذج محدد.","الاستمارة لها غرض وليست للتسلية.","الاستمارة لها هدف معين."]},
  {"q":"العبارة: الجرأة والثقة من صفات الخطيب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجرأة والثقة من صفات الخطيب، فيواجه الجمهور بقوة ولا يخجل ولا يتردد.","ow":["","العبارة صحيحة، فالثقة صفة أساسية للخطيب."]},
  {"q":"العبارة: تحريك الرأس يمينًا ويسارًا يدل على الموافقة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فتحريك الرأس يمينًا ويسارًا يدل على النفي، أما الموافقة فبهز الرأس لأعلى ولأسفل.","ow":["تحريك الرأس يمينًا ويسارًا يدل على النفي وليس الموافقة.",""]},
  {"q":"العبارة: من عناصر الاستمارة توقيع المسؤول.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن عناصر الاستمارة توقيع المسؤول مع العنوان والإرشادات والبيانات.","ow":["","العبارة صحيحة، فتوقيع المسؤول عنصر من عناصرها."]},
  {"q":"العبارة: في الخطبة نتوسع في موضوعات متعددة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالخطبة نركز فيها على موضوع واحد دون التوسع في موضوعات متعددة تشتتها.","ow":["التوسع في موضوعات متعددة يخالف مميزات الخطبة.",""]},
  {"q":"العبارة: الاستمارة قد تكون ورقية أو إلكترونية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالاستمارة قد تكون ورقية أو إلكترونية، وقد تُملأ عن طريق رابط أو رمز استجابة.","ow":["","العبارة صحيحة، فالإلكترونية موجودة."]},
];
window.BANK['a7']['a7-3-8'] = [
  {"q":"مرادف كلمة <b>الحلم</b>:","o":["الأمل","الخوف","النوم","الظلام"],"a":0,"why":"الحلم هو الأمل، وهو مرادفه في نص آبار الدمام، فالمرادف كلمة قريبة في المعنى، وليس الخوف ولا النوم.","ow":["","الخوف ليس قريبًا من معنى الحلم.","النوم ليس معنى الحلم هنا.","الظلام ليس مرادف الحلم."]},
  {"q":"مرادف كلمة <b>الدفين</b>:","o":["الظاهر","القريب","المختفي","الجميل"],"a":2,"why":"الدفين هو الشيء المدفون أي المختفي تحت الأرض، فمرادفه المختفي، وهو عكس الظاهر وليس قريبًا منه.","ow":["الظاهر ضد الدفين.","القريب ليس مرادف الدفين.","","الجميل ليس مرادف الدفين."]},
  {"q":"مرادف <b>الجيولوجيا</b>:","o":["علم الأرض","علم النجوم","علم الحيوان","علم النبات"],"a":0,"why":"الجيولوجيا علم الأرض، أي العلم الذي يدرس طبقات الأرض وصخورها وما فيها، وليس علم النجوم ولا الحيوان.","ow":["","علم النجوم هو الفلك.","علم الحيوان هو علم الأحياء الحيوانية.","علم النبات هو علم النباتات."]},
  {"q":"مرادف <b>طياتها</b>:","o":["ثناياها","أعلاها","أطرافها","ظاهرها"],"a":0,"why":"طياتها معناها ثناياها أي ما بداخلها وما تحويه، كما نقول طيات الثوب أي أجزاؤه الداخلية.","ow":["","أعلاها ليس مرادف طياتها.","أطرافها ليست مرادف طياتها.","ظاهرها عكس طياتها."]},
  {"q":"مرادف <b>امتطوا</b>:","o":["نزلوا","ركبوا","ذهبوا","وقفوا"],"a":1,"why":"امتطوا معناها ركبوا، كما نقول امتطى الفرس أي ركبه، وهي عكس نزلوا ولا تعني ذهبوا أو وقفوا.","ow":["نزلوا عكس ركبوا.","","ذهبوا ليست مرادف امتطوا.","وقفوا ليست مرادف امتطوا."]},
  {"q":"يُقصد بـ <b>الذهب الأسود</b>:","o":["الفحم","الحديد","النفط","الذهب"],"a":2,"why":"الذهب الأسود هو النفط، لأن لونه أسود وقيمته كبيرة كالذهب، وهي تسمية مجازية وليست المقصود بها الفحم.","ow":["الفحم أسود لكنه ليس المقصود في النص.","الحديد معدن آخر وليس الذهب الأسود.","","الذهب معدن أصفر وليس الذهب الأسود."]},
  {"q":"الضد هو الكلمة التي:","o":["قريبة في المعنى","تعاكس معنى كلمة أخرى","متشابهة في الحروف","محذوفة"],"a":1,"why":"الضد هو الكلمة التي تعاكس معنى كلمة أخرى، مثل رضيت وغضبت، أما المرادف فمعناه قريب.","ow":["القريبة في المعنى هي المرادف.","","التشابه في الحروف ليس هو الضد.","الكلمة المحذوفة ليست الضد."]},
  {"q":"المرادف هو كلمة:","o":["قريبة في المعنى","مضادة في المعنى","بلا معنى","جمع"],"a":0,"why":"المرادف هو كلمة تقارب معنى كلمة أخرى، مثل الحلم والأمل، أما الكلمة المضادة في المعنى فهي الضد.","ow":["","المضادة في المعنى هي الضد.","الكلمة التي لا معنى لها ليست مرادفًا.","الجمع ليس هو المرادف."]},
  {"q":"نفهم معنى الكلمة من:","o":["سياق الجملة","عدد حروفها","لونها","مكانها في الصفحة"],"a":0,"why":"نفهم معنى الكلمة من سياق الجملة، أي الجملة التي جاءت فيها الكلمة، فنرجع إلى النص ونفهم المعنى منه.","ow":["","عدد الحروف لا يحدد المعنى.","اللون لا علاقة له بالمعنى.","مكان الكلمة في الصفحة لا يحدد معناها."]},
  {"q":"عمر بئر الدمام رقم 7 حوالي:","o":["عشرين عامًا","سبعين عامًا","مئتي عام","خمسين عامًا"],"a":1,"why":"عمر بئر الدمام رقم سبعة حوالي سبعين عامًا كما ذكر النص، وهي أول بئر نجح فيها استخراج النفط.","ow":["عشرون عامًا ليست عمرها في النص.","","مئتا عام ليست عمرها في النص.","خمسون عامًا ليست عمرها في النص."]},
  {"q":"يتكوّن جبل طويق من الصخر:","o":["الناري","الرملي","الجيري الصلب","الطيني"],"a":2,"why":"يتكون جبل طويق من الصخر الجيري الصلب كما ذكر النص، وليس من الصخر الناري ولا الرملي ولا الطيني.","ow":["الصخر الناري ليس المذكور.","الصخر الرملي ليس المذكور.","","الصخر الطيني ليس المذكور."]},
  {"q":"سُمّي جبل طويق بهذا الاسم لأنه يشبه:","o":["الطوق","الهرم","السيف","الجدار"],"a":0,"why":"سُمّي جبل طويق بذلك لأنه يشبه الطوق، فهو يحيط بصحراء نجد كما يحيط الطوق بالرقبة.","ow":["","الهرم ليس شبه الجبل في سبب التسمية.","السيف ليس شبه الجبل في سبب التسمية.","الجدار ليس شبه الجبل في سبب التسمية."]},
  {"q":"يحيط جبل طويق بصحراء:","o":["نجد","الدهناء","النفود","الربع الخالي"],"a":0,"why":"يحيط جبل طويق بصحراء نجد، ولذلك شُبّه بالطوق الذي يحيط بالرقبة، وليس بالدهناء ولا النفود.","ow":["","الدهناء ليست التي يحيط بها طويق.","النفود ليست التي يحيط بها طويق.","الربع الخالي ليس الذي يحيط به طويق."]},
  {"q":"طول جبل طويق حوالي:","o":["80 كم","800 كم","8 كم","1550 كم"],"a":1,"why":"يمتد جبل طويق مسافة حوالي 800 كم كما ذكر النص، فهو جبل طويل جدًا يحيط بصحراء نجد.","ow":["80 كم أقل بكثير من طوله.","","8 كم أقل بكثير من طوله.","1550 كم ليست طوله في النص."]},
  {"q":"ارتفاع جبل السروات عن سطح البحر:","o":["1170 مترًا","1550 مترًا","3666 مترًا","800 متر"],"a":2,"why":"ارتفاع جبل السروات عن سطح البحر 3666 مترًا، وهو أعلى بكثير من جبل طويق الذي يبلغ حوالي 1170 مترًا.","ow":["1170 مترًا هو ارتفاع طويق.","1550 مترًا ليست ارتفاع السروات.","","800 متر ليست ارتفاع السروات."]},
  {"q":"العبارة: مرادف <b>الدفين</b> هو المختفي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالدفين هو الشيء المدفون المختفي، فمرادفه المختفي، وهما متقاربان في المعنى.","ow":["","العبارة صحيحة، فالدفين والمختفي متقاربان."]},
  {"q":"العبارة: الذهب الأسود يقصد به الفحم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالذهب الأسود يُقصد به النفط وليس الفحم، فهو لقب للنفط لقيمته الكبيرة.","ow":["الذهب الأسود هو النفط وليس الفحم.",""]},
  {"q":"العبارة: جبل طويق أعلى من جبل السروات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فجبل السروات أعلى من جبل طويق، فارتفاع السروات 3666 مترًا وطويق 1170 مترًا.","ow":["طويق ليس أعلى، فالسروات هو الأعلى.",""]},
  {"q":"العبارة: يتكوّن جبل السروات من الصخر الناري.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة بحسب جدول المقارنة في الدرس، فجبل السروات يتكوّن من الصخر الناري وطويق من الجيري.","ow":["","العبارة صحيحة وفق ما ذكره جدول المقارنة بين الجبلين."]},
  {"q":"العبارة: جبل طويق من المعالم الطبيعية في المملكة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجبل طويق من أشهر المعالم الطبيعية في المملكة العربية السعودية ويحيط بصحراء نجد.","ow":["","العبارة صحيحة، فهو معلم جغرافي معروف."]},
];

window.BANK_U = window.BANK_U || {};
window.BANK_U["a7"] = [{"name":"الوحدة ١: القيم الإسلامية","lessons":[["a7-1-1","المذكر والمؤنث"],["a7-1-2","الأمر"],["a7-1-3","رسم همزة الوصل"],["a7-1-4","تكوينات خط الرقعة"],["a7-1-5","النكرة والمعرفة"],["a7-1-6","المبتدأ والخبر"],["a7-1-7","مهارات القراءة وفهم النص"],["a7-1-8","مهارات الحوار وكتابة النهاية"]]},{"name":"الوحدة ٢: الأعلام","lessons":[["a7-2-1","المفرد والمثنى"],["a7-2-2","الأفعال الناسخة (كان وأخواتها)"],["a7-2-3","الاستفهام"],["a7-2-4","رسم همزة القطع"],["a7-2-5","رسم حرف الألف بخط الرقعة"],["a7-2-6","مهارات الحوار وكتابته"],["a7-2-7","معاني المفردات وفهم النص"]]},{"name":"الوحدة ٣: الوطن","lessons":[["a7-3-1","الجمع السالم (المذكر والمؤنث) وملحقاته"],["a7-3-2","جمع التكسير"],["a7-3-3","النداء"],["a7-3-4","الحروف الناسخة"],["a7-3-5","رسم التاء المفتوحة والتاء المربوطة"],["a7-3-6","رسم حرفي (الراء والزاي) بخط الرقعة"],["a7-3-7","إلقاء خطبة وطنية وتعبئة الاستمارة"],["a7-3-8","المرادفات وفهم النص"]]}];
